#!/usr/bin/env python3
"""Shared durable IO helpers for runtest reports and delivery artifacts."""

from collections import Counter
from collections.abc import Mapping as MappingABC
from datetime import datetime, timedelta, timezone
import contextlib
import json
import os
from pathlib import Path
import re
import threading
from typing import Any, Mapping, Sequence
import uuid


__all__ = [
    "GATE_VERSION",
    "SCHEMA_VERSION",
    "ReportFormatError",
    "SchemaVersionError",
    "atomic_write_json",
    "atomic_write_text",
    "build_artifact_retention_metadata",
    "build_report",
    "derive_report_summary",
    "redact_paths",
    "validate_manifest_schema",
    "validate_schema",
]

_ABSOLUTE_PATH_START = r"(?:(?<![A-Za-z0-9_.\\/-])|(?<=file://))"
_UNIX_HOME_RE = re.compile(
    _ABSOLUTE_PATH_START
    + r"/(?:Users|home)/[^/\\\s\"'<>:,;()\[\]{}]+"
)
_ROOT_HOME_RE = re.compile(
    _ABSOLUTE_PATH_START + r"/root(?=$|[/\\\s\"'<>:,;()\[\]{}])"
)
_BUILD_AGENT_RE = re.compile(
    _ABSOLUTE_PATH_START
    + r"/opt/build-agent(?=$|[/\\\s\"'<>:,;()\[\]{}])",
    re.IGNORECASE,
)
_WINDOWS_HOME_RE = re.compile(
    r"(?<![A-Za-z0-9_])(?:[A-Z]:[\\/])Users[\\/]"
    r"[^/\\\s\"'<>:,;()\[\]{}]+",
    re.IGNORECASE,
)
_WINDOWS_ABSOLUTE_RE = re.compile(
    r"(?<![A-Za-z0-9_])[A-Z]:[\\/][^\s\"'<>|:,;()\[\]{}]+",
    re.IGNORECASE,
)
_CLAUDE_TMP_RE = re.compile(
    _ABSOLUTE_PATH_START
    + r"/tmp/claude-[^/\\\s\"'<>:,;()\[\]{}]+"
)
_DOCKER_SOCKET_RE = re.compile(
    _ABSOLUTE_PATH_START
    + r"(?:unix://)?(?:"
    r"(?:/private)?/(?:var/)?run/docker\.sock"
    r"|/(?:Users|home)/[^/\\\s\"'<>:,;()\[\]{}]+"
    r"(?:/[^/\\\s\"'<>:,;()\[\]{}]+)*/"
    r"docker(?:-cli)?\.sock"
    r")",
    re.IGNORECASE,
)
_DOCKER_NPIPE_RE = re.compile(
    r"npipe:/+\./pipe/docker_engine",
    re.IGNORECASE,
)
_PRIVATE_PATH_RE = re.compile(
    _ABSOLUTE_PATH_START
    + r"/(?:"
    r"private(?=$|[/\\\s\"'<>:,;()\[\]{}])"
    r"(?:/[^/\\\s\"'<>:,;()\[\]{}]+)*"
    r"|var/folders(?:/[^/\\\s\"'<>:,;()\[\]{}]+)*"
    r")"
)

SCHEMA_VERSION = "1.0"
GATE_VERSION = "1.0"


class SchemaVersionError(ValueError):
    """Raised when a runtest artifact is not safe for the current reader."""


class ReportFormatError(ValueError):
    """Raised when report details cannot produce trustworthy aggregate metrics."""


def validate_schema(report: Mapping[str, Any]) -> Mapping[str, Any]:
    """Validate and return a report using the current schema contract."""

    if not isinstance(report, MappingABC):
        raise SchemaVersionError("report must be a JSON object")
    expected_versions = {
        "schema_version": SCHEMA_VERSION,
        "gate_version": GATE_VERSION,
    }
    for field, expected in expected_versions.items():
        actual = report.get(field)
        if actual != expected:
            raise SchemaVersionError(
                f"unsupported {field}: expected {expected!r}, got {actual!r}"
            )
    return report


def _required_string(mapping: Mapping[str, Any], field: str) -> str:
    value = mapping.get(field)
    if not isinstance(value, str) or not value.strip():
        raise SchemaVersionError(f"manifest {field} must be a non-empty string")
    return value


def validate_manifest_schema(manifest: Mapping[str, Any]) -> Mapping[str, Any]:
    """Validate the minimum complete runtest evidence manifest contract."""

    validate_schema(manifest)
    if manifest.get("report_type") != "runtest_manifest":
        raise SchemaVersionError("manifest report_type must be 'runtest_manifest'")
    for field in (
        "run_id",
        "finished_at",
        "expected_runner",
        "status",
        "stream_jsonl",
        "verdict",
    ):
        _required_string(manifest, field)
    try:
        datetime.fromisoformat(
            _required_string(manifest, "finished_at").replace("Z", "+00:00")
        )
    except ValueError as exc:
        raise SchemaVersionError("manifest finished_at must be ISO-8601") from exc

    source_session = manifest.get("source_session")
    if not isinstance(source_session, MappingABC):
        raise SchemaVersionError("manifest source_session must be an object")
    for field in (
        "source_session_path",
        "source_session_name",
        "source_session_type",
        "source_session_identifier",
    ):
        _required_string(source_session, field)
    sequence = source_session.get("source_session_sequence")
    if sequence is not None and (isinstance(sequence, bool) or not isinstance(sequence, int)):
        raise SchemaVersionError(
            "manifest source_session_sequence must be an integer or null"
        )

    verdict = _required_string(manifest, "verdict")
    session_ids = manifest.get("session_ids")
    if not isinstance(session_ids, list):
        raise SchemaVersionError("manifest session_ids must be a list")
    if verdict == "PASS" and not session_ids:
        raise SchemaVersionError("PASS manifest session_ids must be non-empty")
    if any(not isinstance(item, str) or not item.strip() for item in session_ids):
        raise SchemaVersionError("manifest session_ids must contain non-empty strings")
    if len(set(session_ids)) != len(session_ids):
        raise SchemaVersionError("manifest session_ids must be unique")

    mappings = manifest.get("session_mappings")
    if not isinstance(mappings, list):
        raise SchemaVersionError("manifest session_mappings must be a list")
    if verdict == "PASS" and not mappings:
        raise SchemaVersionError("PASS manifest session_mappings must be non-empty")
    copied_paths: set[str] = set()
    mapped_ids: set[str] = set()
    stream_reference = _required_string(manifest, "stream_jsonl")
    for mapping in mappings:
        if not isinstance(mapping, MappingABC):
            raise SchemaVersionError("manifest session_mapping must be an object")
        session_id = _required_string(mapping, "session_id")
        copied_path = _required_string(mapping, "copied_native_jsonl")
        if copied_path == stream_reference:
            raise SchemaVersionError("manifest stream_jsonl must differ from native transcript")
        if session_id in mapped_ids:
            raise SchemaVersionError("manifest session_mappings must have unique session_id")
        if copied_path in copied_paths:
            raise SchemaVersionError("manifest session_mappings must have unique native paths")
        mapped_ids.add(session_id)
        copied_paths.add(copied_path)
    if mapped_ids != set(session_ids):
        raise SchemaVersionError(
            "manifest session_mappings session_id values must match session_ids"
        )

    reasons = manifest.get("reason_codes")
    if not isinstance(reasons, list) or any(
        not isinstance(reason, str) or not reason for reason in reasons
    ):
        raise SchemaVersionError("manifest reason_codes must be a list of non-empty strings")
    return manifest


def _code_value(value: Any, *, field: str) -> str:
    candidate = getattr(value, "value", value)
    if not isinstance(candidate, str) or not candidate:
        raise ReportFormatError(f"{field} must be a non-empty string")
    return candidate


def derive_report_summary(
    details: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Derive stable aggregate metrics exclusively from per-session details."""

    verdict_counts: Counter[str] = Counter()
    reason_counts: Counter[str] = Counter()
    rerun_required = not details

    for detail in details:
        verdict = _code_value(detail.get("verdict"), field="verdict")
        verdict_counts[verdict] += 1
        rerun_required = rerun_required or verdict != "PASS"

        reasons = detail.get("reason_codes", ())
        if not isinstance(reasons, (list, tuple)):
            raise ReportFormatError("reason_codes must be a list or tuple")
        for reason in reasons:
            reason_counts[_code_value(reason, field="reason_code")] += 1

    return {
        "verdict_counts": dict(sorted(verdict_counts.items())),
        "reason_counts": dict(sorted(reason_counts.items())),
        "rerun_required": rerun_required,
    }


def build_report(details: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    """Build a current, self-consistent report from immutable detail inputs."""

    detail_records = [dict(detail) for detail in details]
    return {
        "schema_version": SCHEMA_VERSION,
        "gate_version": GATE_VERSION,
        "details": detail_records,
        **derive_report_summary(detail_records),
    }


def _utc_timestamp(value: datetime) -> str:
    return value.astimezone(timezone.utc).isoformat(timespec="seconds").replace(
        "+00:00", "Z"
    )


def build_artifact_retention_metadata(
    artifact_paths: Sequence[str | os.PathLike[str]],
    *,
    created_at: datetime,
    retention_days: int,
    known_roots: Mapping[str | os.PathLike[str], str] | None = None,
    policy: str = "audit",
) -> dict[str, Any]:
    """Build deterministic, redacted time-based artifact retention metadata."""

    if created_at.utcoffset() is None:
        raise ValueError("created_at must be timezone-aware")
    if retention_days < 0:
        raise ValueError("retention_days must be non-negative")

    path_strings = [os.fspath(path) for path in artifact_paths]
    redacted_paths = redact_paths(path_strings, known_roots=known_roots)
    retain_until = created_at + timedelta(days=retention_days)
    return {
        "policy": policy,
        "created_at": _utc_timestamp(created_at),
        "retention_days": retention_days,
        "retain_until": _utc_timestamp(retain_until),
        "artifacts": sorted(redacted_paths),
    }


def _fsync_directory(directory: Path) -> None:
    """Persist a directory entry update after an atomic replacement."""

    # Windows does not support opening a directory with os.open for fsync.
    # The file itself was already flushed above; os.replace remains atomic.
    if os.name == "nt":
        return
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
    directory_fd = os.open(directory, flags)
    try:
        os.fsync(directory_fd)
    finally:
        os.close(directory_fd)


def atomic_write_text(
    path: str | os.PathLike[str],
    content: str,
    *,
    encoding: str = "utf-8",
) -> None:
    """Durably replace ``path`` with text written through a sibling temp file."""

    destination = Path(path)
    temporary = destination.parent / (
        f".{destination.name}.{os.getpid()}.{threading.get_ident()}."
        f"{uuid.uuid4().hex}.tmp"
    )
    try:
        with temporary.open("x", encoding=encoding) as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, destination)
        _fsync_directory(destination.parent)
    finally:
        try:
            temporary.unlink()
        except FileNotFoundError:
            pass


def atomic_write_json(path: str | os.PathLike[str], value: Any) -> None:
    """Durably write deterministic, human-readable UTF-8 JSON."""

    content = json.dumps(value, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    atomic_write_text(path, content)


def _known_root_replacements(
    known_roots: Mapping[str | os.PathLike[str], str] | None,
) -> tuple[tuple[re.Pattern[str], str], ...]:
    replacements: list[tuple[str, str]] = []
    for root, replacement in (known_roots or {}).items():
        root_text = os.fspath(root)
        if not isinstance(root_text, str):
            raise TypeError("known root paths must resolve to strings")
        normalized_root = root_text.rstrip("/\\")
        if not (
            normalized_root.startswith("/")
            or re.match(r"^[A-Za-z]:[\\/]", normalized_root)
        ):
            raise ValueError(f"known root must be absolute: {root_text!r}")
        replacements.append((normalized_root, replacement))

    compiled: list[tuple[re.Pattern[str], str]] = []
    for root_text, replacement in sorted(
        replacements, key=lambda item: len(item[0]), reverse=True
    ):
        flags = re.IGNORECASE if re.match(r"^[A-Za-z]:[\\/]", root_text) else 0
        compiled.append(
            (
                re.compile(
                    rf"{_ABSOLUTE_PATH_START}{re.escape(root_text)}"
                    rf"(?=$|[\\/\s\"'<>:,;()\[\]{{}}])",
                    flags,
                ),
                replacement,
            )
        )
    return tuple(compiled)


def _redact_text(
    text: str, known_roots: tuple[tuple[re.Pattern[str], str], ...]
) -> str:
    for pattern, replacement in known_roots:
        text = pattern.sub(lambda _: replacement, text)
    text = _DOCKER_NPIPE_RE.sub("<DOCKER_SOCKET>", text)
    text = _DOCKER_SOCKET_RE.sub("<DOCKER_SOCKET>", text)
    text = _WINDOWS_HOME_RE.sub("<HOME>", text)
    text = _WINDOWS_ABSOLUTE_RE.sub("<HOST_PATH>", text)
    text = _UNIX_HOME_RE.sub("<HOME>", text)
    text = _ROOT_HOME_RE.sub("<HOME>", text)
    text = _BUILD_AGENT_RE.sub("<BUILD_AGENT>", text)
    text = _CLAUDE_TMP_RE.sub("<CLAUDE_TMP>", text)
    return _PRIVATE_PATH_RE.sub("<PRIVATE_PATH>", text)


def _redact_value(
    value: Any, known_roots: tuple[tuple[re.Pattern[str], str], ...]
) -> Any:
    if isinstance(value, str):
        return _redact_text(value, known_roots)
    if isinstance(value, dict):
        redacted: dict[Any, Any] = {}
        for key, item in value.items():
            redacted_key = (
                _redact_text(key, known_roots) if isinstance(key, str) else key
            )
            if redacted_key in redacted:
                raise ReportFormatError("path redaction produced a duplicate key")
            redacted[redacted_key] = _redact_value(item, known_roots)
        return redacted
    if isinstance(value, list):
        return [_redact_value(item, known_roots) for item in value]
    if isinstance(value, tuple):
        return tuple(_redact_value(item, known_roots) for item in value)
    return value


def redact_paths(
    value: Any,
    *,
    known_roots: Mapping[str | os.PathLike[str], str] | None = None,
) -> Any:
    """Recursively redact host-specific absolute paths from JSON-like values."""

    replacements = _known_root_replacements(known_roots)
    return _redact_value(value, replacements)


# =========================================================================== #
# SECTION: runtest_verdict
