#!/usr/bin/env python3
"""Deterministic, fail-closed verdicts for runtest report artifacts."""

from dataclasses import dataclass, field
from datetime import datetime, timezone
from enum import Enum
import json
from pathlib import Path
import re
import shlex
from typing import Sequence


SCHEMA_VERSION = "1.0"
GATE_VERSION = "1.0"

RUNNER_NAME_RE = re.compile(
    r"^(?:run[_-]?tests?|runtest|test)(?:\.(?:sh|bash|py|bat|ps1|cmd))?$",
    re.IGNORECASE,
)
# JS/TS 测试运行器直接可执行名(常见于 `./node_modules/.bin/vitest run`、`npx jest`、
# `node node_modules/.bin/vitest run`)。这些是无歧义的测试命令；不纳入会导致 stored gate
# 漏认「直接跑 vitest/jest 收尾」的会话,把其后正常编辑误判成 EDIT_AFTER_LAST_TEST。
JS_TEST_RUNNER_NAMES = frozenset(
    {
        "vitest",
        "jest",
        "mocha",
        "jasmine",
        "ava",
        "cypress",
        "playwright",
        "karma",
        "tap",
        "tape",
        "qunit",
        "uvu",
    }
)


class Verdict(str, Enum):
    """Release decision for one captured runtest session."""

    PASS = "PASS"
    INCOMPLETE_TRACE = "INCOMPLETE_TRACE"
    INFRA_ERROR = "INFRA_ERROR"
    INSUFFICIENT_SCOPE = "INSUFFICIENT_SCOPE"
    STALE_TEST_PASS = "STALE_TEST_PASS"
    NO_RELIABLE_TEST_EVIDENCE = "NO_RELIABLE_TEST_EVIDENCE"
    TEST_FAILED_UNRESOLVED = "TEST_FAILED_UNRESOLVED"


class ReasonCode(str, Enum):
    """Stable machine-readable explanation for a verdict."""

    MISSING_TERMINAL_RESULT = "MISSING_TERMINAL_RESULT"
    MALFORMED_JSONL = "MALFORMED_JSONL"
    TERMINAL_RESULT_ERROR = "TERMINAL_RESULT_ERROR"
    TERMINAL_RESULT_NOT_LAST = "TERMINAL_RESULT_NOT_LAST"
    DANGLING_TOOL_USE = "DANGLING_TOOL_USE"
    ORPHAN_TOOL_RESULT = "ORPHAN_TOOL_RESULT"
    DUPLICATE_TOOL_USE = "DUPLICATE_TOOL_USE"
    DUPLICATE_TOOL_RESULT = "DUPLICATE_TOOL_RESULT"
    BACKGROUND_RESULT_PENDING = "BACKGROUND_RESULT_PENDING"
    NO_TEST_ATTEMPT = "NO_TEST_ATTEMPT"
    MISSING_NATIVE_TRANSCRIPT = "MISSING_NATIVE_TRANSCRIPT"
    MISSING_RUNNER_EXIT = "MISSING_RUNNER_EXIT"
    DOCKER_DAEMON_UNAVAILABLE = "DOCKER_DAEMON_UNAVAILABLE"
    DOCKER_SOCKET_PERMISSION_DENIED = "DOCKER_SOCKET_PERMISSION_DENIED"
    CONNECTION_REFUSED = "CONNECTION_REFUSED"
    NO_SUCH_CONTAINER = "NO_SUCH_CONTAINER"
    PORT_ALREADY_ALLOCATED = "PORT_ALREADY_ALLOCATED"
    NETWORK_UNAVAILABLE = "NETWORK_UNAVAILABLE"
    COMMAND_NOT_FOUND = "COMMAND_NOT_FOUND"
    OUT_OF_MEMORY = "OUT_OF_MEMORY"
    NO_REPAIR_BETWEEN_ATTEMPTS = "NO_REPAIR_BETWEEN_ATTEMPTS"
    PARTIAL_RERUN_AFTER_FAILURE = "PARTIAL_RERUN_AFTER_FAILURE"
    EXPECTED_RUNNER_NOT_RUN = "EXPECTED_RUNNER_NOT_RUN"
    EXPECTED_RUNNER_SCOPE_FILTERED = "EXPECTED_RUNNER_SCOPE_FILTERED"
    EDIT_AFTER_LAST_TEST = "EDIT_AFTER_LAST_TEST"
    ZERO_TESTS_COLLECTED = "ZERO_TESTS_COLLECTED"
    TEST_TOOL_RESULT_ERROR = "TEST_TOOL_RESULT_ERROR"
    ERROR_COUNT_NONZERO = "ERROR_COUNT_NONZERO"
    STEP1_TIMEOUT = "STEP1_TIMEOUT"
    STEP1_PROCESS_ERROR = "STEP1_PROCESS_ERROR"
    STEP1_NO_TARGETS = "STEP1_NO_TARGETS"
    STEP1_NO_RUNNER = "STEP1_NO_RUNNER"
    STEP1_SELECTOR_NO_MATCH = "STEP1_SELECTOR_NO_MATCH"
    STEP1_EXCEPTION = "STEP1_EXCEPTION"
    STEP1_DETECTOR_UNAVAILABLE = "STEP1_DETECTOR_UNAVAILABLE"
    FAILED_COUNT_NONZERO = "FAILED_COUNT_NONZERO"
    FAILURE_OUTPUT_DETECTED = "FAILURE_OUTPUT_DETECTED"
    RUNNER_EXIT_NONZERO = "RUNNER_EXIT_NONZERO"


@dataclass(frozen=True)
class VerdictResult:
    """One deterministic verdict and all reasons observed while evaluating it."""

    verdict: Verdict
    reason_codes: tuple[ReasonCode, ...]
    selected_attempt: AttemptEvidence | None = None

    def to_dict(self) -> dict[str, object]:
        selected = self.selected_attempt
        selected_payload: dict[str, object] | None = None
        if selected is not None:
            selected_payload = {
                "tool_use_id": selected.tool_use_id,
                "command": selected.command,
                "result_text": selected.result_text,
                "exit_codes": list(selected.exit_codes),
                "use_sequence": selected.use_sequence,
                "result_sequence": selected.result_sequence,
            }
        return {
            "schema_version": SCHEMA_VERSION,
            "gate_version": GATE_VERSION,
            "verdict": self.verdict.value,
            "reason_codes": [reason.value for reason in self.reason_codes],
            "selected_attempt": selected_payload,
        }


@dataclass(frozen=True)
class AttemptEvidence:
    """Immutable selected runner evidence safe for downstream reporting."""

    tool_use_id: str
    command: str
    result_text: str
    exit_codes: tuple[int, ...]
    use_sequence: int
    result_sequence: int | None


@dataclass
class TestAttempt:
    """One real runner invocation and its paired tool result."""

    tool_use_id: str
    command: str
    use_sequence: int
    result_sequence: int | None = None
    result_text: str = ""
    exit_codes: list[int] = field(default_factory=list)
    failed_count_nonzero: bool = False
    failure_output_detected: bool = False
    error_count_nonzero: bool = False
    zero_tests_collected: bool = False
    tool_result_is_error: bool = False

    def evidence(self) -> AttemptEvidence:
        return AttemptEvidence(
            tool_use_id=self.tool_use_id,
            command=self.command,
            result_text=self.result_text,
            exit_codes=tuple(self.exit_codes),
            use_sequence=self.use_sequence,
            result_sequence=self.result_sequence,
        )


def _message_content(payload: dict) -> list[dict]:
    message = payload.get("message")
    if not isinstance(message, dict):
        return []
    content = message.get("content")
    if not isinstance(content, list):
        return []
    return [item for item in content if isinstance(item, dict)]


def is_test_command(command: str) -> bool:
    """Return whether a shell command actually invokes a test runner."""

    for segment in re.split(r"&&|\|\||;|\n", command):
        segment = segment.strip()
        if not segment:
            continue
        try:
            tokens = shlex.split(segment)
        except ValueError:
            tokens = segment.split()
        while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
            tokens.pop(0)
        if not tokens:
            continue
        if tokens[0] == "env":
            tokens.pop(0)
            while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
                tokens.pop(0)
        while tokens and Path(tokens[0]).name.lower() in {"sudo", "command"}:
            tokens.pop(0)
        if tokens and Path(tokens[0]).name.lower() in {"timeout", "gtimeout"}:
            tokens.pop(0)
            while tokens and (tokens[0].startswith("-") or re.match(r"^\d+[smhd]?$", tokens[0])):
                tokens.pop(0)
        if not tokens:
            continue

        executable = Path(tokens[0].replace("\\", "/")).name.lower()
        args = tokens[1:]
        if RUNNER_NAME_RE.fullmatch(executable):
            return True
        # 直接调用的 JS/TS 测试运行器: `vitest run` / `./node_modules/.bin/jest`
        if executable in JS_TEST_RUNNER_NAMES:
            return True
        # 包装器 `npx/bunx/pnpm dlx/yarn dlx <runner>`: 取首个非选项参数判定
        if executable in {"npx", "bunx", "dlx"}:
            wrapped = [a for a in args if not a.startswith("-")]
            if wrapped and Path(wrapped[0].replace("\\", "/")).name.lower() in JS_TEST_RUNNER_NAMES:
                return True
        # `node/bun/deno <path>/vitest run`: 取被运行脚本的 basename 判定
        if executable in {"node", "nodejs", "bun", "deno"}:
            wrapped = [a for a in args if not a.startswith("-")]
            if wrapped and Path(wrapped[0].replace("\\", "/")).name.lower() in JS_TEST_RUNNER_NAMES:
                return True
            if executable in {"bun", "deno"} and args[:1] == ["test"]:
                return True
        if re.search(r"(?:^|[_-])tests?(?:\.exe)?$", executable, re.IGNORECASE):
            return True
        if executable in {"bash", "sh", "zsh", "source", "."}:
            script_args = [arg for arg in args if not arg.startswith("-")]
            if script_args and RUNNER_NAME_RE.fullmatch(
                Path(script_args[0].replace("\\", "/")).name
            ):
                return True
        if executable in {"python", "python3", "py"}:
            if len(args) >= 2 and args[0] == "-m" and args[1] in {
                "pytest",
                "unittest",
            }:
                return True
            script_args = [arg for arg in args if not arg.startswith("-")]
            if script_args and RUNNER_NAME_RE.fullmatch(
                Path(script_args[0].replace("\\", "/")).name
            ):
                return True
        if executable in {"pytest", "py.test", "tox", "rspec", "phpunit", "ctest"}:
            return True
        if executable == "go" and args[:1] == ["test"]:
            return True
        if executable in {"npm", "pnpm", "yarn"} and args:
            if args[0] == "test" or (len(args) >= 2 and args[:2] == ["run", "test"]):
                return True
        if executable == "make" and any(arg == "test" for arg in args):
            return True
        if executable == "cargo" and args[:1] == ["test"]:
            return True
        if executable in {"mvn", "mvnw"} and any(arg == "test" for arg in args):
            return True
        if executable in {"gradle", "gradlew"} and any(
            arg == "test" or arg.endswith(":test") for arg in args
        ):
            return True
    return False


# --- Container/runtest startup recognition ------------------------------------
# 金标轨迹需保留「docker 启动 runtest 容器」的真实过程,而非只留最终测试结果。
# 这里只识别**真正启动/构建/管理容器**的命令,以及 setup/build 脚本;纯探查命令
# (cat/ls/grep/...)不是启动步,返回 False。测试运行命令由 is_test_command 单独负责,
# 不在此匹配(即便某命令同时含 docker,提取器也会把最终测试步单独接在链尾)。
_CONTAINER_CLIS = {"docker", "docker-compose", "podman", "nerdctl"}
_STARTUP_SCRIPT_RE = re.compile(
    r"^(?:setup|build|build[_-]?image|make[_-]?image|prepare|bootstrap|start|init)"
    r"\.(?:sh|bash)$",
    re.IGNORECASE,
)
_MAKE_STARTUP_TARGETS = {
    "setup",
    "build",
    "image",
    "images",
    "docker",
    "up",
    "compose",
}


def _strip_command_prefixes(tokens: list[str]) -> list[str]:
    """Drop leading env=VAL assignments, env/sudo/command, and timeout wrappers.

    Mirrors is_test_command's tokenizer so downstream recognizers see the real
    executable rather than a wrapper.
    """
    tokens = list(tokens)
    while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
        tokens.pop(0)
    if tokens and tokens[0] == "env":
        tokens.pop(0)
        while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
            tokens.pop(0)
    while tokens and Path(tokens[0]).name.lower() in {"sudo", "command"}:
        tokens.pop(0)
    if tokens and Path(tokens[0]).name.lower() in {"timeout", "gtimeout"}:
        tokens.pop(0)
        while tokens and (
            tokens[0].startswith("-") or re.match(r"^\d+[smhd]?$", tokens[0])
        ):
            tokens.pop(0)
    return tokens


def is_container_startup_command(command: str) -> bool:
    """Return whether a shell command is part of runtest CONTAINER startup.

    True when any segment invokes a container CLI (docker / docker-compose /
    podman / nerdctl) or runs a setup/build script (setup.sh, build_image.sh, …)
    or a make setup/build/image target. Pure inspection commands (cat/ls/grep/…)
    are not startup steps and return False.
    """
    for segment in re.split(r"&&|\|\||;|\n|\|", command):
        segment = segment.strip()
        if not segment:
            continue
        try:
            tokens = shlex.split(segment)
        except ValueError:
            tokens = segment.split()
        tokens = _strip_command_prefixes(tokens)
        if not tokens:
            continue
        executable = Path(tokens[0].replace("\\", "/")).name.lower()
        args = tokens[1:]
        if executable in _CONTAINER_CLIS:
            return True
        if _STARTUP_SCRIPT_RE.fullmatch(executable):
            return True
        if executable in {"bash", "sh", "zsh", "source", "."}:
            script_args = [arg for arg in args if not arg.startswith("-")]
            if script_args and _STARTUP_SCRIPT_RE.fullmatch(
                Path(script_args[0].replace("\\", "/")).name
            ):
                return True
        if executable in {"make", "gmake"} and any(
            arg in _MAKE_STARTUP_TARGETS for arg in args
        ):
            return True
    return False


def can_emit_current_runtime_failure(command: str) -> bool:
    """Return whether a command can produce a new runtime failure.

    Read-only inspection commands may print stale failure text from logs or source
    files; that text must not taint the current runtest session.
    """
    inspection_commands = {
        "awk",
        "cat",
        "cut",
        "echo",
        "find",
        "grep",
        "head",
        "less",
        "ls",
        "more",
        "pwd",
        "readlink",
        "rg",
        "sed",
        "stat",
        "tail",
        "type",
        "which",
    }
    for segment in re.split(r"&&|\|\||;|\n", command):
        try:
            tokens = shlex.split(segment)
        except ValueError:
            tokens = segment.split()
        while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
            tokens.pop(0)
        while tokens and Path(tokens[0]).name.lower() in {"env", "sudo", "command"}:
            tokens.pop(0)
            while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
                tokens.pop(0)
        if not tokens:
            continue
        executable = Path(tokens[0].replace("\\", "/")).name.lower()
        if executable in inspection_commands or executable == "cd":
            continue
        return True
    return False


# --- persisted-output truncation recovery ------------------------------------
# When a Bash tool result is very large, the Claude CLI truncates the inline
# content to a short preview wrapped in <persisted-output> and writes the FULL
# output to disk (toolUseResult.persistedOutputPath). The trailing
# `RUNNER_EXIT=<code>` marker and the pytest summary line live at the very end,
# so the preview loses them and a genuinely-green run is misjudged
# MISSING_RUNNER_EXIT. Recover the full text from the persisted file when it is
# reachable; fail closed (keep the preview) when it is not.

_PERSISTED_OUTPUT_MARKER = "<persisted-output>"
_PERSISTED_READ_CAP = 8 * 1024 * 1024  # 8 MiB
_PERSISTED_EDGE_BYTES = 512 * 1024  # head+tail kept when a file exceeds the cap


def _persisted_output_path(payload: dict) -> Path | None:
    tool_use_result = payload.get("toolUseResult")
    if not isinstance(tool_use_result, dict):
        return None
    raw = tool_use_result.get("persistedOutputPath")
    if not isinstance(raw, str) or not raw:
        return None
    return Path(raw)


def _read_persisted_output(path: Path) -> str | None:
    try:
        if not path.is_file():
            return None
        size = path.stat().st_size
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            if size <= _PERSISTED_READ_CAP:
                return handle.read()
            # Keep the head (collection/plugins) and the tail (summary +
            # RUNNER_EXIT); both matter for the deterministic contract.
            head = handle.read(_PERSISTED_EDGE_BYTES)
            handle.seek(max(0, size - _PERSISTED_EDGE_BYTES))
            tail = handle.read()
        return f"{head}\n...\n{tail}"
    except OSError:
        return None


def _resolve_full_result_text(payload: dict, result_text: str) -> str:
    """Return the complete tool-result text, recovering persisted truncations.

    Only rewrites when the inline text is a <persisted-output> preview AND the
    persisted file is readable on this machine; otherwise the original preview
    is returned so the verdict stays fail-closed.
    """

    if _PERSISTED_OUTPUT_MARKER not in result_text:
        return result_text
    path = _persisted_output_path(payload)
    if path is None:
        return result_text
    full_text = _read_persisted_output(path)
    if full_text is None:
        return result_text
    return full_text


def _result_exit_codes(payload: dict, result_text: str) -> list[int]:
    exit_codes = [
        int(match.group(1))
        for match in re.finditer(
            r"(?im)^\s*(?:RUNNER_EXIT|EXIT|EXIT_CODE)\s*[=:]\s*(-?\d+)\s*$",
            result_text,
        )
    ]
    exit_codes.extend(
        int(match.group(1))
        for match in re.finditer(r"(?i)<exit_code>\s*(-?\d+)\s*</exit_code>", result_text)
    )
    tool_use_result = payload.get("toolUseResult")
    if not isinstance(tool_use_result, dict):
        return exit_codes
    direct_exit = tool_use_result.get("exitCode")
    if isinstance(direct_exit, int):
        exit_codes.append(direct_exit)
    task = tool_use_result.get("task")
    if isinstance(task, dict) and isinstance(task.get("exitCode"), int):
        exit_codes.append(task["exitCode"])
    return exit_codes


def _background_task_id(payload: dict, result_text: str) -> str | None:
    tool_use_result = payload.get("toolUseResult")
    if isinstance(tool_use_result, dict):
        task_id = tool_use_result.get("backgroundTaskId")
        if isinstance(task_id, str) and task_id:
            return task_id
        task = tool_use_result.get("task")
        if isinstance(task, dict):
            task_id = task.get("task_id")
            if isinstance(task_id, str) and task_id:
                return task_id
    match = re.search(
        r"Command running in background with ID:\s*([^\s.]+)|"
        r"<task_id>\s*([^<\s]+)\s*</task_id>",
        result_text,
        re.IGNORECASE,
    )
    if not match:
        return None
    return match.group(1) or match.group(2)


def _background_completed(payload: dict, result_text: str) -> bool:
    tool_use_result = payload.get("toolUseResult")
    if isinstance(tool_use_result, dict):
        task = tool_use_result.get("task")
        if isinstance(task, dict) and task.get("status") == "completed":
            return True
    return bool(
        re.search(r"<status>\s*completed\s*</status>", result_text, re.IGNORECASE)
        and re.search(
            r"<retrieval_status>\s*success\s*</retrieval_status>",
            result_text,
            re.IGNORECASE,
        )
    )


def _runner_scope_arguments(arguments: Sequence[str]) -> list[str]:
    scope_arguments: list[str] = []
    skip_redirect_target = False
    for argument in arguments:
        if skip_redirect_target:
            skip_redirect_target = False
            continue
        if argument in {"|", "|&"}:
            break
        if (
            re.fullmatch(r"\d*(?:>|>>|<|<<|<>|>&|<&)", argument)
            or argument == "&>"
        ):
            skip_redirect_target = True
            continue
        if re.match(r"^(?:\d*(?:>|>>|<|<<|<>|>&|<&)|&>).+", argument):
            continue
        scope_arguments.append(argument)
    return scope_arguments


def test_scope_key(command: str) -> str:
    """Return a stable full/partial scope key for one test command."""

    for segment in re.split(r"&&|\|\||;|\n", command):
        try:
            tokens = shlex.split(segment)
        except ValueError:
            tokens = segment.split()
        while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
            tokens.pop(0)
        if not tokens:
            continue
        executable = Path(tokens[0].replace("\\", "/")).name.lower()
        runner_index: int | None = None
        if RUNNER_NAME_RE.fullmatch(executable) or re.search(
            r"(?:^|[_-])tests?(?:\.exe)?$", executable, re.IGNORECASE
        ):
            runner_index = 0
        elif executable in {"bash", "sh", "zsh", "source", ".", "python", "python3"}:
            for index, token in enumerate(tokens[1:], start=1):
                if RUNNER_NAME_RE.fullmatch(
                    Path(token.replace("\\", "/")).name
                ):
                    runner_index = index
                    break
        if runner_index is None:
            continue
        runner_name = Path(tokens[runner_index].replace("\\", "/")).name.lower()
        trailing = _runner_scope_arguments(tokens[runner_index + 1 :])
        if trailing:
            return f"partial:runner:{runner_name}:{' '.join(trailing).lower()}"
        return f"runner:{runner_name}"
    normalized = " ".join(command.lower().split())
    if re.search(r"\bpytest\b", normalized):
        if re.search(r"(?:^|\s)(?:[^\s]+\.py(?:::|\s|$)|[^\s]*tests?/[^\s]+)", normalized):
            return f"partial:{normalized}"
        return "framework:pytest:full"
    if re.search(r"\bgo\s+test\b", normalized):
        return "framework:go:full" if "./..." in normalized else f"partial:{normalized}"
    return f"command:{normalized}"


def test_scope_covers(failed_command: str, candidate_command: str) -> bool:
    """Return whether a passing candidate covers the earlier failed scope."""

    failed_scope = test_scope_key(failed_command)
    candidate_scope = test_scope_key(candidate_command)
    if failed_scope == candidate_scope:
        return True
    if not failed_scope.startswith("partial:"):
        return False
    if candidate_scope.startswith("runner:"):
        if failed_scope.startswith("partial:runner:"):
            failed_runner = failed_scope.split(":", 3)[2]
            return candidate_scope == f"runner:{failed_runner}"
        return True
    if candidate_scope == "framework:pytest:full":
        return "pytest" in failed_scope or "unittest" in failed_scope
    if candidate_scope == "framework:go:full":
        return "go test" in failed_scope
    return False


def _normalized_runner_path(value: str) -> str:
    return value.replace("\\", "/").strip().removeprefix("./").rstrip("/").lower()


def _command_invokes_expected_runner(command: str, expected_runner: str) -> bool:
    expected = _normalized_runner_path(expected_runner)
    if not expected:
        return False
    for segment in re.split(r"&&|\|\||;|\n", command):
        try:
            tokens = shlex.split(segment)
        except ValueError:
            tokens = segment.split()
        while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
            tokens.pop(0)
        if tokens and Path(tokens[0]).name.lower() == "env":
            tokens.pop(0)
            while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
                tokens.pop(0)
        while tokens and Path(tokens[0]).name.lower() in {"sudo", "command"}:
            tokens.pop(0)
        if tokens and Path(tokens[0]).name.lower() in {"timeout", "gtimeout"}:
            tokens.pop(0)
            while tokens and (
                tokens[0].startswith("-") or re.match(r"^\d+[smhd]?$", tokens[0])
            ):
                tokens.pop(0)
        if not tokens:
            continue
        executable = Path(tokens[0].replace("\\", "/")).name.lower()
        candidates = [tokens[0]]
        if executable in {"bash", "sh", "zsh", "source", ".", "python", "python3", "py"}:
            candidates = [token for token in tokens[1:] if not token.startswith("-")]
        for candidate in candidates:
            normalized = _normalized_runner_path(candidate)
            if normalized == expected or normalized.endswith(f"/{expected}"):
                return True
    return False


def _command_filters_expected_runner(command: str, expected_runner: str) -> bool:
    expected = _normalized_runner_path(expected_runner)
    scope_flags = {
        "-f",
        "-g",
        "-k",
        "-m",
        "-p",
        "-t",
        "-x",
        "--exclude",
        "--file",
        "--files",
        "--filter",
        "--focus",
        "--grep",
        "--include",
        "--match",
        "--only",
        "--package",
        "--packages",
        "--part",
        "--pattern",
        "--rerun",
        "--select",
        "--shard",
        "--spec",
        "--suite",
        "--test",
        "--test-file",
        "--test_file",
        "--tests",
    }
    for segment in re.split(r"&&|\|\||;|\n", command):
        try:
            tokens = shlex.split(segment)
        except ValueError:
            tokens = segment.split()
        while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
            tokens.pop(0)
        if tokens and Path(tokens[0]).name.lower() == "env":
            tokens.pop(0)
            while tokens and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", tokens[0]):
                tokens.pop(0)
        while tokens and Path(tokens[0]).name.lower() in {"sudo", "command"}:
            tokens.pop(0)
        if tokens and Path(tokens[0]).name.lower() in {"timeout", "gtimeout"}:
            tokens.pop(0)
            while tokens and (
                tokens[0].startswith("-") or re.match(r"^\d+[smhd]?$", tokens[0])
            ):
                tokens.pop(0)
        if not tokens:
            continue
        executable = Path(tokens[0].replace("\\", "/")).name.lower()
        if executable in {"bash", "sh", "zsh", "source", ".", "python", "python3", "py"}:
            candidates = tokens[1:]
            runner_index = next(
                (
                    index
                    for index, candidate in enumerate(candidates)
                    if not candidate.startswith("-")
                    and (
                        _normalized_runner_path(candidate) == expected
                        or _normalized_runner_path(candidate).endswith(f"/{expected}")
                    )
                ),
                None,
            )
            if runner_index is None:
                continue
            trailing = _runner_scope_arguments(candidates[runner_index + 1 :])
        elif (
            _normalized_runner_path(tokens[0]) == expected
            or _normalized_runner_path(tokens[0]).endswith(f"/{expected}")
        ):
            trailing = _runner_scope_arguments(tokens[1:])
        else:
            continue
        for argument in trailing:
            if argument == "--" or argument.startswith(">"):
                continue
            flag = argument.split("=", 1)[0].lower()
            if flag in scope_flags or not argument.startswith("-"):
                return True
    return False


def infra_reason_codes(
    result_text: str, exit_codes: Sequence[int]
) -> set[ReasonCode]:
    """Classify shared infrastructure failures from one tool result."""

    reasons: set[ReasonCode] = set()
    if re.search(
        r"Cannot connect to the Docker daemon|"
        r"Is the docker daemon running\??|"
        r"error during connect.*docker",
        result_text,
        re.IGNORECASE | re.DOTALL,
    ):
        reasons.add(ReasonCode.DOCKER_DAEMON_UNAVAILABLE)
    if re.search(
        r"permission denied.*(?:docker(?: daemon)? socket|docker\.sock)|"
        r"docker(?: daemon)? socket.*permission denied",
        result_text,
        re.IGNORECASE | re.DOTALL,
    ):
        reasons.add(ReasonCode.DOCKER_SOCKET_PERMISSION_DENIED)
    if re.search(r"\bconnection refused\b", result_text, re.IGNORECASE):
        reasons.add(ReasonCode.CONNECTION_REFUSED)
    if re.search(r"\bNo such container\b", result_text, re.IGNORECASE):
        reasons.add(ReasonCode.NO_SUCH_CONTAINER)
    if re.search(
        r"\bport is already allocated\b|\baddress already in use\b|"
        r"\bbind for\b.*\bfailed\b",
        result_text,
        re.IGNORECASE,
    ):
        reasons.add(ReasonCode.PORT_ALREADY_ALLOCATED)
    if re.search(
        r"\bfailed to create network\b|"
        r"\bfailed to set up container networking\b|"
        r"\bnetwork is unreachable\b|"
        r"\bcould not resolve host\b|"
        r"\btemporary failure in name resolution\b",
        result_text,
        re.IGNORECASE,
    ):
        reasons.add(ReasonCode.NETWORK_UNAVAILABLE)
    if re.search(r"\bcommand not found\b", result_text, re.IGNORECASE) or 127 in exit_codes:
        reasons.add(ReasonCode.COMMAND_NOT_FOUND)
    if re.search(
        r"\bOOMKilled\b|\bout of memory\b|\bcannot allocate memory\b",
        result_text,
        re.IGNORECASE,
    ) or 137 in exit_codes:
        reasons.add(ReasonCode.OUT_OF_MEMORY)
    return reasons


# Explicit framework/build failure markers (count-free structural signals).
# Deliberately NO bare `\bERROR\b` — pip prints `ERROR: pip's dependency resolver...`
# as a benign warning, so a bare ERROR would false-positive (see _strip / report_run_passed
# notes). Every alternation here is an unambiguous "a run failed" line across frameworks.
_FAILURE_SIGNAL_RE = re.compile(
    r"^\s*FAILED(?:\s|$)"                       # pytest line-leading FAILED
    r"|\bBUILD FAILURE\b"                       # maven
    r"|\bBUILD FAILED\b"                        # gradle / ant / xcodebuild
    r"|Traceback \(most recent call last\):"    # python traceback
    r"|\bFailures\s*:\s*[1-9]\d*\b"             # maven/junit `Failures: N`
    r"|^---\s+FAIL:"                            # go test
    r"|^FAIL\b"                                 # go / jest package-summary line
    r"|^ok\s+\S+\s+\S*\bFAIL\b"                 # (defensive) mixed go summary
    r"|^panic:"                                 # go panic
    r"|\btest result:\s*FAILED\b"              # rust cargo
    r"|^\s*>?\s*Task\s+\S+\s+FAILED\b"         # gradle `> Task :x FAILED`
    r"|^(?:FAILURES|ERRORS)!"                   # phpunit banner
    r"|^\s*Failed!\s*$"                         # dotnet `Failed!`
    r"|^Error:\s+Command failed with exit code" # generic runner wrapper
    r"|\bAssertionError\b"                      # unittest/pytest assertion
    r"|^E\s+assert\b"                           # pytest assert body line
    r"|^E\s+\w*(?:Error|Exception)\b",          # pytest error body line
    re.IGNORECASE | re.MULTILINE,
)


def has_failure_output(result_text: str) -> bool:
    """Return whether output contains an explicit framework/build failure."""

    return bool(_FAILURE_SIGNAL_RE.search(result_text))


def has_zero_test_output(result_text: str) -> bool:
    """Return whether a runner completed without executing any tests."""

    if not re.search(
        r"\bno tests? ran\b|"
        r"\bran 0 tests?\b|"
        r"\b0 tests? (?:collected|passed)\b|"
        r"\b0 passed\b|"
        r"\[no test files\]",
        result_text,
        re.IGNORECASE,
    ):
        return False
    # 多套件运行里,单个空测试二进制/空 crate 会打印 `0 passed`——典型是 Rust
    # `test result: ok. 0 passed; 0 failed`,或 monorepo 里某个无用例的子包。但只要**同一份
    # 输出**里存在任一**非零**通过计数(`33 passed` / `passed=159` 等),整轮就确实跑过测试,
    # 不能因某个空套件的 `0 passed` 判成「零测试」→ 误删健康的全绿插入块。仅当通篇找不到任何
    # 非零通过证据时,才判零测试(真正的 `No tests collected` / `ran 0 tests`)。
    has_positive_pass = any(
        int(match.group(1).replace(",", "")) > 0
        for match in re.finditer(
            r"(?<![A-Za-z0-9_=])(\d[\d,]*)\s+(?:tests?\s+)?passed\b(?!\s*[:=])",
            result_text,
            re.IGNORECASE,
        )
    ) or any(
        int(match.group(1).replace(",", "")) > 0
        for match in re.finditer(
            r"\bpass(?:ed)?[ \t]*=[ \t]*(\d[\d,]*)", result_text, re.IGNORECASE
        )
    ) or any(
        # 自建/多语言测试台的标签式通过汇总:`Passed:  39`(冒号+值),mocha `39 passing`。
        # FB9B53 这类 Go 多包运行里空包打印 `[no test files]`,而真实通过数走 `Passed: 39` 标签形——
        # 若不认这个形态,正向通过证据就被漏掉,空包的 `[no test files]` 反而把全绿运行判成零测试→误删。
        int(match.group(1).replace(",", "")) > 0
        for match in re.finditer(
            r"(?im)^\s*Passed[ \t]*:[ \t]*(\d[\d,]*)\b", result_text
        )
    ) or any(
        int(match.group(1).replace(",", "")) > 0
        for match in re.finditer(
            r"\b(\d[\d,]*)\s+passing\b", result_text, re.IGNORECASE
        )
    )
    return not has_positive_pass


def _parse_event_timestamp(value: object) -> float | None:
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return float(value)
    if not isinstance(value, str) or not value.strip():
        return None
    text = value.strip()
    try:
        return float(text)
    except ValueError:
        pass
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.utcoffset() is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.timestamp()


def _load_ordered_native_payloads(paths: Sequence[Path]) -> tuple[list[dict], bool]:
    entries: list[tuple[float | None, int, int, dict]] = []
    malformed = False
    for path_index, path in enumerate(paths):
        with path.open("r", encoding="utf-8", errors="replace") as handle:
            for line_index, raw_line in enumerate(handle):
                if not raw_line.strip():
                    continue
                try:
                    payload = json.loads(raw_line)
                except json.JSONDecodeError:
                    malformed = True
                    continue
                if not isinstance(payload, dict) or not _message_content(payload):
                    continue
                entries.append(
                    (
                        _parse_event_timestamp(payload.get("timestamp")),
                        path_index,
                        line_index,
                        payload,
                    )
                )
    if entries and all(timestamp is not None for timestamp, *_rest in entries):
        entries.sort(
            key=lambda entry: (
                float(entry[0]),
                entry[1],
                entry[2],
            )
        )
    return [entry[3] for entry in entries], malformed


def evaluate_report_artifacts(
    *,
    stream_path: Path,
    native_paths: Sequence[Path] = (),
    expected_runner: str | None = None,
) -> VerdictResult:
    """Evaluate the minimum trustworthy Claude stream contract.

    A stream without a top-level terminal ``result`` is legacy or truncated data.
    It is intentionally rejected and must be rerun rather than inferred from prose.
    """

    terminal_result: dict | None = None
    last_stream_event_type: str | None = None
    malformed = False
    if stream_path.is_file():
        with stream_path.open("r", encoding="utf-8", errors="replace") as handle:
            for raw_line in handle:
                if not raw_line.strip():
                    continue
                try:
                    payload = json.loads(raw_line)
                except json.JSONDecodeError:
                    malformed = True
                    continue
                if isinstance(payload, dict):
                    last_stream_event_type = str(payload.get("type", ""))
                    if payload.get("type") == "result":
                        terminal_result = payload

    if malformed:
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.MALFORMED_JSONL,),
        )

    if terminal_result is None:
        return VerdictResult(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(ReasonCode.MISSING_TERMINAL_RESULT,),
        )

    if last_stream_event_type != "result":
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.TERMINAL_RESULT_NOT_LAST,),
        )

    if (
        terminal_result.get("is_error") is True
        or terminal_result.get("subtype") != "success"
    ):
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.TERMINAL_RESULT_ERROR,),
        )

    existing_native_paths = [
        native_path for native_path in native_paths if native_path.is_file()
    ]
    if not existing_native_paths:
        return VerdictResult(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(ReasonCode.MISSING_NATIVE_TRANSCRIPT,),
        )
    native_payloads, native_malformed = _load_ordered_native_payloads(
        existing_native_paths
    )

    pending_tool_uses: set[str] = set()
    seen_tool_uses: set[str] = set()
    tool_use_names: dict[str, str] = {}
    tool_use_commands: dict[str, str] = {}
    completed_tool_uses: set[str] = set()
    background_tool_uses: set[str] = set()
    background_task_tests: dict[str, str] = {}
    task_output_tools: dict[str, str] = {}
    pending_background_tasks: set[str] = set()
    test_tool_uses: set[str] = set()
    test_attempts: dict[str, TestAttempt] = {}
    orphan_tool_result = False
    duplicate_tool_use = False
    duplicate_tool_result = False
    infra_reasons: set[ReasonCode] = set()
    sequence = 0
    last_edit_sequence: int | None = None
    for payload in native_payloads:
        for item in _message_content(payload):
            sequence += 1
            if item.get("type") == "tool_use" and item.get("id"):
                tool_use_id = str(item["id"])
                if tool_use_id in seen_tool_uses:
                    duplicate_tool_use = True
                seen_tool_uses.add(tool_use_id)
                tool_use_names[tool_use_id] = str(item.get("name", ""))
                pending_tool_uses.add(tool_use_id)
                tool_input = item.get("input")
                if (
                    isinstance(tool_input, dict)
                    and tool_input.get("run_in_background") is True
                ):
                    background_tool_uses.add(tool_use_id)
                command = (
                    str(tool_input.get("command", ""))
                    if isinstance(tool_input, dict)
                    else ""
                )
                tool_use_commands[tool_use_id] = command
                if item.get("name") == "Bash" and is_test_command(command):
                    test_tool_uses.add(tool_use_id)
                    test_attempts[tool_use_id] = TestAttempt(
                        tool_use_id=tool_use_id,
                        command=command,
                        use_sequence=sequence,
                    )
                if item.get("name") in {
                    "Edit",
                    "Write",
                    "MultiEdit",
                    "NotebookEdit",
                }:
                    last_edit_sequence = sequence
                if item.get("name") == "TaskOutput" and isinstance(tool_input, dict):
                    task_id = tool_input.get("task_id")
                    if isinstance(task_id, str) and task_id:
                        task_output_tools[tool_use_id] = task_id
            elif item.get("type") == "tool_result" and item.get("tool_use_id"):
                tool_use_id = str(item["tool_use_id"])
                if tool_use_id in completed_tool_uses:
                    duplicate_tool_result = True
                elif tool_use_id not in pending_tool_uses:
                    orphan_tool_result = True
                else:
                    completed_tool_uses.add(tool_use_id)
                result_content = item.get("content")
                result_text = (
                    result_content
                    if isinstance(result_content, str)
                    else json.dumps(result_content, ensure_ascii=False)
                )
                result_text = _resolve_full_result_text(payload, result_text)
                tool_name = tool_use_names.get(tool_use_id)
                if tool_name == "TaskOutput" or (
                    tool_name == "Bash"
                    and can_emit_current_runtime_failure(
                        tool_use_commands.get(tool_use_id, "")
                    )
                ):
                    infra_reasons.update(
                        infra_reason_codes(
                            result_text,
                            _result_exit_codes(payload, result_text),
                        )
                    )
                related_test_id = (
                    tool_use_id if tool_use_id in test_tool_uses else None
                )
                if tool_use_id in background_tool_uses:
                    task_id = _background_task_id(payload, result_text)
                    pending_task_id = task_id or f"tool:{tool_use_id}"
                    pending_background_tasks.add(pending_task_id)
                    if task_id and tool_use_id in test_tool_uses:
                        background_task_tests[task_id] = tool_use_id
                task_output_id = task_output_tools.get(tool_use_id)
                if task_output_id:
                    related_test_id = background_task_tests.get(task_output_id)
                    if _background_completed(payload, result_text):
                        pending_background_tasks.discard(task_output_id)
                    else:
                        pending_background_tasks.add(task_output_id)
                if related_test_id:
                    attempt = test_attempts[related_test_id]
                    attempt.result_sequence = sequence
                    attempt.result_text = result_text
                    attempt.tool_result_is_error = item.get("is_error") is True
                    attempt.failed_count_nonzero = any(
                        int(match.group(1)) > 0
                        for match in re.finditer(
                            r"(?im)(?:^|[,;|][ \t]*)\b(\d+)[ \t]+failed\b",
                            result_text,
                        )
                    ) or any(
                        int(match.group(1).replace(",", "")) > 0
                        for match in re.finditer(
                            r"(?im)^[ \t]*Failed[ \t]*:[ \t]*(\d[\d,]*)\b",
                            result_text,
                        )
                    )
                    attempt.failure_output_detected = has_failure_output(result_text)
                    attempt.error_count_nonzero = any(
                        int(match.group(1)) > 0
                        for match in re.finditer(
                            r"(?im)(?:^|[,;|][ \t]*)\b(\d+)[ \t]+errors?\b",
                            result_text,
                        )
                    ) or any(
                        int(match.group(1).replace(",", "")) > 0
                        for match in re.finditer(
                            r"(?im)^[ \t]*Errors?[ \t]*:[ \t]*(\d[\d,]*)\b",
                            result_text,
                        )
                    )
                    attempt.zero_tests_collected = has_zero_test_output(result_text)
                    attempt.exit_codes = _result_exit_codes(payload, result_text)
                pending_tool_uses.discard(tool_use_id)

    if native_malformed:
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.MALFORMED_JSONL,),
        )

    if pending_background_tasks:
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.BACKGROUND_RESULT_PENDING,),
        )

    if duplicate_tool_use:
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.DUPLICATE_TOOL_USE,),
        )

    if duplicate_tool_result:
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.DUPLICATE_TOOL_RESULT,),
        )

    if orphan_tool_result:
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.ORPHAN_TOOL_RESULT,),
        )

    if pending_tool_uses:
        return VerdictResult(
            verdict=Verdict.INCOMPLETE_TRACE,
            reason_codes=(ReasonCode.DANGLING_TOOL_USE,),
        )

    if infra_reasons:
        return VerdictResult(
            verdict=Verdict.INFRA_ERROR,
            reason_codes=tuple(sorted(infra_reasons, key=lambda reason: reason.value)),
        )

    if not test_tool_uses:
        return VerdictResult(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(ReasonCode.NO_TEST_ATTEMPT,),
        )

    all_completed_attempts = [
        attempt for attempt in test_attempts.values() if attempt.result_sequence is not None
    ]
    candidate_attempts = all_completed_attempts
    if expected_runner is not None:
        expected_attempts = [
            attempt
            for attempt in all_completed_attempts
            if _command_invokes_expected_runner(attempt.command, expected_runner)
        ]
        if not expected_attempts:
            latest_attempt = max(
                all_completed_attempts,
                key=lambda attempt: attempt.result_sequence or attempt.use_sequence,
            )
            return VerdictResult(
                verdict=Verdict.INSUFFICIENT_SCOPE,
                reason_codes=(ReasonCode.EXPECTED_RUNNER_NOT_RUN,),
                selected_attempt=latest_attempt.evidence(),
            )
        candidate_attempts = expected_attempts
    latest_attempt = max(
        candidate_attempts,
        key=lambda attempt: attempt.result_sequence or attempt.use_sequence,
    )

    # 唯一成功判据（用户口径）：最近一次测试运行**没有任何错误的测试**且 **runner exit==0**。
    # 之前基于 scope 过滤 / 零测试 / edit-after-test(过时) / 跨尝试未修复 / 部分重跑 的额外
    # 结构性闸门经常误报失败，已按需求移除——只保留「有失败信号 或 退出码非零 → 失败」。
    if not latest_attempt.exit_codes:
        # 无法确认 exit==0（判官已强化提示词要求每次都打印 RUNNER_EXIT=）；查无退出码即视为证据不足。
        return VerdictResult(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(ReasonCode.MISSING_RUNNER_EXIT,),
            selected_attempt=latest_attempt.evidence(),
        )

    failure_reasons: list[ReasonCode] = []
    if latest_attempt.tool_result_is_error:
        failure_reasons.append(ReasonCode.TEST_TOOL_RESULT_ERROR)
    if latest_attempt.failed_count_nonzero:
        failure_reasons.append(ReasonCode.FAILED_COUNT_NONZERO)
    if latest_attempt.failure_output_detected:
        failure_reasons.append(ReasonCode.FAILURE_OUTPUT_DETECTED)
    if latest_attempt.error_count_nonzero:
        failure_reasons.append(ReasonCode.ERROR_COUNT_NONZERO)
    if any(exit_code != 0 for exit_code in latest_attempt.exit_codes):
        failure_reasons.append(ReasonCode.RUNNER_EXIT_NONZERO)
    if failure_reasons:
        return VerdictResult(
            verdict=Verdict.TEST_FAILED_UNRESOLVED,
            reason_codes=tuple(failure_reasons),
            selected_attempt=latest_attempt.evidence(),
        )

    return VerdictResult(
        verdict=Verdict.PASS,
        reason_codes=(),
        selected_attempt=latest_attempt.evidence(),
    )


# =========================================================================== #
# SECTION: clean_runtest_evidence
# =========================================================================== #
#!/usr/bin/env python3
"""Deterministically validate and clean stored OpenAI-style runtest blocks."""

import argparse
from copy import deepcopy
from dataclasses import dataclass
from datetime import datetime, timezone
from enum import Enum
import json
from pathlib import Path
import re
from typing import Any, Sequence
core_infra_reason_codes = infra_reason_codes


REPORT_SCHEMA = "runtest-evidence-cleaner-report"
SCHEMA_VERSION = "1.0"


class StoredVerdict(str, Enum):
    """Trust decision for stored test evidence in one session."""

    PASS = "PASS"
    INFRA_ERROR = "INFRA_ERROR"
    INCOMPLETE_TRACE = "INCOMPLETE_TRACE"
    NO_RELIABLE_TEST_EVIDENCE = "NO_RELIABLE_TEST_EVIDENCE"
    STALE_TEST_PASS = "STALE_TEST_PASS"
    TEST_FAILED_UNRESOLVED = "TEST_FAILED_UNRESOLVED"


class StoredReasonCode(str, Enum):
    """Stable machine-readable validation reason."""

    NO_TEST_BLOCK = "NO_TEST_BLOCK"
    DANGLING_TEST_TOOL_CALL = "DANGLING_TEST_TOOL_CALL"
    DANGLING_TOOL_CALL = "DANGLING_TOOL_CALL"
    ORPHAN_TOOL_RESULT = "ORPHAN_TOOL_RESULT"
    TRAILING_NON_ASSISTANT = "TRAILING_NON_ASSISTANT"
    MISSING_TERMINAL_SUMMARY = "MISSING_TERMINAL_SUMMARY"
    TERMINAL_SUMMARY_NOT_PLAIN_TEXT = "TERMINAL_SUMMARY_NOT_PLAIN_TEXT"
    BACKGROUND_RESULT_PENDING = "BACKGROUND_RESULT_PENDING"
    RETRIEVAL_TIMEOUT = "RETRIEVAL_TIMEOUT"
    MISSING_BLOCK_SUMMARY = "MISSING_BLOCK_SUMMARY"
    DOCKER_DAEMON_UNAVAILABLE = "DOCKER_DAEMON_UNAVAILABLE"
    DOCKER_SOCKET_PERMISSION_DENIED = "DOCKER_SOCKET_PERMISSION_DENIED"
    CONNECTION_REFUSED = "CONNECTION_REFUSED"
    NO_SUCH_CONTAINER = "NO_SUCH_CONTAINER"
    PORT_ALREADY_ALLOCATED = "PORT_ALREADY_ALLOCATED"
    NETWORK_UNAVAILABLE = "NETWORK_UNAVAILABLE"
    COMMAND_NOT_FOUND = "COMMAND_NOT_FOUND"
    PYTHON_NOT_FOUND = "PYTHON_NOT_FOUND"
    OUT_OF_MEMORY = "OUT_OF_MEMORY"
    FAILED_COUNT_NONZERO = "FAILED_COUNT_NONZERO"
    ERROR_COUNT_NONZERO = "ERROR_COUNT_NONZERO"
    FAILURE_OUTPUT_DETECTED = "FAILURE_OUTPUT_DETECTED"
    RUNNER_EXIT_NONZERO = "RUNNER_EXIT_NONZERO"
    MISSING_RUNNER_EXIT = "MISSING_RUNNER_EXIT"
    REPOSITORY_CD_FAILED = "REPOSITORY_CD_FAILED"
    ZERO_TESTS_COLLECTED = "ZERO_TESTS_COLLECTED"
    CONTRADICTORY_SUCCESS_CLAIM = "CONTRADICTORY_SUCCESS_CLAIM"
    TEST_COUNT_MISMATCH = "TEST_COUNT_MISMATCH"
    TEST_TOOL_RESULT_ERROR = "TEST_TOOL_RESULT_ERROR"
    EDIT_AFTER_LAST_TEST = "EDIT_AFTER_LAST_TEST"
    PARTIAL_RERUN_AFTER_FAILURE = "PARTIAL_RERUN_AFTER_FAILURE"
    DUPLICATE_TOOL_RESULT = "DUPLICATE_TOOL_RESULT"
    DUPLICATE_TOOL_CALL = "DUPLICATE_TOOL_CALL"
    NO_REPAIR_BETWEEN_ATTEMPTS = "NO_REPAIR_BETWEEN_ATTEMPTS"


# 「结构性(broken-trajectory)」原因码子集——收尾补测时可绕过它们(需求:结构性闸门不拦终态
# 补测)。只含收尾总结形态/尾节点非 assistant 这类**纯结构**问题;绝不含正确性码(测试真失败/
# 零测试/假成功/计数不符/编辑后陈旧)、配对码(悬空/孤儿/重复——那些交给 cleaner 修)、或 INFRA。
STRUCTURAL_REASON_CODES = frozenset({
    StoredReasonCode.MISSING_BLOCK_SUMMARY,
    StoredReasonCode.MISSING_TERMINAL_SUMMARY,
    StoredReasonCode.TERMINAL_SUMMARY_NOT_PLAIN_TEXT,
    StoredReasonCode.TRAILING_NON_ASSISTANT,
})

# 「正确性/INFRA」原因码——**永不**为终态补测放行(否则就会插入一个失败/伪造/环境坏掉的测试)。
# 这是终态候选闸门豁免的硬底线:只要残留里有其中任何一个,就拒插,无论它是不是插入前就存在。
HARD_BLOCK_REASON_CODES = frozenset({
    StoredReasonCode.FAILED_COUNT_NONZERO,
    StoredReasonCode.ERROR_COUNT_NONZERO,
    StoredReasonCode.FAILURE_OUTPUT_DETECTED,
    StoredReasonCode.RUNNER_EXIT_NONZERO,
    StoredReasonCode.ZERO_TESTS_COLLECTED,
    StoredReasonCode.CONTRADICTORY_SUCCESS_CLAIM,
    StoredReasonCode.TEST_COUNT_MISMATCH,
    StoredReasonCode.EDIT_AFTER_LAST_TEST,
    StoredReasonCode.PARTIAL_RERUN_AFTER_FAILURE,
    StoredReasonCode.NO_REPAIR_BETWEEN_ATTEMPTS,
    StoredReasonCode.TEST_TOOL_RESULT_ERROR,
    # INFRA / 环境
    StoredReasonCode.DOCKER_DAEMON_UNAVAILABLE,
    StoredReasonCode.DOCKER_SOCKET_PERMISSION_DENIED,
    StoredReasonCode.CONNECTION_REFUSED,
    StoredReasonCode.NO_SUCH_CONTAINER,
    StoredReasonCode.PORT_ALREADY_ALLOCATED,
    StoredReasonCode.NETWORK_UNAVAILABLE,
    StoredReasonCode.COMMAND_NOT_FOUND,
    StoredReasonCode.PYTHON_NOT_FOUND,
    StoredReasonCode.OUT_OF_MEMORY,
    StoredReasonCode.REPOSITORY_CD_FAILED,
    StoredReasonCode.BACKGROUND_RESULT_PENDING,
    StoredReasonCode.RETRIEVAL_TIMEOUT,
})


@dataclass(frozen=True)
class TestBlock:
    """One assistant(tool call) -> tool result -> assistant block."""

    start_index: int
    end_index: int
    result_index: int
    tool_call_id: str
    command: str
    result_text: str
    exit_codes: tuple[int, ...]
    result_is_error: bool


@dataclass(frozen=True)
class SessionValidation:
    """Validation outcome and all parsed test blocks."""

    verdict: StoredVerdict
    reason_codes: tuple[StoredReasonCode, ...]
    blocks: tuple[TestBlock, ...]


@dataclass(frozen=True)
class CleanResult:
    """Messages produced by a cleanup action."""

    messages: list[dict[str, Any]]
    changed: bool
    validation_before: SessionValidation
    removed_block_ranges: tuple[tuple[int, int], ...] = ()
    removed_orphan_indices: tuple[int, ...] = ()
    removed_extra_tool_result_indices: tuple[int, ...] = ()
    rewritten_summary_indices: tuple[int, ...] = ()
    removed_summary_indices: tuple[int, ...] = ()
    removed_runtest_intro_indices: tuple[int, ...] = ()
    quarantine_required: bool = False


def _tool_arguments(tool_call: dict[str, Any]) -> dict[str, Any] | None:
    function = tool_call.get("function")
    if not isinstance(function, dict):
        return None
    arguments = function.get("arguments")
    if isinstance(arguments, str):
        try:
            arguments = json.loads(arguments)
        except json.JSONDecodeError:
            return None
    if not isinstance(arguments, dict):
        return None
    return arguments


def _tool_command(tool_call: dict[str, Any]) -> str | None:
    function = tool_call.get("function")
    if not isinstance(function, dict) or str(function.get("name", "")).lower() != "bash":
        return None
    arguments = _tool_arguments(tool_call)
    if arguments is None:
        return None
    command = arguments.get("command")
    return command if isinstance(command, str) else None


def _message_text(message: dict[str, Any]) -> str:
    content = message.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return "\n".join(
            str(item.get("text", ""))
            for item in content
            if isinstance(item, dict) and item.get("text")
        )
    return ""


def _tool_result_exit_codes(message: dict[str, Any], result_text: str) -> tuple[int, ...]:
    codes = _runner_exit_codes(result_text)

    def add_code(value: Any) -> None:
        if isinstance(value, bool):
            return
        if isinstance(value, int):
            codes.append(value)
        elif isinstance(value, str) and re.fullmatch(r"-?\d+", value.strip()):
            codes.append(int(value))

    mappings = [message]
    mappings.extend(
        value
        for key in ("metadata", "tool_result", "toolUseResult")
        if isinstance((value := message.get(key)), dict)
    )
    for mapping in mappings:
        for key in ("exit_code", "exitCode", "return_code", "returncode"):
            add_code(mapping.get(key))
    return tuple(dict.fromkeys(codes))


def _background_task_id_from_text(result_text: str) -> str | None:
    match = re.search(
        r"Command running in background with ID:\s*([^\s.]+)|"
        r"<task_id>\s*([^<\s]+)\s*</task_id>",
        result_text,
        re.IGNORECASE,
    )
    if not match:
        return None
    return match.group(1) or match.group(2)


def _background_result_index(
    messages: Sequence[dict[str, Any]], result_index: int, result_text: str
) -> int | None:
    task_id = _background_task_id_from_text(result_text)
    if task_id is None:
        return None
    last_matching_result: int | None = None
    for assistant_index in range(result_index + 1, len(messages)):
        message = messages[assistant_index]
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        for tool_call in tool_calls:
            if not isinstance(tool_call, dict):
                continue
            function = tool_call.get("function")
            if not isinstance(function, dict):
                continue
            function_name = str(function.get("name", "")).replace("_", "").lower()
            if function_name not in {"taskoutput", "bashoutput", "gettaskoutput"}:
                continue
            arguments = _tool_arguments(tool_call) or {}
            referenced_task_id = next(
                (
                    str(arguments[key])
                    for key in ("task_id", "taskId", "bash_id", "id")
                    if arguments.get(key) is not None
                ),
                "",
            )
            if referenced_task_id != task_id or not tool_call.get("id"):
                continue
            output_call_id = str(tool_call["id"])
            output_index = next(
                (
                    index
                    for index in range(assistant_index + 1, len(messages))
                    if messages[index].get("role") == "tool"
                    and str(messages[index].get("tool_call_id", "")) == output_call_id
                ),
                None,
            )
            if output_index is None:
                continue
            last_matching_result = output_index
    return last_matching_result


def _parse_blocks(messages: Sequence[dict[str, Any]]) -> list[TestBlock]:
    blocks: list[TestBlock] = []
    for index, message in enumerate(messages):
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        for tool_call in tool_calls:
            if not isinstance(tool_call, dict):
                continue
            command = _tool_command(tool_call)
            call_id = tool_call.get("id")
            if not command or not call_id or not is_test_command(command):
                continue
            result_index = next(
                (
                    later_index
                    for later_index in range(index + 1, len(messages))
                    if messages[later_index].get("role") == "tool"
                    and messages[later_index].get("tool_call_id") == call_id
                ),
                None,
            )
            if result_index is None:
                continue
            initial_result_text = _message_text(messages[result_index])
            effective_result_index = (
                _background_result_index(messages, result_index, initial_result_text)
                or result_index
            )
            cursor = effective_result_index + 1
            while cursor < len(messages) and messages[cursor].get("role") == "tool":
                cursor += 1
            end_index = (
                cursor
                if cursor < len(messages) and messages[cursor].get("role") == "assistant"
                else effective_result_index
            )
            result_text = _message_text(messages[effective_result_index])
            blocks.append(
                TestBlock(
                    start_index=index,
                    end_index=end_index,
                    result_index=effective_result_index,
                    tool_call_id=str(call_id),
                    command=command,
                    result_text=result_text,
                    exit_codes=_tool_result_exit_codes(
                        messages[effective_result_index], result_text
                    ),
                    result_is_error=bool(
                        messages[effective_result_index].get("is_error")
                    ),
                )
            )
    return blocks


def _test_call_ids(messages: Sequence[dict[str, Any]]) -> set[str]:
    call_ids: set[str] = set()
    for message in messages:
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        for tool_call in tool_calls:
            if not isinstance(tool_call, dict):
                continue
            command = _tool_command(tool_call)
            call_id = tool_call.get("id")
            if command and call_id and is_test_command(command):
                call_ids.add(str(call_id))
    return call_ids


def _all_tool_call_ids(messages: Sequence[dict[str, Any]]) -> set[str]:
    call_ids: set[str] = set()
    for message in messages:
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        for tool_call in tool_calls:
            if isinstance(tool_call, dict) and tool_call.get("id"):
                call_ids.add(str(tool_call["id"]))
    return call_ids


def _tool_commands_by_call_id(
    messages: Sequence[dict[str, Any]],
) -> dict[str, str]:
    commands: dict[str, str] = {}
    for message in messages:
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        for tool_call in tool_calls:
            if not isinstance(tool_call, dict) or not tool_call.get("id"):
                continue
            command = _tool_command(tool_call)
            if command is not None:
                commands[str(tool_call["id"])] = command
    return commands


def _tool_result_can_emit_current_failure(
    result: dict[str, Any], commands_by_call_id: dict[str, str]
) -> bool:
    command = commands_by_call_id.get(str(result.get("tool_call_id", "")))
    return command is None or can_emit_current_runtime_failure(command)


def _dangling_test_ranges(
    messages: Sequence[dict[str, Any]],
    result_ids: set[str],
    *,
    test_only: bool = True,
) -> set[tuple[int, int]]:
    ranges: set[tuple[int, int]] = set()
    for index, message in enumerate(messages):
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        all_ids = {
            str(tool_call["id"])
            for tool_call in tool_calls
            if isinstance(tool_call, dict) and tool_call.get("id")
        }
        test_ids = {
            str(tool_call["id"])
            for tool_call in tool_calls
            if isinstance(tool_call, dict)
            and tool_call.get("id")
            and (command := _tool_command(tool_call))
            and is_test_command(command)
        }
        candidate_ids = test_ids if test_only else all_ids
        if not candidate_ids - result_ids:
            continue
        end_index = index
        cursor = index + 1
        while (
            cursor < len(messages)
            and messages[cursor].get("role") == "tool"
            and str(messages[cursor].get("tool_call_id", "")) in all_ids
        ):
            end_index = cursor
            cursor += 1
        if (
            cursor < len(messages)
            and messages[cursor].get("role") == "assistant"
            and not messages[cursor].get("tool_calls")
        ):
            end_index = cursor
        ranges.add((index, end_index))
    return ranges


def _infra_reasons(
    result_text: str, exit_codes: Sequence[int] = ()
) -> set[StoredReasonCode]:
    reasons = {
        StoredReasonCode(reason.value)
        for reason in core_infra_reason_codes(result_text, exit_codes)
    }
    if (
        StoredReasonCode.COMMAND_NOT_FOUND in reasons
        and re.search(
            r"\bpython(?:3)?\s*:\s*command not found\b",
            result_text,
            re.IGNORECASE,
        )
    ):
        reasons.add(StoredReasonCode.PYTHON_NOT_FOUND)
    return reasons


def _session_infra_reasons(
    messages: Sequence[dict[str, Any]],
    allowed_indices: set[int] | None = None,
) -> set[StoredReasonCode]:
    """Return infrastructure failures from every tool result in the session.

    When allowed_indices is given, only tool results at those message indices
    are scanned (used to scope the blacklist to pipeline-inserted blocks so
    historical dev-session output cannot taint the verdict).
    """

    reasons: set[StoredReasonCode] = set()
    commands_by_call_id = _tool_commands_by_call_id(messages)
    for index, message in enumerate(messages):
        if allowed_indices is not None and index not in allowed_indices:
            continue
        if message.get("role") != "tool" or not _tool_result_can_emit_current_failure(
            message, commands_by_call_id
        ):
            continue
        result_text = _message_text(message)
        reasons.update(
            _infra_reasons(result_text, _tool_result_exit_codes(message, result_text))
        )
    return reasons


def _is_retrieval_timeout(result_text: str) -> bool:
    return bool(
        re.search(
            r"<retrieval_status>\s*(?:timeout|timed_out|error)\s*"
            r"</retrieval_status>|\bretrieval timed out\b|"
            r"\btask retrieval timed out\b|\bcommand timed out\b|"
            r"\bretrieval timeout\b",
            result_text,
            re.IGNORECASE,
        )
    )


def _session_has_retrieval_timeout(
    messages: Sequence[dict[str, Any]],
    allowed_indices: set[int] | None = None,
) -> bool:
    """A recorded retrieval timeout is incomplete evidence even if retried later."""

    return any(
        message.get("role") == "tool"
        and (allowed_indices is None or index in allowed_indices)
        and _is_retrieval_timeout(_message_text(message))
        for index, message in enumerate(messages)
    )


def _background_task_ids_by_call(
    messages: Sequence[dict[str, Any]],
) -> dict[str, str]:
    """Map TaskOutput-like tool calls to the background task they retrieve."""

    task_ids_by_call: dict[str, str] = {}
    for message in messages:
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        for tool_call in tool_calls:
            if not isinstance(tool_call, dict) or not tool_call.get("id"):
                continue
            function = tool_call.get("function")
            if not isinstance(function, dict):
                continue
            function_name = str(function.get("name", "")).replace("_", "").lower()
            if function_name not in {"taskoutput", "bashoutput", "gettaskoutput"}:
                continue
            arguments = _tool_arguments(tool_call) or {}
            task_id = next(
                (
                    str(arguments[key])
                    for key in ("task_id", "taskId", "bash_id", "id")
                    if arguments.get(key) is not None
                ),
                "",
            )
            if task_id:
                task_ids_by_call[str(tool_call["id"])] = task_id
    return task_ids_by_call


def _unresolved_background_task_ids(
    messages: Sequence[dict[str, Any]],
    allowed_indices: set[int] | None = None,
) -> set[str]:
    """Track every background task, including setup tasks outside test blocks.

    With allowed_indices only tool results at those indices contribute, so
    historical background launches outside pipeline-inserted blocks are ignored.
    """

    task_ids_by_call = _background_task_ids_by_call(messages)
    task_complete: dict[str, bool] = {}
    for index, message in enumerate(messages):
        if message.get("role") != "tool":
            continue
        if allowed_indices is not None and index not in allowed_indices:
            continue
        result_text = _message_text(message)
        task_id = _background_task_id_from_text(result_text) or task_ids_by_call.get(
            str(message.get("tool_call_id", ""))
        )
        if task_id is None:
            continue
        if re.search(
            r"<retrieval_status>\s*success\s*</retrieval_status>|"
            r"<status>\s*completed\s*</status>",
            result_text,
            re.IGNORECASE,
        ):
            task_complete[task_id] = True
        elif re.search(
            r"Command running in background with ID:|"
            r"<retrieval_status>\s*(?:running|pending|timeout|timed_out|error)\s*"
            r"</retrieval_status>|<status>\s*(?:running|pending)\s*</status>",
            result_text,
            re.IGNORECASE,
        ):
            task_complete[task_id] = False
    return {task_id for task_id, complete in task_complete.items() if not complete}


def _tool_result_block_range(
    messages: Sequence[dict[str, Any]],
    result_index: int,
) -> tuple[int, int]:
    """Return the assistant-call/result/summary range owning one tool result."""

    result = messages[result_index]
    call_id = str(result.get("tool_call_id", ""))
    if not call_id:
        return (result_index, result_index)
    start_index: int | None = None
    sibling_ids: set[str] = set()
    for candidate_index in range(result_index - 1, -1, -1):
        candidate = messages[candidate_index]
        if candidate.get("role") != "assistant":
            continue
        tool_calls = candidate.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        sibling_ids = {
            str(tool_call["id"])
            for tool_call in tool_calls
            if isinstance(tool_call, dict) and tool_call.get("id")
        }
        if call_id in sibling_ids:
            start_index = candidate_index
            break
    if start_index is None:
        return (result_index, result_index)
    end_index = result_index
    cursor = result_index + 1
    while (
        cursor < len(messages)
        and messages[cursor].get("role") == "tool"
        and str(messages[cursor].get("tool_call_id", "")) in sibling_ids
    ):
        end_index = cursor
        cursor += 1
    if (
        cursor < len(messages)
        and messages[cursor].get("role") == "assistant"
        and not messages[cursor].get("tool_calls")
    ):
        end_index = cursor
    return (start_index, end_index)


def _infra_tool_ranges(
    messages: Sequence[dict[str, Any]],
    allowed_indices: set[int] | None = None,
) -> set[tuple[int, int]]:
    """Locate complete tool-call blocks whose result contains infra failure."""

    commands_by_call_id = _tool_commands_by_call_id(messages)
    return {
        _tool_result_block_range(messages, result_index)
        for result_index, result in enumerate(messages)
        if result.get("role") == "tool"
        and (allowed_indices is None or result_index in allowed_indices)
        and _tool_result_can_emit_current_failure(result, commands_by_call_id)
        and _infra_reasons(
            _message_text(result),
            _tool_result_exit_codes(result, _message_text(result)),
        )
    }


def _background_task_tool_ranges(
    messages: Sequence[dict[str, Any]],
    task_ids: set[str],
    allowed_indices: set[int] | None = None,
) -> set[tuple[int, int]]:
    """Locate all tool blocks belonging to tainted background tasks."""

    task_ids_by_call = _background_task_ids_by_call(messages)
    return {
        _tool_result_block_range(messages, result_index)
        for result_index, result in enumerate(messages)
        if result.get("role") == "tool"
        and (allowed_indices is None or result_index in allowed_indices)
        and (
            _background_task_id_from_text(_message_text(result))
            or task_ids_by_call.get(str(result.get("tool_call_id", "")))
        )
        in task_ids
    }


def _retrieval_timeout_tool_ranges(
    messages: Sequence[dict[str, Any]],
    allowed_indices: set[int] | None = None,
) -> set[tuple[int, int]]:
    """Remove the launcher and every retrieval block for timed-out work."""

    task_ids_by_call = _background_task_ids_by_call(messages)
    timed_out_ids = {
        task_id
        for result_index, result in enumerate(messages)
        if result.get("role") == "tool"
        and (allowed_indices is None or result_index in allowed_indices)
        and _is_retrieval_timeout(_message_text(result))
        and (
            task_id := (
                _background_task_id_from_text(_message_text(result))
                or task_ids_by_call.get(str(result.get("tool_call_id", "")))
            )
        )
    }
    timeout_ranges = {
        _tool_result_block_range(messages, result_index)
        for result_index, result in enumerate(messages)
        if result.get("role") == "tool"
        and (allowed_indices is None or result_index in allowed_indices)
        and _is_retrieval_timeout(_message_text(result))
    }
    return timeout_ranges | _background_task_tool_ranges(
        messages, timed_out_ids, allowed_indices
    )


_PASSING_CASE_LINE_RE = re.compile(
    r"^\s*(?:"
    r"[✓✔√✅]"          # ✓ ✔ √ ✅  vitest/jest/mocha per-test pass glyph
    r"|PASS(?=[\s:])"               # jest 文件级 `PASS src/foo.test.js`
    r"|\[\s*(?:PASS(?:ED)?|OK)\s*\]"  # 自建测试台逐条通过标记 `[PASS] ...` / `[ OK ]`
    r"|ok\s+\d+\b"                  # TAP `ok 1 - ...`
    r"|#"                          # `#`-前缀行:TAP `# Subtest:`/`# pass N`,或测试脚本回显的
                                    # 注释/小节标题(如 `# Account lockout after 5 failed attempts`)。
                                    # 这些行绝不会是失败**计数**明细/汇总行(真实框架汇总不以 `#` 起头;
                                    # TAP 的 `# fail N` 是「关键词在前、数字在后」,本就不被 `\d+ failed`
                                    # 命中),故在计数前整行剔除,避免注释里的 "N failed" 字样被误当失败数。
    r"|-{3}\s*PASS\b"               # go `--- PASS: TestX`
    r")"
)


def _strip_passing_case_lines(result_text: str) -> str:
    """去掉「不可能承载失败**计数**」的行(逐条通过用例行 + `#` 注释/小节标题行),再做失败计数扫描。

    vitest/jest/mocha 会逐条打印通过用例,行首带 ✓/√/`[PASS]` 等 pass 标记,而用例**名字**里常嵌
    含 "failed"/"failures" 之类的字样,例如:

        ✓ ... > should lock account after 5 failed attempts 10ms
        [PASS] account is locked after 5 failed logins

    测试脚本还常把小节标题作为 `#` 注释回显到输出,例如 `# Account lockout after 5 failed attempts`。
    朴素的 `\\b(\\d+)[ \\t]+failed\\b` 会把这些标题里的 "5 failed" 误当成「5 个失败用例」→
    FAILED_COUNT_NONZERO → 连锁 CONTRADICTORY_SUCCESS_CLAIM,把**全绿**的真跑测试误杀。
    这些行(pass 标记行、`#` 注释/小节标题行)既不可能是真正的失败明细行(那些带 ×/✗/`[FAIL]`),
    也不可能是失败计数汇总行(真实框架汇总不以 `#` 起头;TAP 的 `# fail N` 是关键词在前、数字在后,
    本就不被 `\\d+ failed` 命中),故在计数前整行剔除是安全的:真实失败的明细行与汇总行(如
    `Tests 2 failed | 161 passed`)均予保留。
    """

    if not result_text:
        return result_text
    return "\n".join(
        line
        for line in result_text.splitlines()
        if not _PASSING_CASE_LINE_RE.match(_strip_ansi(line))
    )


def _ordinary_failure_reasons(
    result_text: str, exit_codes: Sequence[int] = ()
) -> set[StoredReasonCode]:
    reasons: set[StoredReasonCode] = set()
    # 失败/错误**计数**类正则易被通过用例的名字击穿(名字里含 "N failed"/"N errors"),
    # 故先剔除 pass 标记行再计数;失败信号(has_failure_output)与 exit code 仍用原文。
    count_text = _strip_passing_case_lines(result_text)
    # 计数正则的两道护栏(2026-07-18):列对齐的 `key=value` 汇总表会把朴素的
    # `\d+[ \t]+failed` 击穿——例如 `passed=78   failed=0`,朴素式会把 `passed=78` 的
    # `78` 桥接到 `failed=0` 的 `failed` 词上,把**全绿**的 78 误当成「78 个失败」→
    # FAILED_COUNT_NONZERO → 把健康的插入块当失败块删掉(见排查报告)。故:
    #   ① `(?<![\w=])` —— 数字不得是前一个 `key=` 的取值(挡住 passed=78 的 78);
    #   ② `(?![ \t]*=)` —— 关键词不得是 `failed=`/`errors=` 这种标签(那属于 key=value,
    #      交由下方**显式** `key=N` 分支计数,且只在 N>0 时判失败)。
    # 真实失败明细/汇总(如 `2 failed, 3 passed`、`5 failures`、`Failed: 4`)仍照常命中。
    if any(
        int(match.group(1)) > 0
        for match in re.finditer(
            r"(?<![\w=])(\d+)[ \t]+fail(?:ed|ures?)\b(?![ \t]*=)",
            count_text,
            re.IGNORECASE,
        )
    ) or any(
        int(match.group(1).replace(",", "")) > 0
        for match in re.finditer(
            r"(?im)^\s*Failed[ \t]*:[ \t]*(\d[\d,]*)\b",
            count_text,
        )
    ) or any(
        # number not adjacent to "failed": ctest `N tests failed out of M`,
        # generic `N tests failed`.
        int(match.group(1)) > 0
        for match in re.finditer(
            r"(?<![\w=])(\d+)[ \t]+tests?[ \t]+failed\b(?![ \t]*=)",
            count_text,
            re.IGNORECASE,
        )
    ) or any(
        # 显式 key=value 汇总: `failed=N` / `failures=N` / `fail=N`(仅 N>0 判失败;
        # `failed=0` 这类全绿标签在此天然不触发)。
        int(match.group(1).replace(",", "")) > 0
        for match in re.finditer(
            r"\bfail(?:ed|ures?)?[ \t]*=[ \t]*(\d[\d,]*)\b",
            count_text,
            re.IGNORECASE,
        )
    ):
        reasons.add(StoredReasonCode.FAILED_COUNT_NONZERO)
    if any(
        int(match.group(1)) > 0
        for match in re.finditer(
            r"(?<![\w=])(\d+)[ \t]+errors?\b(?![ \t]*=)", count_text, re.IGNORECASE
        )
    ) or any(
        int(match.group(1).replace(",", "")) > 0
        for match in re.finditer(
            r"(?im)^\s*Errors?[ \t]*:[ \t]*(\d[\d,]*)\b",
            count_text,
        )
    ) or any(
        # unittest `FAILED (errors=N)` / `errors=N` inline.
        int(match.group(1)) > 0
        for match in re.finditer(
            r"\berrors?[ \t]*=[ \t]*(\d+)\b", count_text, re.IGNORECASE
        )
    ):
        reasons.add(StoredReasonCode.ERROR_COUNT_NONZERO)
    if has_failure_output(result_text):
        reasons.add(StoredReasonCode.FAILURE_OUTPUT_DETECTED)
    all_exit_codes = [*_runner_exit_codes(result_text), *exit_codes]
    if any(exit_code != 0 for exit_code in all_exit_codes):
        reasons.add(StoredReasonCode.RUNNER_EXIT_NONZERO)
    return reasons


def _runner_exit_codes(result_text: str) -> list[int]:
    codes = [
        int(match.group(1))
        for match in re.finditer(
            r"(?im)^\s*(?:RUNNER_EXIT|EXIT|EXIT_CODE)\s*[=:]\s*(-?\d+)\s*$",
            result_text,
        )
    ]
    codes.extend(
        int(match.group(1))
        for match in re.finditer(
            r"(?i)<exit_code>\s*(-?\d+)\s*</exit_code>", result_text
        )
    )
    return codes


def _is_edit_message(message: dict[str, Any]) -> bool:
    if message.get("role") != "assistant":
        return False
    tool_calls = message.get("tool_calls")
    if not isinstance(tool_calls, list):
        return False
    mutating_tool_names = {
        "edit",
        "write",
        "multiedit",
        "apply_patch",
        "notebookedit",
        "createfile",
    }
    for tool_call in tool_calls:
        if not isinstance(tool_call, dict):
            continue
        function = tool_call.get("function")
        if (
            isinstance(function, dict)
            and str(function.get("name", "")).lower() in mutating_tool_names
        ):
            return True
    return False


def _is_clean_pass(block: TestBlock) -> bool:
    return bool(block.exit_codes) and all(
        code == 0 for code in block.exit_codes
    ) and not _block_failure_reasons(block) and not _zero_tests(block.result_text)


def _is_fully_successful(block: TestBlock) -> bool:
    """收尾口径的「完全成功测试」：一次真跑且全绿(passed>0, failed=0, 无失败信号, 非零测试)。

    与 `_is_clean_pass` 的区别:不强制要求块里显式出现 exit code——大量真实通过的收尾块
    并不打印 `RUNNER_EXIT=0`(会被 MISSING_RUNNER_EXIT 标注),若强求 exit 码会把它们误判成
    「非完全成功」→ 误删。这里改为:①无任何失败原因(`_block_failure_reasons` 已覆盖 exit!=0、
    失败/错误计数、失败输出);②有正向通过证据 `passed>0`;③failed 为 0/缺省;④非零测试。
    这是 `report_run_passed`(基于 ToolEvent)在 TestBlock 层的等价物。"""
    if block.exit_codes and any(code != 0 for code in block.exit_codes):
        return False
    if _block_failure_reasons(block):
        return False
    if _zero_tests(block.result_text):
        return False
    passed, failed = parse_test_counts(block.result_text)
    return bool(passed and passed > 0) and not failed


def _block_failure_reasons(block: TestBlock) -> set[StoredReasonCode]:
    reasons = _ordinary_failure_reasons(block.result_text, block.exit_codes)
    if block.result_is_error:
        reasons.add(StoredReasonCode.TEST_TOOL_RESULT_ERROR)
    return reasons


def _zero_tests(result_text: str) -> bool:
    return has_zero_test_output(result_text)


def _failure_is_repaired(
    failed_block: TestBlock,
    blocks: Sequence[TestBlock],
    messages: Sequence[dict[str, Any]],
) -> bool:
    for candidate in blocks:
        if candidate.start_index <= failed_block.end_index:
            continue
        if not _is_clean_pass(candidate) or not test_scope_covers(
            failed_block.command, candidate.command
        ):
            continue
        if any(
            _is_edit_message(messages[index])
            for index in range(failed_block.end_index + 1, candidate.start_index)
        ):
            return True
    return False


def _failure_has_mismatched_rerun(
    failed_block: TestBlock,
    blocks: Sequence[TestBlock],
    messages: Sequence[dict[str, Any]],
) -> bool:
    for candidate in blocks:
        if candidate.start_index <= failed_block.end_index or not _is_clean_pass(candidate):
            continue
        if test_scope_covers(failed_block.command, candidate.command):
            continue
        if any(
            _is_edit_message(messages[index])
            for index in range(failed_block.end_index + 1, candidate.start_index)
        ):
            return True
    return False


def _failure_has_same_scope_pass_without_edit(
    failed_block: TestBlock,
    blocks: Sequence[TestBlock],
    messages: Sequence[dict[str, Any]],
) -> bool:
    for candidate in blocks:
        if candidate.start_index <= failed_block.end_index or not _is_clean_pass(candidate):
            continue
        if not test_scope_covers(failed_block.command, candidate.command):
            continue
        if not any(
            _is_edit_message(messages[index])
            for index in range(failed_block.end_index + 1, candidate.start_index)
        ):
            return True
    return False


def _has_unconditional_success_claim(message: dict[str, Any]) -> bool:
    text = _message_text(message)
    if re.search(
        r"\b(?:not|never|cannot|couldn't|didn't)\b[^.\n]{0,30}"
        r"\b(?:tests?|suite)\b[^.\n]{0,20}\bpass",
        text,
        re.IGNORECASE,
    ):
        return False
    return bool(
        re.search(
            r"\ball (?:the )?tests? (?:have )?passed\b|"
            r"\btests? (?:all )?(?:pass|passed|passing|are green)\b|"
            r"\btest suite (?:pass|passes|passed|is green)\b|"
            r"\beverything passes\b|\bfully verified\b|"
            r"全部测试(?:均|都)?通过|测试(?:均|都|已)?通过|验证通过",
            text,
            re.IGNORECASE,
        )
    )


_RUNNER_PASS_COUNT_RE = re.compile(
    r"(?<![A-Za-z0-9_])(\d[\d,]*)\s+passed\b", re.IGNORECASE
)
_TERMINAL_RUNNER_EXIT_RE = re.compile(
    r"(?im)^\s*(?:RUNNER_EXIT|EXIT_CODE|EXIT)\s*[=:]\s*-?\d+\s*$"
)
_ASSISTANT_PASS_COUNT_RE = re.compile(
    r"(?<![A-Za-z0-9_])(\d[\d,]*)\s+(?:tests?\s+)?passed\b",
    re.IGNORECASE,
)


def _strip_trailing_exit_sentinel(text: str) -> str:
    """截掉**尾部**的 RUNNER_EXIT/EXIT_CODE 哨兵行，避免把 exit 码误当计数。

    只在「哨兵之后不再有任何测试计数/汇总证据」时才截断:脚本常先 `echo "exit=$?"` 再 `tail`
    出真实测试输出(exit 出现在**开头**),盲目截掉哨兵起点之后会把 `13 passed` 等真实计数一并
    清空、令完全成功被误判为失败。改为从后往前找第一个「其后无计数/汇总」的哨兵才截。"""
    if not text:
        return text
    for _m in reversed(list(_TERMINAL_RUNNER_EXIT_RE.finditer(text))):
        after = text[_m.end():]
        if not (_TEST_PASS_COUNT_RE.search(after)
                or _TEST_FAIL_COUNT_RE.search(after)
                or _STRONG_TEST_SUMMARY_RE.search(after)):
            return text[: _m.start()]
    return text


def _last_runner_pass_count(text: str) -> int | None:
    text = _strip_trailing_exit_sentinel(text)
    matches = list(_RUNNER_PASS_COUNT_RE.finditer(text))
    if not matches:
        return None
    return int(matches[-1].group(1).replace(",", ""))


def _summary_has_test_count_mismatch(result_text: str, summary: dict[str, Any]) -> bool:
    if summary.get("role") != "assistant" or summary.get("tool_calls"):
        return False
    evidence_count = _last_runner_pass_count(result_text)
    if evidence_count is None:
        return False
    claims = {
        int(match.group(1).replace(",", ""))
        for match in _ASSISTANT_PASS_COUNT_RE.finditer(_message_text(summary))
    }
    # 收尾总结常并列「全量」与「子集」两个通过数,例如
    #   `New regression tests: 7 passed` + `Full suite: 223 passed (216 baseline + 7 new)`。
    # 7 与 223 都真实、互不矛盾。旧判据 `any(claim != evidence)` 会因 7≠223 误报计数不符,
    # 把一个证据充分的全绿收尾判成 TEST_COUNT_MISMATCH。计数不符的真正风险是**夸大/伪造**
    # (声称的通过数比证据多),而非提及一个更小的子集数。故只在「有声称数**超过**证据数」时判
    # 不符:子集数(≤证据)放行,夸大数(>证据)仍被抓,且即便总结同时复述了正确总数也照抓。
    return any(claim > evidence_count for claim in claims)


def _block_has_test_count_mismatch(
    block: TestBlock, messages: Sequence[dict[str, Any]]
) -> bool:
    if block.end_index >= len(messages):
        return False
    return _summary_has_test_count_mismatch(
        block.result_text, messages[block.end_index]
    )


def _terminal_has_test_count_mismatch(
    blocks: Sequence[TestBlock], messages: Sequence[dict[str, Any]]
) -> bool:
    if not blocks or not messages:
        return False
    latest_block = max(blocks, key=lambda block: block.result_index)
    return _summary_has_test_count_mismatch(latest_block.result_text, messages[-1])


def _remove_success_claim_sentences(text: str) -> str:
    sentences = re.split(r"(?<=[.!?。！？])\s+", text.strip())
    kept = [
        sentence
        for sentence in sentences
        if sentence and not _has_unconditional_success_claim({"content": sentence})
    ]
    return " ".join(kept)


def _terminal_summary_reason(
    messages: Sequence[dict[str, Any]],
) -> StoredReasonCode | None:
    """Require the session to end with a non-empty plain-text assistant summary."""

    if not messages:
        return None
    terminal = messages[-1]
    if terminal.get("role") != "assistant":
        return StoredReasonCode.TRAILING_NON_ASSISTANT
    content = terminal.get("content")
    if not isinstance(content, str):
        return StoredReasonCode.TERMINAL_SUMMARY_NOT_PLAIN_TEXT
    if not content.strip():
        return StoredReasonCode.MISSING_TERMINAL_SUMMARY
    return None


def validate_messages(messages: Sequence[dict[str, Any]]) -> SessionValidation:
    """Validate the minimum trustworthy stored test block contract.

    Scope rule (2026-07-14): structural checks (duplicate/dangling tool calls,
    orphan results) always cover the whole session. The strict evidence
    contract (infra blacklist, RUNNER_EXIT, block summary, count consistency,
    failure/repair analysis, ...) applies only to pipeline-inserted synthetic
    blocks when any exist — historical dev-session blocks are context, not
    evidence, and their interactive noise (missing RUNNER_EXIT markers, user
    turns after tool results, probe failures) must not taint the verdict.
    Sessions without any synthetic block keep the legacy whole-session
    behavior.
    """

    test_call_ids = _test_call_ids(messages)
    all_tool_call_ids = _all_tool_call_ids(messages)
    result_ids = {
        str(message.get("tool_call_id"))
        for message in messages
        if message.get("role") == "tool" and message.get("tool_call_id")
    }
    blocks = tuple(_parse_blocks(messages))
    call_counts: dict[str, int] = {}
    for message in messages:
        if message.get("role") != "assistant":
            continue
        tool_calls = message.get("tool_calls")
        if not isinstance(tool_calls, list):
            continue
        for tool_call in tool_calls:
            if isinstance(tool_call, dict) and tool_call.get("id"):
                call_id = str(tool_call["id"])
                call_counts[call_id] = call_counts.get(call_id, 0) + 1
    if any(count > 1 for count in call_counts.values()):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.DUPLICATE_TOOL_CALL,),
            blocks=blocks,
        )
    result_counts: dict[str, int] = {}
    for message in messages:
        if message.get("role") != "tool" or not message.get("tool_call_id"):
            continue
        result_id = str(message["tool_call_id"])
        result_counts[result_id] = result_counts.get(result_id, 0) + 1
    if any(count > 1 for count in result_counts.values()):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.DUPLICATE_TOOL_RESULT,),
            blocks=blocks,
        )
    if test_call_ids - result_ids:
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.DANGLING_TEST_TOOL_CALL,),
            blocks=blocks,
        )
    if all_tool_call_ids - result_ids:
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.DANGLING_TOOL_CALL,),
            blocks=blocks,
        )
    if any(
        message.get("role") == "tool"
        and str(message.get("tool_call_id", "")) not in all_tool_call_ids
        for message in messages
    ):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.ORPHAN_TOOL_RESULT,),
            blocks=blocks,
        )
    synthetic_blocks = tuple(
        block for block in blocks if _block_is_synthetic(block, messages)
    )
    evidence_blocks = synthetic_blocks if synthetic_blocks else blocks
    scope_indices = (
        _synthetic_scope_indices(synthetic_blocks, messages)
        if synthetic_blocks
        else None
    )
    infra_reasons = _session_infra_reasons(messages, scope_indices)
    if infra_reasons:
        return SessionValidation(
            verdict=StoredVerdict.INFRA_ERROR,
            reason_codes=tuple(sorted(infra_reasons, key=lambda reason: reason.value)),
            blocks=blocks,
        )
    if _session_has_retrieval_timeout(messages, scope_indices):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.RETRIEVAL_TIMEOUT,),
            blocks=blocks,
        )
    if _unresolved_background_task_ids(messages, scope_indices):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.BACKGROUND_RESULT_PENDING,),
            blocks=blocks,
        )
    if not blocks:
        # 没有(块解析器识别到的)测试块。但会话可能本就是「已含真实完全成功测试、被正确放行、未插
        # 合成块」的 passing suite——块解析器(旧 is_test_command/_parse_blocks)会漏认
        # `bash run_tests.sh`→vitest、`npx vitest`、后台/子代理测试等真实终态测试。用改进后的确定性
        # oracle 复核:收尾确有一次**完全成功**的真实测试 → PASS(passing suite 无需合成块,与用户口径
        # 「有全成功的测试就通过」一致);否则才是真的无可靠测试证据 → NO_TEST_BLOCK。
        if terminal_test_state(messages).state == TERMINAL_PASSING:
            return SessionValidation(
                verdict=StoredVerdict.PASS,
                reason_codes=(),
                blocks=(),
            )
        return SessionValidation(
            verdict=StoredVerdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(StoredReasonCode.NO_TEST_BLOCK,),
            blocks=(),
        )
    if any(
        messages[block.end_index].get("role") != "assistant"
        for block in evidence_blocks
    ):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.MISSING_BLOCK_SUMMARY,),
            blocks=blocks,
        )
    terminal_reason = _terminal_summary_reason(messages)
    if terminal_reason is not None:
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(terminal_reason,),
            blocks=blocks,
        )
    if any(
        re.search(
            r"Command running in background with ID:|"
            r"<retrieval_status>\s*(?:running|pending)\s*</retrieval_status>|"
            r"<status>\s*(?:running|pending)\s*</status>",
            block.result_text,
            re.IGNORECASE,
        )
        for block in evidence_blocks
    ):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.BACKGROUND_RESULT_PENDING,),
            blocks=blocks,
        )
    if any(
        re.search(
            r"<retrieval_status>\s*(?:timeout|timed_out|error)\s*</retrieval_status>|"
            r"\bretrieval timed out\b|\btask retrieval timed out\b|"
            r"\bcommand timed out\b|\btimeout after \d+",
            block.result_text,
            re.IGNORECASE,
        )
        for block in evidence_blocks
    ):
        return SessionValidation(
            verdict=StoredVerdict.INCOMPLETE_TRACE,
            reason_codes=(StoredReasonCode.RETRIEVAL_TIMEOUT,),
            blocks=blocks,
        )
    if any(
        re.search(
            r"(?:^|\n).*\bcd(?::|\s).*No such file or directory",
            block.result_text,
            re.IGNORECASE,
        )
        for block in evidence_blocks
    ):
        return SessionValidation(
            verdict=StoredVerdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(StoredReasonCode.REPOSITORY_CD_FAILED,),
            blocks=blocks,
        )
    # 终态语义对齐(2026-07-17):非合成(真实源)会话——若**收尾测试窗口是干净全绿**且其后未再改代码,
    # 直接判 PASS。历史上的失败→修复→重跑属正常开发迭代,不因中段失败/部分重跑/零测试否决一个终态
    # 已绿的会话。这消除 stored gate 与判官 terminal_test_state/needs_final_test 对同一会话给出相反结论
    # 的不一致(判官只看收尾窗口)。合成候选(插入了补测块)**不**走此捷径:其插入块仍逐块严格校验
    # (fail-closed),下方 EDIT_AFTER_LAST_TEST 仍对「收尾测试后又改代码」把关。
    if not synthetic_blocks and blocks:
        _last_test_end = max(block.end_index for block in blocks)
        _edited_after = any(
            _is_edit_message(messages[i])
            for i in range(_last_test_end + 1, len(messages))
        )
        if not _edited_after and terminal_test_state(messages).state == TERMINAL_PASSING:
            return SessionValidation(
                verdict=StoredVerdict.PASS, reason_codes=(), blocks=blocks
            )
    unresolved_zero_blocks = [
        block
        for block in evidence_blocks
        if _zero_tests(block.result_text)
        and not _failure_is_repaired(block, blocks, messages)
    ]
    if unresolved_zero_blocks:
        return SessionValidation(
            verdict=StoredVerdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(StoredReasonCode.ZERO_TESTS_COLLECTED,),
            blocks=blocks,
        )
    failed_blocks = [
        block
        for block in evidence_blocks
        if _block_failure_reasons(block)
    ]
    unresolved_blocks = [
        block
        for block in failed_blocks
        if not _failure_is_repaired(block, blocks, messages)
    ]
    failure_reasons: set[StoredReasonCode] = set()
    for block in unresolved_blocks:
        failure_reasons.update(_block_failure_reasons(block))
    if any(
        _failure_has_mismatched_rerun(block, blocks, messages)
        for block in unresolved_blocks
    ):
        failure_reasons.add(StoredReasonCode.PARTIAL_RERUN_AFTER_FAILURE)
    if any(
        _failure_has_same_scope_pass_without_edit(block, blocks, messages)
        for block in unresolved_blocks
    ):
        failure_reasons.add(StoredReasonCode.NO_REPAIR_BETWEEN_ATTEMPTS)
    if any(
        _has_unconditional_success_claim(messages[block.end_index])
        for block in unresolved_blocks
    ):
        failure_reasons.add(StoredReasonCode.CONTRADICTORY_SUCCESS_CLAIM)
    if failure_reasons:
        return SessionValidation(
            verdict=StoredVerdict.TEST_FAILED_UNRESOLVED,
            reason_codes=tuple(sorted(failure_reasons, key=lambda reason: reason.value)),
            blocks=blocks,
        )
    if any(
        _block_has_test_count_mismatch(block, messages) for block in evidence_blocks
    ) or _terminal_has_test_count_mismatch(evidence_blocks, messages):
        return SessionValidation(
            verdict=StoredVerdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(StoredReasonCode.TEST_COUNT_MISMATCH,),
            blocks=blocks,
        )
    if synthetic_blocks and any(not block.exit_codes for block in evidence_blocks):
        # `RUNNER_EXIT=<code>` 哨兵是**流水线插入的合成块专属**产物(add_run_test 才会打印);真实
        # 会话里被正确放行、未补测的通过测试(如直接 `pytest`/`bash run_tests.sh`)本就不打印它。
        # 故仅在**校验合成块**时要求 RUNNER_EXIT;无合成块的 legacy 会话不因缺这个哨兵被误判
        # (与本函数顶部注释「RUNNER_EXIT 只对合成证据成立」一致,亦符合用户口径:有全成功测试即通过)。
        return SessionValidation(
            verdict=StoredVerdict.NO_RELIABLE_TEST_EVIDENCE,
            reason_codes=(StoredReasonCode.MISSING_RUNNER_EXIT,),
            blocks=blocks,
        )
    last_test_end = max(block.end_index for block in evidence_blocks)
    if any(_is_edit_message(messages[index]) for index in range(last_test_end + 1, len(messages))):
        return SessionValidation(
            verdict=StoredVerdict.STALE_TEST_PASS,
            reason_codes=(StoredReasonCode.EDIT_AFTER_LAST_TEST,),
            blocks=blocks,
        )
    return SessionValidation(verdict=StoredVerdict.PASS, reason_codes=(), blocks=blocks)


# add_run_test_tool.py prepends a synthetic user turn (see its synth_user_intro:
# "...run the discovered test runner...") in front of every runtest block it inserts,
# so the segment reads user -> assistant(tool_call) -> tool -> closing assistant.
# A parsed TestBlock only spans assistant(tool_call)..tool, so deleting a block would
# leave that user turn dangling; across repeated pipeline passes those orphans stack
# up (a session ending in `tool, user, user`) and then trip MISSING_BLOCK_SUMMARY /
# TRAILING_NON_ASSISTANT taints that take otherwise-valid inserts down with them.
# Treat such a user turn as pipeline residue and remove it together with its block
# (or on its own when the block is already gone). Both the current and the legacy
# command-inlined phrasings contain this marker substring.
_RUNTEST_INTRO_MARKER = "run the discovered test runner"


def _is_synthetic_runtest_intro(message: dict[str, Any]) -> bool:
    return (
        message.get("role") == "user"
        and not message.get("tool_calls")
        and _RUNTEST_INTRO_MARKER in _message_text(message).lower()
    )


def _synthetic_segment_start(
    messages: Sequence[dict[str, Any]], block_start: int
) -> int:
    """Backward-walk from a synthetic test block's start to the injected segment head.

    A gold-standard runtest insert is a contiguous span:
      [marker user intro] + [assistant(startup tool_call)+tool]* + assistant(test)+tool
    The intro marker sits at the head — on the user intro, or (when the anchor's
    predecessor was already a user, so no user intro was added) on the first
    inserted assistant's content. This walks back over the contiguous injected
    assistant(tool_call)/tool pairs to that marker head and returns its index.

    Returns `block_start` unchanged when no marker head is found within the
    bounded injected span, so genuine history is never pulled into cleanup.
    """
    if block_start < 0 or block_start >= len(messages):
        return block_start
    if _RUNTEST_INTRO_MARKER in _message_text(messages[block_start]).lower():
        # Marker on the block's own start node (legacy single-node insert): the
        # user intro, if any, is handled by the orphan-intro sweep.
        return block_start
    # The injected span is at most MAX_INSERT_CHAIN_STEPS (assistant+tool) pairs
    # plus one user intro; bound the walk to that span so a marker-less run of
    # real history before the block can never be swept.
    max_steps = MAX_INSERT_CHAIN_STEPS * 2 + 2
    steps = 0
    cursor = block_start - 1
    while cursor >= 0 and steps < max_steps:
        node = messages[cursor]
        if not isinstance(node, dict):
            break
        role = node.get("role")
        if _is_synthetic_runtest_intro(node):
            return cursor
        if role == "assistant" and _RUNTEST_INTRO_MARKER in _message_text(node).lower():
            return cursor
        if role == "tool" or (role == "assistant" and node.get("tool_calls")):
            cursor -= 1
            steps += 1
            continue
        break
    return block_start


def _block_is_synthetic(
    block: TestBlock, messages: Sequence[dict[str, Any]]
) -> bool:
    """Whether a parsed test block was inserted by the runtest pipeline.

    add_run_test_tool.py brands every inserted segment with the intro marker at
    its head (the synthetic user intro, or the first inserted assistant when no
    user intro was added). Multi-node gold inserts place several real container
    startup steps between that head and the final test block, so detection walks
    back over the contiguous injected pairs to the marker head. Historical
    trajectory blocks never carry that phrasing.
    """

    start = messages[block.start_index]
    if _RUNTEST_INTRO_MARKER in _message_text(start).lower():
        return True
    # Multi-node: the marker head sits several injected startup pairs earlier.
    if _synthetic_segment_start(messages, block.start_index) != block.start_index:
        return True
    # Legacy: the immediate predecessor is the synthetic user intro.
    return block.start_index > 0 and _is_synthetic_runtest_intro(
        messages[block.start_index - 1]
    )


def _synthetic_scope_indices(
    blocks: Sequence[TestBlock], messages: Sequence[dict[str, Any]]
) -> set[int]:
    """Message indices covered by each synthetic segment: head .. closing summary.

    Spans the whole injected segment (marker head + container startup pairs +
    final test pair), not just the final test block, so infra/background/timeout
    scoping and removal both see the entire inserted span.
    """

    return {
        index
        for block in blocks
        for index in range(
            _synthetic_segment_start(messages, block.start_index),
            block.end_index + 1,
        )
    }


def _message_starts_test_block(message: dict[str, Any]) -> bool:
    """Whether this assistant message issues a genuine test-runner tool call."""

    tool_calls = message.get("tool_calls")
    if message.get("role") != "assistant" or not isinstance(tool_calls, list):
        return False
    for tool_call in tool_calls:
        if not isinstance(tool_call, dict):
            continue
        command = _tool_command(tool_call)
        if command and is_test_command(command):
            return True
    return False


def _orphaned_runtest_intro_indices(
    messages: Sequence[dict[str, Any]], indexes_to_remove: set[int]
) -> set[int]:
    """Synthetic runtest intros whose paired test block is absent or being removed.

    A gold insert may place several container-startup pairs between the intro and
    the final test block, so this scans FORWARD over the contiguous injected
    assistant(tool_call)/tool pairs to reach that block. The intro survives iff
    the paired test block is present and not being removed.
    """

    orphaned: set[int] = set()
    max_steps = MAX_INSERT_CHAIN_STEPS * 2 + 2
    for index, message in enumerate(messages):
        if not _is_synthetic_runtest_intro(message):
            continue
        cursor = index + 1
        steps = 0
        paired_block_survives = False
        while cursor < len(messages) and steps < max_steps:
            node = messages[cursor]
            if not isinstance(node, dict):
                break
            if _message_starts_test_block(node):
                paired_block_survives = cursor not in indexes_to_remove
                break
            role = node.get("role")
            if role == "tool" or (role == "assistant" and node.get("tool_calls")):
                cursor += 1
                steps += 1
                continue
            break
        if not paired_block_survives:
            orphaned.add(index)
    return orphaned


def clean_messages(
    messages: Sequence[dict[str, Any]],
    *,
    action: str = "delete",
    only_synthetic: bool = False,
) -> CleanResult:
    """Return a detached message list; cleanup policies are applied by action.

    only_synthetic (presweep mode): sweep ONLY pipeline residue — broken
    synthetic blocks and orphaned synthetic intros left by earlier pipeline
    versions. Legacy history is never touched, so this is safe to run BEFORE
    insertion (STEP2) to keep old residue from blocking a fresh insert.
    """

    if action not in {"delete", "quarantine"}:
        raise ValueError(f"unsupported cleanup action: {action}")
    validation = validate_messages(messages)
    if action == "quarantine":
        return CleanResult(
            messages=deepcopy(list(messages)),
            changed=False,
            validation_before=validation,
            quarantine_required=validation.verdict is not StoredVerdict.PASS,
        )
    dirty_blocks: list[TestBlock] = []
    synthetic_blocks = [
        block
        for block in validation.blocks
        if _block_is_synthetic(block, messages)
    ]
    # Scope rule (2026-07-14): when the session carries pipeline-inserted
    # synthetic blocks, cleanup may only remove those blocks (plus structural
    # orphans/duplicates below). Historical trajectory blocks are source data
    # — including genuine red->green repair evidence — and are never deleted.
    scoped = bool(synthetic_blocks)
    if only_synthetic and not scoped:
        # Presweep on a session with no synthetic blocks: the only sweepable
        # residue is orphaned intros; every other node is legacy history.
        orphan_intros = tuple(
            sorted(_orphaned_runtest_intro_indices(messages, set()))
        )
        orphan_set = set(orphan_intros)
        return CleanResult(
            messages=[
                deepcopy(message)
                for index, message in enumerate(messages)
                if index not in orphan_set
            ],
            changed=bool(orphan_intros),
            validation_before=validation,
            removed_runtest_intro_indices=orphan_intros,
        )
    scope_indices = (
        _synthetic_scope_indices(tuple(synthetic_blocks), messages) if scoped else None
    )
    cleanup_candidates = synthetic_blocks if scoped else list(validation.blocks)

    def _scoped_dirty(candidates: Sequence[TestBlock]) -> list[TestBlock]:
        """Per-block dirty selection for scoped (synthetic) cleanup.

        Fix (2026-07-18, option 1): a non-PASS *session* verdict must not drag a
        healthy insert to deletion. When synthetic blocks are present the strict
        contract already scopes the verdict to those blocks, but with several
        inserts (or a session-level reason unrelated to the insert) the old
        `dirty_blocks = all cleanup_candidates` deleted healthy blocks too. Now,
        in scoped mode, only synthetic blocks that are NOT a clean self-contained
        pass are removed — i.e. the insert itself failed (`_block_failure_reasons`),
        collected zero tests, or is structurally broken (no RUNNER_EXIT). A
        genuinely-green insert (`_is_clean_pass`) always survives, so historical
        red blocks never implicate it. Non-scoped (legacy whole-session) cleanup
        keeps its original behavior.
        """

        if not scoped:
            return list(candidates)
        return [block for block in candidates if not _is_clean_pass(block)]

    if validation.verdict in {
        StoredVerdict.INFRA_ERROR,
        StoredVerdict.INCOMPLETE_TRACE,
        StoredVerdict.NO_RELIABLE_TEST_EVIDENCE,
        StoredVerdict.STALE_TEST_PASS,
    } and StoredReasonCode.TEST_COUNT_MISMATCH not in validation.reason_codes:
        dirty_blocks = _scoped_dirty(cleanup_candidates)
    elif validation.verdict is StoredVerdict.TEST_FAILED_UNRESOLVED:
        # Removing only the newest failed block could make an older green block
        # look like the terminal proof on the next validation pass — so in the
        # non-scoped path we still take every candidate. In scoped mode a green
        # insert is kept: its own evidence is self-contained and authoritative.
        dirty_blocks = _scoped_dirty(cleanup_candidates)

    if scoped:
        # Scoped removal spans the WHOLE injected segment: from the marker head
        # (user intro / first inserted assistant) through the final test pair, so
        # the intermediate container-startup pairs are removed as one unit and
        # never left orphaned between a removed intro and a removed test block.
        range_set = {
            (_synthetic_segment_start(messages, block.start_index), block.end_index)
            for block in dirty_blocks
        }
    else:
        range_set = {(block.start_index, block.end_index) for block in dirty_blocks}
    if validation.verdict is StoredVerdict.INFRA_ERROR:
        range_set.update(_infra_tool_ranges(messages, scope_indices))
    if StoredReasonCode.BACKGROUND_RESULT_PENDING in validation.reason_codes:
        range_set.update(
            _background_task_tool_ranges(
                messages,
                _unresolved_background_task_ids(messages, scope_indices),
                scope_indices,
            )
        )
    if StoredReasonCode.RETRIEVAL_TIMEOUT in validation.reason_codes:
        range_set.update(_retrieval_timeout_tool_ranges(messages, scope_indices))
    if scoped:
        # A synthetic block's closing assistant is the pre-existing anchor
        # node (add_run_test_tool never inserts a closing assistant); every
        # range helper above extends to that trailing plain assistant, so trim
        # it back here. History keeps its summary and the session keeps its
        # terminal node — only the injected user/assistant(tool_call)/tool
        # nodes are removed.
        range_set = {
            (start, end - 1)
            if (
                end < len(messages)
                and end - 1 >= start
                and messages[end].get("role") == "assistant"
                and not messages[end].get("tool_calls")
            )
            else (start, end)
            for start, end in range_set
        }
    if (
        StoredReasonCode.DANGLING_TEST_TOOL_CALL in validation.reason_codes
        or StoredReasonCode.DANGLING_TOOL_CALL in validation.reason_codes
    ) and not only_synthetic:
        result_ids = {
            str(message.get("tool_call_id"))
            for message in messages
            if message.get("role") == "tool" and message.get("tool_call_id")
        }
        range_set.update(
            _dangling_test_ranges(
                messages,
                result_ids,
                test_only=(
                    StoredReasonCode.DANGLING_TEST_TOOL_CALL in validation.reason_codes
                ),
            )
        )
    removed_ranges = tuple(sorted(range_set))
    indexes_to_remove = {
        index
        for start_index, end_index in removed_ranges
        for index in range(start_index, end_index + 1)
    }
    known_call_ids = _all_tool_call_ids(messages)
    removed_orphan_indices: tuple[int, ...] = ()
    extra_tool_result_indices: list[int] = []
    if not only_synthetic:
        # Legacy structural damage (orphan / duplicate tool results) is out of
        # presweep scope — it predates the pipeline and is handled by the
        # post-insert cleanup step instead.
        removed_orphan_indices = tuple(
            index
            for index, message in enumerate(messages)
            if message.get("role") == "tool"
            and str(message.get("tool_call_id", "")) not in known_call_ids
        )
        indexes_to_remove.update(removed_orphan_indices)
        seen_result_ids: set[str] = set()
        for index, message in enumerate(messages):
            if message.get("role") != "tool" or not message.get("tool_call_id"):
                continue
            result_id = str(message["tool_call_id"])
            if result_id in seen_result_ids:
                extra_tool_result_indices.append(index)
            seen_result_ids.add(result_id)
        indexes_to_remove.update(extra_tool_result_indices)
    removed_runtest_intro_indices = tuple(
        sorted(_orphaned_runtest_intro_indices(messages, indexes_to_remove))
    )
    indexes_to_remove.update(removed_runtest_intro_indices)
    cleaned_messages: list[dict[str, Any]] = []
    rewritten_summary_indices: list[int] = []
    removed_summary_indices: list[int] = []
    strip_success_claims = (
        validation.verdict is not StoredVerdict.PASS
        and bool(dirty_blocks if scoped else validation.blocks)
        and StoredReasonCode.TEST_COUNT_MISMATCH not in validation.reason_codes
    )
    # In scoped mode only the summaries attached to removed synthetic evidence
    # may be rewritten: the anchor node closing each removed block and the
    # session terminal (which carries the merged verification sentence).
    # Historical assistant prose stays verbatim.
    strip_eligible_indices: set[int] | None = None
    if scoped and strip_success_claims:
        strip_eligible_indices = {block.end_index for block in dirty_blocks}
        if messages:
            strip_eligible_indices.add(len(messages) - 1)
    for index, message in enumerate(messages):
        if index in indexes_to_remove:
            continue
        copied = deepcopy(message)
        if (
            strip_success_claims
            and (strip_eligible_indices is None or index in strip_eligible_indices)
            and copied.get("role") == "assistant"
            and not copied.get("tool_calls")
            and isinstance(copied.get("content"), str)
            and _has_unconditional_success_claim(copied)
        ):
            rewritten = _remove_success_claim_sentences(copied["content"])
            if rewritten != copied["content"]:
                if not rewritten.strip():
                    removed_summary_indices.append(index)
                    continue
                copied["content"] = rewritten
                rewritten_summary_indices.append(index)
        cleaned_messages.append(copied)
    return CleanResult(
        messages=cleaned_messages,
        changed=bool(
            indexes_to_remove or rewritten_summary_indices or removed_summary_indices
        ),
        validation_before=validation,
        removed_block_ranges=removed_ranges,
        removed_orphan_indices=removed_orphan_indices,
        removed_extra_tool_result_indices=tuple(extra_tool_result_indices),
        rewritten_summary_indices=tuple(rewritten_summary_indices),
        removed_summary_indices=tuple(removed_summary_indices),
        removed_runtest_intro_indices=removed_runtest_intro_indices,
        quarantine_required=(
            StoredReasonCode.TEST_COUNT_MISMATCH in validation.reason_codes
        ),
    )


def _message_list(document: dict[str, Any]) -> list[dict[str, Any]] | None:
    for key in ("messages", "chat_messages", "conversation", "history"):
        value = document.get(key)
        if isinstance(value, list) and all(isinstance(item, dict) for item in value):
            return value
    return None


_SUBAGENT_NAME_RE = re.compile(r"(?:^|[^0-9A-Za-z])agent-", re.ASCII)


def _is_main_session_path(path: Path) -> bool:
    """Exclude nested worker (sub-agent) transcripts from the main runtest gate.

    Sub-agent transcripts live under a ``subagents/`` directory in the native
    nested layout, but flattened batch layouts name them
    ``TASK-...__agent-<hex>.json`` (or bare ``agent-<hex>.json``) *directly*
    inside ``sessions/`` — the old ``startswith("agent-")`` check let those
    leak in as main sessions. Match the ``agent-<hex>`` token anywhere in the
    stem so both layouts are excluded.
    """

    if "subagents" in path.parts:
        return False
    if path.name.startswith("agent-"):
        return False
    if _SUBAGENT_NAME_RE.search(path.stem):
        return False
    return True


def _session_paths(root: Path, report_path: Path) -> list[Path]:
    if root.is_file():
        return [root]
    excluded_directories = {
        ".git",
        ".tmp",
        "__MACOSX",
        "report",
        "runtest_quarantine",
        ".runtest_quarantine",
    }
    report_resolved = report_path.resolve()
    candidates = [
        path
        for path in sorted(root.rglob("*.json"))
        if path.is_file()
        and path.resolve() != report_resolved
        and not any(part in excluded_directories for part in path.parts)
        and not path.name.startswith("._")
    ]
    session_layout_paths = [
        path
        for path in candidates
        if "sessions" in path.parts and _is_main_session_path(path)
    ]
    if session_layout_paths:
        return session_layout_paths
    return [path for path in candidates if path.parent == root]


def _relative_label(path: Path, root: Path) -> str:
    if root.is_file():
        return path.name
    try:
        return path.relative_to(root).as_posix()
    except ValueError:
        return path.name


def _block_record(block: TestBlock) -> dict[str, Any]:
    return {
        "start_index": block.start_index,
        "end_index": block.end_index,
        "result_index": block.result_index,
        "tool_call_id": block.tool_call_id,
        "command": block.command,
        "result_excerpt": block.result_text[:500],
        "exit_codes": list(block.exit_codes),
        "result_is_error": block.result_is_error,
    }


def inspect_stored_session(
    path: Path,
    *,
    root: Path,
    action: str,
    dry_run: bool,
    quarantine_dir: Path | None = None,
    only_synthetic: bool = False,
) -> dict[str, Any]:
    """Process one session and return a JSON-serializable audit record."""

    label = _relative_label(path, root)
    try:
        document = json.loads(path.read_text(encoding="utf-8-sig"))
    except (OSError, json.JSONDecodeError) as exc:
        return {
            "file": label,
            "verdict": StoredVerdict.INCOMPLETE_TRACE.value,
            "reason_codes": ["INVALID_JSON"],
            "error": str(exc),
            "changed": False,
            "would_change": False,
            "quarantine_required": True,
            "blocks": [],
        }
    if not isinstance(document, dict):
        return {
            "file": label,
            "verdict": StoredVerdict.NO_RELIABLE_TEST_EVIDENCE.value,
            "reason_codes": ["NO_MESSAGES_ARRAY"],
            "changed": False,
            "would_change": False,
            "quarantine_required": True,
            "blocks": [],
        }
    messages = _message_list(document)
    if messages is None:
        return {
            "file": label,
            "verdict": StoredVerdict.NO_RELIABLE_TEST_EVIDENCE.value,
            "reason_codes": ["NO_MESSAGES_ARRAY"],
            "changed": False,
            "would_change": False,
            "quarantine_required": True,
            "blocks": [],
        }

    validation = validate_messages(messages)
    if action == "validate":
        cleanup = CleanResult(
            messages=deepcopy(messages),
            changed=False,
            validation_before=validation,
            quarantine_required=validation.verdict is not StoredVerdict.PASS,
        )
    else:
        cleanup = clean_messages(
            messages, action=action, only_synthetic=only_synthetic
        )

    actually_changed = False
    quarantine_path: str | None = None
    if action == "delete" and cleanup.changed and not dry_run:
        messages[:] = cleanup.messages
        atomic_write_json(path, document)
        actually_changed = True
    elif (
        action == "quarantine"
        and cleanup.quarantine_required
        and quarantine_dir is not None
    ):
        destination = quarantine_dir / label
        quarantine_path = destination.as_posix()
        if not dry_run:
            destination.parent.mkdir(parents=True, exist_ok=True)
            atomic_write_json(destination, document)
            actually_changed = True

    return {
        "file": label,
        "verdict": validation.verdict.value,
        "reason_codes": [reason.value for reason in validation.reason_codes],
        "changed": actually_changed,
        "would_change": cleanup.changed or cleanup.quarantine_required,
        "quarantine_required": cleanup.quarantine_required,
        "quarantine_path": quarantine_path,
        "removed_block_ranges": [list(item) for item in cleanup.removed_block_ranges],
        "removed_orphan_indices": list(cleanup.removed_orphan_indices),
        "removed_extra_tool_result_indices": list(
            cleanup.removed_extra_tool_result_indices
        ),
        "rewritten_summary_indices": list(cleanup.rewritten_summary_indices),
        "removed_summary_indices": list(cleanup.removed_summary_indices),
        "removed_runtest_intro_indices": list(cleanup.removed_runtest_intro_indices),
        "blocks": [_block_record(block) for block in validation.blocks],
    }


def _default_quarantine_dir(root: Path) -> Path:
    if root.is_file():
        return root.parent / "runtest_quarantine"
    return root.parent / f"{root.name}_runtest_quarantine"


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Validate or clean stored OpenAI-style runtest evidence."
    )
    parser.add_argument("input", nargs="?", help="Session JSON file or root directory.")
    parser.add_argument("-r", "--root", help="Session JSON file or root directory.")
    parser.add_argument(
        "--action",
        choices=("validate", "quarantine", "delete"),
        default="validate",
    )
    parser.add_argument("--dry-run", action="store_true")
    parser.add_argument("--report", type=Path)
    parser.add_argument("--quarantine-dir", type=Path)
    parser.add_argument(
        "--only-synthetic",
        action="store_true",
        help=(
            "Presweep mode (delete only): sweep pipeline residue — broken "
            "synthetic blocks and orphaned synthetic intros. Never touches "
            "legacy history. Meant to run BEFORE add_run_test_tool."
        ),
    )
    parser.add_argument(
        "--preserve-step1-failures",
        action="store_true",
        help=(
            "Exclude sessions with an explicit non-PASS result in "
            "runtest_summary.json so they remain byte-for-byte unchanged."
        ),
    )
    return parser


def clean_main(argv: Sequence[str] | None = None) -> int:
    """CLI entry point; return nonzero whenever any session is not trustworthy."""

    args = _build_parser().parse_args(argv)
    if args.only_synthetic and args.action != "delete":
        _build_parser().error("--only-synthetic requires --action delete")
    root = Path(args.root or args.input or ".").expanduser().resolve()
    if not root.exists():
        _build_parser().error(f"input does not exist: {root}")
    report_path = (
        args.report.expanduser().resolve()
        if args.report
        else (root.parent if root.is_file() else root)
        / "runtest_evidence_report.json"
    )
    quarantine_dir = (
        args.quarantine_dir.expanduser().resolve()
        if args.quarantine_dir
        else _default_quarantine_dir(root)
    )
    paths = _session_paths(root, report_path)
    skipped_failed_paths: list[Path] = []
    if args.preserve_step1_failures:
        failed_keys = _failed_step1_session_keys(root)
        skipped_failed_paths = [
            path for path in paths if _session_task_key(path) in failed_keys
        ]
        paths = [path for path in paths if _session_task_key(path) not in failed_keys]
    records = [
        inspect_stored_session(
            path,
            root=root,
            action=args.action,
            dry_run=args.dry_run,
            quarantine_dir=quarantine_dir,
            only_synthetic=bool(args.only_synthetic),
        )
        for path in paths
    ]
    non_pass = sum(record["verdict"] != StoredVerdict.PASS.value for record in records)
    rerun_required = not records or non_pass > 0
    if args.only_synthetic:
        # Presweep runs before insertion, so non-PASS legacy sessions are
        # expected; only surface how much residue was actually swept.
        rerun_required = False
    payload = {
        "schema": REPORT_SCHEMA,
        "schema_version": SCHEMA_VERSION,
        "generated_at": datetime.now(timezone.utc).isoformat(),
        "root": root.as_posix(),
        "action": args.action,
        "only_synthetic": bool(args.only_synthetic),
        "preserve_step1_failures": bool(args.preserve_step1_failures),
        "skipped_failed_sessions": [
            _relative_label(path, root) for path in skipped_failed_paths
        ],
        "dry_run": bool(args.dry_run),
        "rerun_required": rerun_required,
        "summary": {
            "files_scanned": len(records),
            "failed_sessions_preserved": len(skipped_failed_paths),
            "pass": len(records) - non_pass,
            "non_pass": non_pass,
            "changed": sum(bool(record["changed"]) for record in records),
            "would_change": sum(bool(record["would_change"]) for record in records),
            "quarantine_required": sum(
                bool(record["quarantine_required"]) for record in records
            ),
            "rerun_required": rerun_required,
        },
        "files": records,
    }
    report_path.parent.mkdir(parents=True, exist_ok=True)
    redacted = redact_paths(payload, known_roots={root: "<INPUT_ROOT>"})
    atomic_write_json(report_path, redacted)
    return 1 if rerun_required else 0


# =========================================================================== #
# SECTION: runtest_failure_bucket
# =========================================================================== #
#!/usr/bin/env python3
"""Package unresolved runtest sessions into a non-destructive failure bucket."""

from dataclasses import asdict, dataclass
from datetime import datetime, timezone
import hashlib
import json
import os
from pathlib import Path
import shutil
from typing import Any, Sequence
import uuid


SUCCESSFUL_STEP2_STATUSES = frozenset(
    {
        "modified",
        "unchanged",
        "dry_run_planned",
        # 幂等重跑:上一轮已插好且仍能过 scoped 契约的 session,视为成功。
        "skipped_existing_valid_insert",
        # 正当跳过:planner 判定末节点没有声称测试过,不该插(2026-07-14)。
        "skipped_plan_declined",
        # 正当跳过:LLM 判定该 session 无需补测(needs_final_test=false)。
        "skipped_no_test_needed",
        # Step1 exhausted all eligible retries. The source session is retained
        # byte-for-byte and is deliberately non-blocking at TASK scope.
        "skipped_runtest_failed_unchanged",
        # 兼容旧状态(历史遗留,当前流程不再产生)。
        "skipped_source_already_pass",
    }
)
# 「判官放行、原样保留」的 STEP2 状态:这类会话**没有合成测试块**,是否可交付由 LLM 判官
# (needs_final_test / planner)裁决,不由确定性 validate_messages 裁决。route 层(collect_failure_records)
# 已豁免它们不进 _failed;链尾 ⑤ 最终校验必须与之一致——否则 ④/⑤ 会因这些会话的**插入前既有**
# 轨迹问题(NO_TEST_BLOCK / STALE_TEST_PASS / ORPHAN_TOOL_RESULT 等)把整个 TASK 判失败且无从收敛。
RELEASED_STEP2_STATUSES = frozenset(
    {
        "skipped_no_test_needed",
        "skipped_plan_declined",
        "skipped_source_already_pass",
    }
)
STEP2_INCOMPLETE_REASONS = {
    "error_existing_block_incomplete": "EXISTING_BLOCK_INCOMPLETE",
    "error_post_insert_validation": "POST_INSERT_VALIDATION_FAILED",
    "skipped_last_node_not_assistant": "MISSING_TERMINAL_ASSISTANT",
    "skipped_no_messages": "NO_MESSAGES_ARRAY",
    "skipped_root_not_object": "INVALID_SESSION_ROOT",
    "error_read_json": "INVALID_JSON",
}


@dataclass(frozen=True)
class FailureRecord:
    task_name: str
    session_name: str
    verdict: str
    reason_codes: tuple[str, ...]
    decision_source: str
    retry_count: int = 0
    attempts: tuple[dict[str, Any], ...] = ()


@dataclass(frozen=True)
class FailurePackageResult:
    failed_root: Path
    tasks_packaged: int
    sessions_packaged: int


def _load_json_object(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8-sig"))
    if not isinstance(value, dict):
        raise ValueError(f"expected a JSON object: {path}")
    return value


def _step1_details_by_session(
    summary_path: Path,
) -> dict[tuple[str, str], dict[str, Any]]:
    if not summary_path.is_file():
        return {}
    summary = _load_json_object(summary_path)
    indexed: dict[tuple[str, str], dict[str, Any]] = {}

    def _is_ok(detail: dict[str, Any]) -> bool:
        v = str(detail.get("verdict") or "")
        return not v or v in ("PASS", NO_TEST_NEEDED_VERDICT)

    for detail in summary.get("details") or []:
        if not isinstance(detail, dict):
            continue
        source_session = detail.get("source_session")
        if not isinstance(source_session, dict):
            continue
        session_name = str(source_session.get("source_session_name") or "")
        raw_task_dir = str(detail.get("task_dir") or "")
        task_name = Path(raw_task_dir).name
        summary_root = summary_path.resolve().parent
        # A single-TASK summary redacts its exact task_dir to <ROOT>. Recover
        # the real task name from the summary location so routing and skip
        # policy can still match sessions/<name> deterministically.
        if task_name in {"<ROOT>", "<INPUT_ROOT>", "<TASK_ROOT>"} and (
            summary_root / "sessions"
        ).is_dir():
            task_name = summary_root.name
        if task_name and session_name:
            key = (task_name, session_name)
            existing = indexed.get(key)
            # 同一 session 可能有多条摘要（终态 run + 若干节点级 run）。routing 关心的是
            # 「有没有任何一次失败」：优先保留失败条目，绝不让靠后的成功 run 掩盖靠前的失败 run。
            if existing is None or (_is_ok(existing) and not _is_ok(detail)):
                indexed[key] = detail
    return indexed


def _step1_detail_is_success(detail: dict[str, Any]) -> bool:
    return str(detail.get("status") or "") == "ok" and str(
        detail.get("verdict") or ""
    ) in {Verdict.PASS.value, NO_TEST_NEEDED_VERDICT}


def _step1_summary_path_for_root(root: Path) -> Path:
    resolved = root.expanduser().resolve()
    if resolved.is_file() and resolved.parent.name == "sessions":
        return resolved.parent.parent / "runtest_summary.json"
    return resolved / "runtest_summary.json"


def _session_task_key(path: Path) -> tuple[str, str]:
    resolved = path.expanduser().resolve()
    task_root = (
        resolved.parent.parent
        if resolved.parent.name == "sessions"
        else find_task_root(resolved)
    )
    return task_root.name, resolved.name


def _failed_step1_session_keys(root: Path) -> set[tuple[str, str]]:
    """Sessions whose exhausted Step1 result must remain byte-for-byte unchanged."""

    summary_path = _step1_summary_path_for_root(root)
    return {
        key
        for key, detail in _step1_details_by_session(summary_path).items()
        if not _step1_detail_is_success(detail)
    }


@dataclass(frozen=True)
class Step1SkipPolicy:
    complete: bool
    successful_sessions: tuple[str, ...] = ()
    skipped_sessions: tuple[str, ...] = ()
    error: str = ""


def _step1_skip_policy(
    root: Path, session_names: Sequence[str] = ()
) -> Step1SkipPolicy:
    """Validate Step1 coverage before making its failures non-blocking.

    A missing or partial summary remains a hard TASK error. Only explicit,
    per-session non-PASS records are eligible for skip-and-preserve handling.
    """

    expected = discover_session_files(root)
    selectors = tuple(session_names)
    if selectors:
        expected = [
            path for path in expected if addtool_session_name_matches(path, selectors)
        ]
    if not expected:
        return Step1SkipPolicy(False, error="Step1 selected no main sessions")

    summary_path = _step1_summary_path_for_root(root)
    if not summary_path.is_file():
        return Step1SkipPolicy(False, error=f"missing {summary_path.name}")
    try:
        indexed = _step1_details_by_session(summary_path)
    except Exception as exc:
        return Step1SkipPolicy(False, error=f"invalid {summary_path.name}: {exc}")

    missing: list[str] = []
    successful: list[str] = []
    skipped: list[str] = []
    for path in expected:
        task_name, session_name = _session_task_key(path)
        detail = indexed.get((task_name, session_name))
        label = f"{task_name}/{session_name}"
        if detail is None:
            missing.append(label)
        elif _step1_detail_is_success(detail):
            successful.append(label)
        else:
            skipped.append(label)
    if missing:
        return Step1SkipPolicy(
            False,
            error="Step1 summary missing session result(s): " + ", ".join(missing),
        )
    return Step1SkipPolicy(
        True,
        successful_sessions=tuple(successful),
        skipped_sessions=tuple(skipped),
    )


def _source_task_path(source_root: Path, task_name: str) -> Path:
    if source_root.name == task_name and (source_root / "sessions").is_dir():
        return source_root
    return source_root / task_name


def collect_failure_records(
    *,
    root: Path,
    step1_summary_path: Path,
    add_report_paths: Sequence[Path],
) -> list[FailureRecord]:
    """Merge Step 1, Step 2, and stored-session failure evidence."""

    source_root = root.expanduser().resolve()
    step1_details = _step1_details_by_session(step1_summary_path)
    records: dict[tuple[str, str], FailureRecord] = {}
    for (task_name, session_name), detail in step1_details.items():
        step1_verdict = str(detail.get("verdict") or "")
        if not step1_verdict or step1_verdict in ("PASS", NO_TEST_NEEDED_VERDICT):
            # PASS 或「判官判定无需补测」都不是 STEP1 失败，不进失败桶。
            continue
        session_path = (
            _source_task_path(source_root, task_name) / "sessions" / session_name
        )
        if not session_path.is_file():
            continue
        attempts = tuple(
            dict(attempt)
            for attempt in detail.get("attempts") or []
            if isinstance(attempt, dict)
        )
        records[(task_name, session_name)] = FailureRecord(
            task_name=task_name,
            session_name=session_name,
            verdict=step1_verdict,
            reason_codes=tuple(
                str(reason) for reason in detail.get("reason_codes") or []
            ),
            decision_source="step1",
            retry_count=int(detail.get("retry_count") or 0),
            attempts=attempts,
        )
    for report_path in add_report_paths:
        report = _load_json_object(report_path)
        task_name = report_path.resolve().parent.parent.name
        source_task = _source_task_path(source_root, task_name)
        if not source_task.is_dir():
            continue
        for file_report in report.get("files") or []:
            if not isinstance(file_report, dict):
                continue
            session_name = Path(str(file_report.get("path") or "")).name
            if not session_name:
                continue
            step1_detail = step1_details.get((task_name, session_name), {})
            attempts = tuple(
                dict(attempt)
                for attempt in step1_detail.get("attempts") or []
                if isinstance(attempt, dict)
            )
            # STEP2 状态本身即成功(如 skipped_no_test_needed:STEP1 判 passing/无需补测而正确跳过、
            # 原样保留;或 modified/unchanged)时,file_report 里可能残留一个来自「报告门评估旧遗留 run 目录
            # (无 manifest)」的过期 verdict=NO_RELIABLE_TEST_EVIDENCE。绝不能用这个过期 verdict 把一个被
            # 正确放行的 passing session 误分流到 _failed——成功状态下跳过 candidate/report verdict 失败判定,
            # 交由下方基于 status 的 stored-session 校验(会对真正写坏的会话兜底)。
            step2_status = str(file_report.get("status") or "unknown")
            _status_is_success = step2_status in SUCCESSFUL_STEP2_STATUSES
            candidate_verdict = str(file_report.get("candidate_verdict") or "")
            if candidate_verdict and candidate_verdict != "PASS" and not _status_is_success:
                records[(task_name, session_name)] = FailureRecord(
                    task_name=task_name,
                    session_name=session_name,
                    verdict=candidate_verdict,
                    reason_codes=tuple(
                        str(reason)
                        for reason in file_report.get("candidate_reason_codes") or []
                    ),
                    decision_source="candidate_gate",
                    retry_count=int(step1_detail.get("retry_count") or 0),
                    attempts=attempts,
                )
                continue
            report_verdict = str(file_report.get("verdict") or "")
            if report_verdict and report_verdict != "PASS" and not _status_is_success:
                if (task_name, session_name) not in records:
                    records[(task_name, session_name)] = FailureRecord(
                        task_name=task_name,
                        session_name=session_name,
                        verdict=report_verdict,
                        reason_codes=tuple(
                            str(reason)
                            for reason in file_report.get("reason_codes") or []
                        ),
                        decision_source="step2_report_gate",
                        retry_count=int(step1_detail.get("retry_count") or 0),
                        attempts=attempts,
                    )
                continue
            status = str(file_report.get("status") or "unknown")
            if status in SUCCESSFUL_STEP2_STATUSES:
                # 精简（需求）：成功插入/正当放行的会话不再跑「插入后 stored 校验」把已通过的插入
                # 反向判失败。是否插入成功的唯一判据已在插入前由 report gate(exit==0 且无失败测试)确定。
                continue
            if (task_name, session_name) in records:
                continue
            if status in STEP2_INCOMPLETE_REASONS:
                verdict = "INCOMPLETE_TRACE"
                default_reasons = (STEP2_INCOMPLETE_REASONS[status],)
            else:
                verdict = "NO_RELIABLE_TEST_EVIDENCE"
                default_reasons = (status.upper(),)
            reported_reasons = tuple(
                str(reason) for reason in file_report.get("reason_codes") or []
            )
            records[(task_name, session_name)] = FailureRecord(
                task_name=task_name,
                session_name=session_name,
                verdict=verdict,
                reason_codes=reported_reasons or default_reasons,
                decision_source="step2_delivery",
                retry_count=int(step1_detail.get("retry_count") or 0),
                attempts=attempts,
            )
    return [records[key] for key in sorted(records)]


def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _validate_roots(root: Path, failed_root: Path) -> tuple[Path, Path]:
    source = root.expanduser().resolve()
    destination = failed_root.expanduser().resolve()
    if source == destination:
        raise ValueError("failed_root must not equal the input root")
    try:
        destination.relative_to(source)
    except ValueError:
        pass
    else:
        raise ValueError("failed_root must not be inside the input root")
    return source, destination


def _copy_optional_tree(source: Path, destination: Path) -> bool:
    if not source.is_dir():
        return False
    # symlinks=True:repo 快照常带指向原作者机器的悬空符号链接(.venv/bin/python*),
    # 默认的"跟随并复制目标"会抛 shutil.Error 把整个失败分流打死;原样复制链接即可。
    shutil.copytree(
        source,
        destination,
        dirs_exist_ok=True,
        symlinks=True,
        ignore_dangling_symlinks=True,
    )
    return True


def _record_payload(
    record: FailureRecord,
    *,
    session_path: Path,
    preserved_paths: list[str],
) -> dict[str, Any]:
    payload = asdict(record)
    payload["session"] = payload.pop("session_name")
    payload.pop("task_name", None)
    payload["reason_codes"] = list(record.reason_codes)
    payload["attempts"] = list(record.attempts)
    payload["session_sha256"] = _sha256(session_path)
    payload["preserved_paths"] = preserved_paths
    return payload


def package_failure_sessions(
    *,
    root: Path,
    failed_root: Path,
    records: Sequence[FailureRecord],
) -> FailurePackageResult:
    """Copy failed sessions and the minimal rerunnable task context by task."""

    source_root, destination_root = _validate_roots(root, failed_root)
    grouped: dict[str, list[FailureRecord]] = {}
    for record in records:
        grouped.setdefault(record.task_name, []).append(record)
    destination_root.mkdir(parents=True, exist_ok=True)

    sessions_packaged = 0
    for task_name, task_records in sorted(grouped.items()):
        source_task = _source_task_path(source_root, task_name)
        if not source_task.is_dir():
            raise FileNotFoundError(f"missing source task: {source_task}")
        destination_task = destination_root / task_name
        staging_task = destination_root / f".{task_name}.tmp-{uuid.uuid4().hex}"
        backup_task = destination_root / f".{task_name}.bak-{uuid.uuid4().hex}"
        try:
            if destination_task.is_dir():
                shutil.copytree(
                    destination_task,
                    staging_task,
                    symlinks=True,
                    ignore_dangling_symlinks=True,
                )
            else:
                staging_task.mkdir(parents=True)
            _copy_optional_tree(source_task / "repo", staging_task / "repo")
            metadata_path = source_task / "metadata.json"
            if metadata_path.is_file():
                shutil.copy2(metadata_path, staging_task / metadata_path.name)

            manifest_path = staging_task / "failure_manifest.json"
            manifest_records_by_session: dict[str, dict[str, Any]] = {}
            if manifest_path.is_file():
                existing_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
                for item in existing_manifest.get("sessions") or []:
                    if isinstance(item, dict) and item.get("session"):
                        manifest_records_by_session[str(item["session"])] = item
            for record in sorted(task_records, key=lambda item: item.session_name):
                source_session = source_task / "sessions" / record.session_name
                if not source_session.is_file():
                    raise FileNotFoundError(f"missing source session: {source_session}")
                destination_session = staging_task / "sessions" / record.session_name
                destination_session.parent.mkdir(parents=True, exist_ok=True)
                if not destination_session.exists():
                    shutil.copy2(source_session, destination_session)
                preserved_paths = [f"sessions/{record.session_name}"]

                session_stem = source_session.stem
                if _copy_optional_tree(
                    source_task / "sessions" / session_stem,
                    staging_task / "sessions" / session_stem,
                ):
                    preserved_paths.append(f"sessions/{session_stem}/")
                if _copy_optional_tree(
                    source_task / "report" / session_stem,
                    staging_task / "report" / session_stem,
                ):
                    preserved_paths.append(f"report/{session_stem}/")
                manifest_records_by_session[record.session_name] = _record_payload(
                    record,
                    session_path=destination_session,
                    preserved_paths=preserved_paths,
                )
                sessions_packaged += 1

            manifest_payload = {
                "schema_version": "1.0",
                "generated_at": datetime.now(timezone.utc).isoformat(),
                "task": task_name,
                "sessions": [
                    manifest_records_by_session[name]
                    for name in sorted(manifest_records_by_session)
                ],
            }
            atomic_write_json(
                manifest_path,
                redact_paths(
                    manifest_payload,
                    known_roots={
                        source_root: "<ROOT>",
                        destination_root: "<FAILED_ROOT>",
                    },
                ),
            )
            if destination_task.exists():
                os.replace(destination_task, backup_task)
                try:
                    os.replace(staging_task, destination_task)
                except Exception:
                    os.replace(backup_task, destination_task)
                    raise
                shutil.rmtree(backup_task, ignore_errors=True)
            else:
                os.replace(staging_task, destination_task)
        except Exception:
            shutil.rmtree(staging_task, ignore_errors=True)
            shutil.rmtree(backup_task, ignore_errors=True)
            raise

    return FailurePackageResult(
        failed_root=destination_root,
        tasks_packaged=len(grouped),
        sessions_packaged=sessions_packaged,
    )


# =========================================================================== #
# SECTION: add_run_test_tool
# =========================================================================== #
#!/usr/bin/env python3
"""
Insert real test-run tool nodes from report JSONL trajectories into source sessions.

Typical use:
  python3 script/add_run_test_tool.py \
    -r data1/TASK-20260519-D03579

What this script does:
1. Find TASK*/sessions/*.json source trajectories.
2. Find matching TASK*/report/<session-stem>/*.jsonl runner trajectories.
3. Extract real test-related tool_use/tool_result pairs, e.g. Bash run_tests.sh.
4. Use an LLM planner, following the same Anthropic Messages API style as
   modify_assistant_content.py, to decide whether and which tool events to insert.
5. Insert user(synthetic intro) + assistant(tool_calls) + tool result nodes
   immediately before the target assistant completion/verification-claim message,
   which then serves as the closing summary.
6. If the report run is a clean pass, append one concise verification sentence
   (command + pass/fail counts) to that target assistant's content only — no other
   node or field is touched.
7. Write a JSON audit report under <TASK>/report/.

The script never fabricates a test result. If a report JSONL only contains an
authentication failure and no tool_result, it records a skipped item.

Token metadata normalization is intentionally left to its dedicated cleanup stage;
this insertion step does not rewrite unrelated session or subagent metadata.
"""

import argparse
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor, as_completed
from fnmatch import fnmatch
from dataclasses import asdict, dataclass, field, replace
from datetime import datetime, timedelta, timezone
import hashlib
import json
import os
import re
import threading
from pathlib import Path
from typing import Any, Callable

import requests
StoredSessionVerdict = StoredVerdict
STORED_PASS_CLAIM_RE = _ASSISTANT_PASS_COUNT_RE
stored_block_is_synthetic = _block_is_synthetic
stored_last_runner_pass_count = _last_runner_pass_count
validate_stored_session = validate_messages


SCRIPT_DIR = Path(__file__).resolve().parent
DEFAULT_ENV_PATH = SCRIPT_DIR / ".env"
# 并发 worker 的日志按 session 攒块后经此锁原子输出,避免行错位。
_PRINT_LOCK = threading.Lock()
DEFAULT_BASE_URL = "https://ai.mindflow.com.cn"
DEFAULT_ANTHROPIC_VERSION = "2023-06-01"
DEFAULT_MODEL = "claude-opus-4-8"
# MAX_TOOL_PAIRS 只约束 planner 可选的**测试步**数量(每锚点选 1 个 verdict 测试步)。
# 金标补测插入的**容器启动步链**长度不受此值约束,而由提取层 MAX_STARTUP_STEPS 与插入
# 层 MAX_INSERT_CHAIN_STEPS 两级共同兜底(见下)。
MAX_TOOL_PAIRS = 1
LLM_TIMEOUT_SECONDS = 120
# clean_runtest_evidence.py 用这个短语识别"管线插入的合成块"(scoped 严格契约只审
# 带此标记的块);user intro 与 assistant intro 都必须包含它,否则插入块无法被识别。
RUNTEST_INTRO_MARKER = "run the discovered test runner"
DEFAULT_ASSISTANT_INTRO = (
    "I'll run the discovered test runner to verify the previous changes."
)

SYSTEM_PROMPT = """You are a strict trajectory repair planner.

You will be given an assistant completion claim from a source session, plus
candidate tool calls that were really extracted from the report JSONL.

Task:
1. Decide whether the candidate tool call(s) should be inserted before that
   assistant message.
2. You may only select candidates that already have a real tool_result; never
   fabricate test output.
3. Prefer test-runner commands, e.g. run_tests.sh, go test, go vet, pytest.
4. If a candidate comes from the same source session and proves that tests were
   "actually attempted", it should be selected.
5. If there is no suitable candidate, should_insert must be false.

Output only a JSON object. Do not output explanations, Markdown, or code fences:
{
  "should_insert": true,
  "selected_event_indices": [0],
  "assistant_intro": "I'll run the discovered test runner to verify the previous changes.",
  "reason": "The assistant claimed tests were added but the source session has no real test execution before that claim."
}
"""


@dataclass(frozen=True)
class RuntimeConfig:
    api_key: str
    base_url: str
    anthropic_version: str
    model: str
    env_path: str = ""


@dataclass
class ToolEvent:
    event_index: int
    source_jsonl: str
    source_line_tool_use: int
    source_line_tool_result: int
    report_session_id: str
    tool_use_id: str
    tool_name: str
    tool_input: dict[str, Any]
    command: str
    description: str
    result_content: str
    result_is_error: bool
    tool_use_timestamp: str
    tool_result_timestamp: str
    # 该 tool_use 所属 assistant 消息在原生 stream-json 里的真实 usage(message.usage)
    tool_use_usage: dict[str, Any] = field(default_factory=dict)
    run_id: str = ""
    # 发起该 tool_use 的 assistant 在原生轨迹里的真实叙述文本(同条消息的 text 块,
    # 或紧邻其前的 assistant text 行)。金标补测用它当插入节点的自然叙述,而非写死的
    # intro;缺失则为空串,由构造层回退到默认 intro。
    assistant_text: str = ""


@dataclass(frozen=True)
class ReportGate:
    verdict: str
    reason_codes: tuple[str, ...]
    run_dir: Path | None = None
    run_id: str = ""
    manifest: dict[str, Any] | None = None
    stream_path: Path | None = None
    native_paths: tuple[Path, ...] = ()
    verdict_result: VerdictResult | None = None


def _artifact_path(run_dir: Path, reference: Any) -> Path | None:
    if not isinstance(reference, str) or not reference:
        return None
    candidate = Path(reference)
    if not candidate.is_absolute():
        candidate = run_dir / candidate
    try:
        resolved = candidate.resolve()
        resolved.relative_to(run_dir.resolve())
    except (OSError, ValueError):
        return None
    return resolved if resolved.is_file() else None


def _gate_cohort_key(path: Path) -> tuple[int, tuple[Any, ...], str]:
    timestamp_match = re.match(r"^(\d{8})-(\d{6})-(\d{6})(?:-|$)", path.name)
    if timestamp_match:
        return (
            3,
            tuple(int(part) for part in timestamp_match.groups()),
            path.as_posix(),
        )
    legacy_run_match = re.match(r"^run[-_](\d+)(?:\D|$)", path.name, re.I)
    if legacy_run_match:
        return (2, (int(legacy_run_match.group(1)),), path.as_posix())
    natural = tuple(
        (0, int(part)) if part.isdigit() else (1, part.lower())
        for part in re.split(r"(\d+)", path.name)
        if part
    )
    return 1, natural, path.as_posix()


def _gate_cohort_dirs(session_path: Path, report_root: Path) -> list[Path]:
    report_dirs = matching_report_dirs(session_path, report_root=report_root)
    cohort_dirs: list[Path] = []
    for report_dir in report_dirs:
        nested_runs = sorted(path for path in report_dir.iterdir() if path.is_dir())
        if nested_runs:
            cohort_dirs.extend(nested_runs)
        elif (report_dir / "manifest.json").is_file() or any(
            report_dir.glob("*.jsonl")
        ):
            cohort_dirs.append(report_dir)
    return cohort_dirs


def _manifest_scope_node(run_dir: Path) -> int | None:
    """Read scope_node_index from a run dir's manifest (None = terminal run)."""
    try:
        manifest = json.loads(
            (run_dir / "manifest.json").read_text(encoding="utf-8-sig")
        )
    except Exception:  # noqa: BLE001
        return None
    value = manifest.get("scope_node_index") if isinstance(manifest, dict) else None
    if isinstance(value, bool):
        return None
    return value if isinstance(value, int) else None


def evaluate_session_report_gate(
    session_path: Path, *, report_root: Path
) -> ReportGate:
    cohort_dirs = _gate_cohort_dirs(session_path, report_root)
    if not cohort_dirs:
        return ReportGate(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE.value,
            reason_codes=("MISSING_MANIFEST",),
        )
    run_dir = max(set(cohort_dirs), key=_gate_cohort_key)
    return _evaluate_run_dir(session_path, run_dir)


def evaluate_session_report_gates(
    session_path: Path, *, report_root: Path
) -> list[tuple[int | None, ReportGate]]:
    """Scope-aware gate: one (scope_node_index, gate) per distinct run scope.

    Groups run dirs by their manifest's ``scope_node_index`` (None = terminal
    full-suite run, int = repo@N node-scoped run) and evaluates the NEWEST run in
    each group. Enables Req4 node-scoped insertion: the terminal group anchors at
    the last node; each node-N group anchors before node N.
    """
    cohort_dirs = _gate_cohort_dirs(session_path, report_root)
    by_scope: dict[int | None, list[Path]] = {}
    for run_dir in cohort_dirs:
        by_scope.setdefault(_manifest_scope_node(run_dir), []).append(run_dir)
    out: list[tuple[int | None, ReportGate]] = []
    for scope, dirs in by_scope.items():
        newest = max(set(dirs), key=_gate_cohort_key)
        out.append((scope, _evaluate_run_dir(session_path, newest)))
    # Deterministic order: terminal first, then ascending node index.
    out.sort(key=lambda t: (t[0] is not None, t[0] if t[0] is not None else -1))
    return out


def _evaluate_run_dir(session_path: Path, run_dir: Path) -> ReportGate:
    manifest_path = run_dir / "manifest.json"
    if not manifest_path.is_file():
        return ReportGate(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE.value,
            reason_codes=("MISSING_MANIFEST",),
            run_dir=run_dir,
        )
    try:
        manifest_value = json.loads(manifest_path.read_text(encoding="utf-8-sig"))
        validate_manifest_schema(manifest_value)
        manifest = dict(manifest_value)
    except (OSError, json.JSONDecodeError, SchemaVersionError, TypeError):
        return ReportGate(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE.value,
            reason_codes=("INVALID_MANIFEST_SCHEMA",),
            run_dir=run_dir,
        )

    run_id = str(manifest.get("run_id") or "")
    # 精简：只做「定位工件 → 跑一次 evaluate_report_artifacts → PASS 即可插入」。
    # 之前的 SOURCE_SESSION_MISMATCH / SESSION_IDENTITY_MISMATCH / MANIFEST_ARTIFACT_COLLISION /
    # BACKGROUND_TEST_EVIDENCE_NOT_INLINE / MANIFEST_VERDICT_MISMATCH 等一致性/身份交叉校验闸门
    # 经常误报失败、拦住本已通过的插入，已按需求移除。成功口径唯一：runner exit==0 且无失败测试
    # （由 evaluate_report_artifacts 判定）。
    stream_path = _artifact_path(run_dir, manifest.get("stream_jsonl"))
    mappings = manifest.get("session_mappings")
    native_paths: list[Path] = []
    if isinstance(mappings, list):
        for mapping in mappings:
            if not isinstance(mapping, dict):
                continue
            native_path = _artifact_path(run_dir, mapping.get("copied_native_jsonl"))
            if native_path is not None:
                native_paths.append(native_path)
    if stream_path is None or not native_paths:
        return ReportGate(
            verdict=Verdict.NO_RELIABLE_TEST_EVIDENCE.value,
            reason_codes=("MISSING_MANIFEST_ARTIFACT",),
            run_dir=run_dir,
            run_id=run_id,
            manifest=manifest,
        )

    verdict_result = evaluate_report_artifacts(
        stream_path=stream_path,
        native_paths=native_paths,
        expected_runner=str(manifest["expected_runner"]),
    )
    evaluated_reasons = tuple(reason.value for reason in verdict_result.reason_codes)
    return ReportGate(
        verdict=verdict_result.verdict.value,
        reason_codes=evaluated_reasons,
        run_dir=run_dir,
        run_id=run_id,
        manifest=manifest,
        stream_path=stream_path,
        native_paths=tuple(native_paths),
        verdict_result=verdict_result,
    )


def load_env(path: Path) -> dict[str, str]:
    values: dict[str, str] = {}
    if not path.exists():
        return values
    for raw_line in path.read_text(encoding="utf-8-sig").splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("export "):
            line = line[len("export ") :].strip()
        if "=" not in line:
            continue
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in {"'", '"'}:
            value = value[1:-1]
        values[key] = value
    return values


def first_non_empty(*values: str | None) -> str:
    for value in values:
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return ""


def env_search_paths(root: Path, explicit_env_path: Path | None) -> list[Path]:
    paths: list[Path] = []
    if explicit_env_path is not None:
        paths.append(explicit_env_path)
    if root.is_file():
        paths.append(root.parent / ".env")
    else:
        paths.append(root / ".env")
        paths.append(root.parent / ".env")
    paths.extend([Path.cwd() / ".env", DEFAULT_ENV_PATH])

    result: list[Path] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.expanduser().resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        result.append(resolved)
    return result


def resolve_env_file(root: Path, explicit_env_path: Path | None) -> Path | None:
    paths = env_search_paths(root, explicit_env_path)
    if explicit_env_path is not None:
        return paths[0]
    for path in paths:
        if path.is_file():
            return path
    return None


def resolve_runtime_config(*, root: Path, env_path: Path | None = None) -> RuntimeConfig:
    resolved_env_path = resolve_env_file(root, env_path)
    env_file = load_env(resolved_env_path) if resolved_env_path else {}
    environ = os.environ
    return RuntimeConfig(
        api_key=first_non_empty(
            environ.get("MODEL_API_KEY"),
            environ.get("ANTHROPIC_API_KEY"),
            env_file.get("MODEL_API_KEY"),
            env_file.get("ANTHROPIC_API_KEY"),
        ),
        base_url=first_non_empty(
            environ.get("MODEL_BASE_URL"),
            environ.get("ANTHROPIC_BASE_URL"),
            environ.get("DEFAULT_BASE_URL"),
            env_file.get("MODEL_BASE_URL"),
            env_file.get("ANTHROPIC_BASE_URL"),
            env_file.get("DEFAULT_BASE_URL"),
            DEFAULT_BASE_URL,
        ),
        anthropic_version=first_non_empty(
            environ.get("ANTHROPIC_VERSION"),
            environ.get("MODEL_ANTHROPIC_VERSION"),
            env_file.get("ANTHROPIC_VERSION"),
            env_file.get("MODEL_ANTHROPIC_VERSION"),
            DEFAULT_ANTHROPIC_VERSION,
        ),
        model=first_non_empty(
            # 专用变量 ADD_RUN_TEST_TOOL_MODEL(planner 模型)优先于通用 MODEL_NAME，
            # 使 planner 与判官(读 MODEL_NAME)可各自独立取模型。
            environ.get("ADD_RUN_TEST_TOOL_MODEL"),
            env_file.get("ADD_RUN_TEST_TOOL_MODEL"),
            environ.get("MODEL_NAME"),
            environ.get("DEFAULT_MODEL"),
            env_file.get("MODEL_NAME"),
            env_file.get("DEFAULT_MODEL"),
            DEFAULT_MODEL,
        ),
        env_path=str(resolved_env_path) if resolved_env_path else "",
    )


def anthropic_messages_url(base_url: str) -> str:
    base = base_url.rstrip("/")
    if base.endswith("/v1/messages"):
        return base
    if base.endswith("/messages"):
        return base
    if base.endswith("/v1"):
        return f"{base}/messages"
    return f"{base}/v1/messages"


def strip_wrapping(text: str) -> str:
    cleaned = text.strip()
    if cleaned.startswith("```"):
        lines = cleaned.splitlines()
        lines = lines[1:]
        if lines and lines[-1].strip().startswith("```"):
            lines = lines[:-1]
        cleaned = "\n".join(lines).strip()
    return cleaned


def parse_json_object(text: str) -> dict[str, Any]:
    cleaned = strip_wrapping(text)
    try:
        data = json.loads(cleaned)
    except json.JSONDecodeError:
        start = cleaned.find("{")
        end = cleaned.rfind("}")
        if start == -1 or end == -1 or end <= start:
            raise
        data = json.loads(cleaned[start : end + 1])
    if not isinstance(data, dict):
        raise ValueError("LLM response is not a JSON object")
    return data


def normalize_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts: list[str] = []
        for item in value:
            if isinstance(item, dict):
                if item.get("type") == "text" and item.get("text"):
                    parts.append(str(item["text"]))
                elif item.get("text"):
                    parts.append(str(item["text"]))
                else:
                    parts.append(str(item))
            else:
                parts.append(str(item))
        return "\n".join(part for part in parts if part)
    if isinstance(value, dict) and value.get("text"):
        return str(value["text"])
    return str(value)


def call_llm_plan(
    *,
    config: RuntimeConfig,
    user_prompt: str,
    timeout: int,
) -> dict[str, Any]:
    payload = {
        "model": config.model,
        "max_tokens": 2048,
        "system": SYSTEM_PROMPT,
        "messages": [{"role": "user", "content": user_prompt}],
    }
    headers = {
        "x-api-key": config.api_key,
        "anthropic-version": config.anthropic_version,
        "content-type": "application/json",
    }
    response = requests.post(
        anthropic_messages_url(config.base_url),
        headers=headers,
        json=payload,
        timeout=timeout,
    )
    if response.status_code != 200:
        raise RuntimeError(f"LLM API error {response.status_code}: {response.text[:500]}")
    data = response.json()
    blocks = data.get("content", [])
    text = "\n".join(
        block.get("text", "") for block in blocks if block.get("type") == "text"
    )
    return parse_json_object(text)


def find_task_root(path: Path) -> Path:
    resolved = path.resolve()
    if resolved.is_dir() and resolved.name.startswith("TASK-"):
        return resolved
    if resolved.parent.name == "sessions":
        return resolved.parent.parent
    for parent in resolved.parents:
        if parent.name.startswith("TASK-"):
            return parent
    return resolved.parent


def addtool_session_name_matches(path: Path, selectors: tuple[str, ...]) -> bool:
    '''True if `path` matches any --session-name selector (exact name, stem, or glob).'''
    name = path.name
    stem = path.stem
    for sel in selectors:
        if sel == name or sel == stem or fnmatch(name, sel) or fnmatch(stem, sel):
            return True
    return False


def discover_session_files(root: Path) -> list[Path]:
    root = root.resolve()
    if root.is_file():
        return [root]
    if (root / "sessions").is_dir():
        return sorted(
            path
            for path in (root / "sessions").glob("*.json")
            if path.is_file()
            and path.parent.name == "sessions"
            and _is_main_session_path(path)
        )
    files: list[Path] = []
    for path in sorted(root.rglob("sessions/*.json")):
        if path.parent.name != "sessions":
            continue
        if not _is_main_session_path(path):
            continue
        if any(parent.name.startswith("TASK-") for parent in path.parents):
            files.append(path)
    return files


def find_message_list(data: dict[str, Any]) -> list[dict[str, Any]] | None:
    for key in ("messages", "chat_messages", "conversation", "history"):
        value = data.get(key)
        if isinstance(value, list):
            return value
    return None


def delivery_tool_id(event: ToolEvent) -> str:
    digest = hashlib.sha256(
        f"{event.run_id}:{event.tool_use_id}".encode("utf-8")
    ).hexdigest()[:20]
    return f"toolu_runtest_{digest}"


def inspect_existing_insert(
    messages: list[dict[str, Any]], event: ToolEvent
) -> str:
    for index, message in enumerate(messages):
        if message.get("role") != "assistant":
            continue
        calls = [call for call in message.get("tool_calls") or [] if isinstance(call, dict)]
        target_call: dict[str, Any] | None = None
        for call in calls:
            if not isinstance(call, dict) or not call.get("id"):
                continue
            function = call.get("function")
            if not isinstance(function, dict) or function.get("name") != event.tool_name:
                continue
            try:
                arguments = json.loads(str(function.get("arguments") or "{}"))
            except json.JSONDecodeError:
                continue
            if not isinstance(arguments, dict) or str(arguments.get("command") or "") != event.command:
                continue
            target_call = call
            break
        if target_call is None:
            continue
        call_ids = [str(call.get("id")) for call in calls if call.get("id")]
        result_counts = {call_id: 0 for call_id in call_ids}
        target_content_matches = False
        cursor = index + 1
        while cursor < len(messages):
            tool_message = messages[cursor]
            if not isinstance(tool_message, dict) or tool_message.get("role") != "tool":
                break
            result_id = str(tool_message.get("tool_call_id") or "")
            if result_id in result_counts:
                result_counts[result_id] += 1
            if (
                result_id == str(target_call.get("id"))
                and normalize_text(tool_message.get("content")) == event.result_content
            ):
                target_content_matches = True
            cursor += 1
        has_closing_summary = (
            cursor < len(messages)
            and isinstance(messages[cursor], dict)
            and messages[cursor].get("role") == "assistant"
            and not messages[cursor].get("tool_calls")
            and bool(normalize_text(messages[cursor].get("content")).strip())
        )
        if (
            call_ids
            and all(result_counts[call_id] == 1 for call_id in call_ids)
            and target_content_matches
            and has_closing_summary
        ):
            return "valid"
        return "incomplete"
    return "absent"


def has_existing_insert(messages: list[dict[str, Any]], event: ToolEvent) -> bool:
    return inspect_existing_insert(messages, event) == "valid"


def validate_delivery_messages(messages: list[dict[str, Any]]) -> tuple[str, ...]:
    """Validate global tool pairing and the normal terminal assistant contract."""

    call_positions: dict[str, int] = {}
    result_positions: dict[str, int] = {}
    for index, message in enumerate(messages):
        if not isinstance(message, dict):
            return ("MALFORMED_MESSAGE",)
        if message.get("role") == "assistant":
            calls = message.get("tool_calls") or []
            if not isinstance(calls, list):
                return ("MALFORMED_TOOL_CALLS",)
            for call in calls:
                call_id = call.get("id") if isinstance(call, dict) else None
                if not isinstance(call_id, str) or not call_id:
                    return ("MALFORMED_TOOL_CALL",)
                if call_id in call_positions:
                    return ("DUPLICATE_TOOL_CALL",)
                call_positions[call_id] = index
        if message.get("role") == "tool":
            result_id = message.get("tool_call_id")
            if not isinstance(result_id, str) or not result_id:
                return ("MALFORMED_TOOL_RESULT",)
            if result_id in result_positions:
                return ("DUPLICATE_TOOL_RESULT",)
            result_positions[result_id] = index
    missing_results = set(call_positions) - set(result_positions)
    if missing_results:
        return ("DANGLING_TOOL_CALL",)
    orphan_results = set(result_positions) - set(call_positions)
    if orphan_results:
        return ("ORPHAN_TOOL_RESULT",)
    if any(
        result_positions[call_id] <= call_index
        for call_id, call_index in call_positions.items()
    ):
        return ("TOOL_RESULT_BEFORE_CALL",)
    if not messages:
        return ("MISSING_TERMINAL_ASSISTANT",)
    terminal = messages[-1]
    if (
        terminal.get("role") != "assistant"
        or terminal.get("tool_calls")
        or not normalize_text(terminal.get("content")).strip()
    ):
        return ("INVALID_TERMINAL_ASSISTANT",)
    return ()



def safe_report_name(value: str) -> str:
    """Mirror run_claude_runtests.safe_name for per-session report folders."""
    cleaned = re.sub(r"[^A-Za-z0-9_.-]+", "_", value.strip())
    return cleaned.strip("._") or "unnamed"


def matching_report_dirs(
    session_path: Path,
    *,
    report_root: Path,
) -> list[Path]:
    if not report_root.is_dir():
        return []
    stem = session_path.stem
    candidates = {stem, safe_report_name(stem)}
    task_name = safe_report_name(find_task_root(session_path).name)
    scoped_parent = (
        report_root
        if report_root.name == task_name
        else report_root / task_name
    )
    if scoped_parent.is_dir():
        scoped_containers = [
            scoped_parent / candidate
            for candidate in candidates
            if (scoped_parent / candidate).is_dir()
        ]
        if scoped_containers:
            return sorted(set(scoped_containers))
    containers: set[Path] = set()
    if report_root.name in candidates and (
        (report_root / "manifest.json").is_file() or any(report_root.glob("*.jsonl"))
    ):
        containers.add(report_root)
    for candidate in candidates:
        container = report_root / candidate
        if container.is_dir():
            containers.add(container)
    return sorted(containers)


def jsonl_message_content(obj: dict[str, Any]) -> Any:
    message = obj.get("message")
    if isinstance(message, dict):
        return message.get("content")
    return None


def jsonl_message_usage(obj: dict[str, Any]) -> dict[str, Any]:
    """原生 stream-json 行里,该 assistant 消息的真实 token 用量(message.usage)。

    发起 tool_use 的那条 assistant 消息即代表一次真实 API 调用,其 usage 就是
    这次调用的真实计费,用它填充插入 assistant 节点的 _metadata.tokens 最贴切。
    """
    message = obj.get("message")
    if isinstance(message, dict) and isinstance(message.get("usage"), dict):
        return message["usage"]
    if isinstance(obj.get("usage"), dict):
        return obj["usage"]
    return {}



def iter_tool_uses(obj: dict[str, Any]) -> list[dict[str, Any]]:
    content = jsonl_message_content(obj)
    if not isinstance(content, list):
        return []
    return [
        item
        for item in content
        if isinstance(item, dict) and item.get("type") == "tool_use" and item.get("id")
    ]


def iter_tool_results(obj: dict[str, Any]) -> list[dict[str, Any]]:
    content = jsonl_message_content(obj)
    if not isinstance(content, list):
        return []
    return [
        item
        for item in content
        if isinstance(item, dict) and item.get("type") == "tool_result" and item.get("tool_use_id")
    ]


def tool_result_text(item: dict[str, Any]) -> str:
    content = item.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for block in content:
            if isinstance(block, dict):
                parts.append(normalize_text(block))
            else:
                parts.append(str(block))
        return "\n".join(parts)
    return normalize_text(content)


def extract_gate_selected_event(gate: ReportGate) -> ToolEvent | None:
    verdict_result = gate.verdict_result
    selected = verdict_result.selected_attempt if verdict_result else None
    if selected is None:
        return None

    tool_record: tuple[Path, int, dict[str, Any], dict[str, Any]] | None = None
    result_record: tuple[int, dict[str, Any], dict[str, Any]] | None = None
    for native_path in gate.native_paths:
        with native_path.open("r", encoding="utf-8", errors="replace") as handle:
            for line_no, raw_line in enumerate(handle, start=1):
                if not raw_line.strip():
                    continue
                try:
                    obj = json.loads(raw_line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(obj, dict):
                    continue
                for tool_use in iter_tool_uses(obj):
                    if str(tool_use.get("id")) == selected.tool_use_id:
                        tool_record = (native_path, line_no, obj, tool_use)
                for tool_result in iter_tool_results(obj):
                    if (
                        str(tool_result.get("tool_use_id")) == selected.tool_use_id
                        or tool_result_text(tool_result) == selected.result_text
                    ):
                        result_record = (line_no, obj, tool_result)

    if tool_record is None:
        return None
    native_path, tool_line, tool_obj, tool_use = tool_record
    tool_input = tool_use.get("input")
    if not isinstance(tool_input, dict):
        tool_input = {}
    result_line = result_record[0] if result_record else tool_line
    result_obj = result_record[1] if result_record else tool_obj
    return ToolEvent(
        event_index=0,
        source_jsonl=str(native_path),
        source_line_tool_use=tool_line,
        source_line_tool_result=result_line,
        report_session_id=str(
            result_obj.get("sessionId") or tool_obj.get("sessionId") or ""
        ),
        tool_use_id=selected.tool_use_id,
        tool_name=str(tool_use.get("name") or "Bash"),
        tool_input=dict(tool_input),
        command=selected.command,
        description=str(tool_input.get("description") or ""),
        result_content=selected.result_text,
        result_is_error=False,
        tool_use_timestamp=str(tool_obj.get("timestamp") or ""),
        tool_result_timestamp=str(result_obj.get("timestamp") or ""),
        tool_use_usage=jsonl_message_usage(tool_obj),
        run_id=gate.run_id,
    )


# 金标补测:一次插入最多保留的「启动步」数(测试步始终额外保留),故整段 ≤ 该值 + 1。
MAX_STARTUP_STEPS = 7
# 插入层防御性上限:整段(启动步 + 测试步)节点对数。提取层已按 MAX_STARTUP_STEPS 截断,
# 这里再兜一层,确保任何来源的链都不会超长;截断时保留链尾(测试步 + 最近的启动步)。
MAX_INSERT_CHAIN_STEPS = MAX_STARTUP_STEPS + 1


def _assistant_text_from_obj(obj: dict[str, Any]) -> str:
    """Extract the assistant narration text from one native stream-json line.

    Returns the concatenated `text` blocks of the message content (or a raw
    string content), stripped. Empty when the line carries no prose.
    """
    content = jsonl_message_content(obj)
    if isinstance(content, str):
        return content.strip()
    if isinstance(content, list):
        parts = [
            str(item.get("text") or "")
            for item in content
            if isinstance(item, dict) and item.get("type") == "text"
        ]
        return "\n".join(part for part in parts if part).strip()
    return ""


def _startup_event_from_records(
    *,
    native_path: Path,
    tool_line: int,
    tool_obj: dict[str, Any],
    tool_use: dict[str, Any],
    narration: str,
    result_line: int,
    result_obj: dict[str, Any],
    result_item: dict[str, Any],
    run_id: str,
) -> ToolEvent:
    tool_input = tool_use.get("input")
    if not isinstance(tool_input, dict):
        tool_input = {}
    return ToolEvent(
        event_index=0,  # reassigned by caller into chain order
        source_jsonl=str(native_path),
        source_line_tool_use=tool_line,
        source_line_tool_result=result_line,
        report_session_id=str(
            result_obj.get("sessionId") or tool_obj.get("sessionId") or ""
        ),
        tool_use_id=str(tool_use.get("id") or ""),
        tool_name=str(tool_use.get("name") or "Bash"),
        tool_input=dict(tool_input),
        command=str(tool_input.get("command") or ""),
        description=str(tool_input.get("description") or ""),
        result_content=tool_result_text(result_item),
        result_is_error=bool(result_item.get("is_error")),
        tool_use_timestamp=str(tool_obj.get("timestamp") or ""),
        tool_result_timestamp=str(result_obj.get("timestamp") or ""),
        tool_use_usage=jsonl_message_usage(tool_obj),
        run_id=run_id,
        assistant_text=narration,
    )


def extract_gate_process_events(gate: ReportGate) -> list[ToolEvent]:
    """Return the ordered runtest chain [container-startup steps…, final test step].

    The final element is the verdict-selected test attempt (identical to
    extract_gate_selected_event). Preceding it, within the SAME native jsonl, we
    recover the real docker/container startup steps (is_container_startup_command)
    so the delivered gold trajectory shows the true process — how the runtest
    container was built/started — not just the final result out of nowhere.

    Each step also carries the assistant's real narration (assistant_text) from
    the report run. Startup steps whose tool_result is an error, or that have no
    captured result (dangling), are skipped — fail-closed: never ship a red or
    incomplete startup node. At most MAX_STARTUP_STEPS closest to the test are
    kept. Returns [] if the selected test event cannot be located, else a list
    whose event_index is 0..N in chain order (test step last).
    """
    selected_event = extract_gate_selected_event(gate)
    if selected_event is None:
        return []
    native_path = Path(selected_event.source_jsonl)
    test_line = selected_event.source_line_tool_use
    if not native_path.is_file():
        return [replace(selected_event, event_index=0)]

    # Single pass over the winning run's native jsonl: collect every tool_use
    # (with the narration that introduced it) and index tool_results by id.
    tool_use_records: list[tuple[int, dict[str, Any], dict[str, Any], str]] = []
    result_by_id: dict[str, tuple[int, dict[str, Any], dict[str, Any]]] = {}
    pending_text = ""
    with native_path.open("r", encoding="utf-8", errors="replace") as handle:
        for line_no, raw_line in enumerate(handle, start=1):
            if not raw_line.strip():
                continue
            try:
                obj = json.loads(raw_line)
            except json.JSONDecodeError:
                continue
            if not isinstance(obj, dict):
                continue
            uses = iter_tool_uses(obj)
            same_line_text = _assistant_text_from_obj(obj)
            if uses:
                narration = same_line_text or pending_text
                for tool_use in uses:
                    tool_use_records.append((line_no, obj, tool_use, narration))
                pending_text = ""  # consumed by this tool_use line
            elif same_line_text:
                pending_text = same_line_text
            for result_item in iter_tool_results(obj):
                rid = str(result_item.get("tool_use_id") or "")
                if rid and rid not in result_by_id:
                    result_by_id[rid] = (line_no, obj, result_item)

    startup_events: list[ToolEvent] = []
    selected_narration = ""
    for tool_line, tool_obj, tool_use, narration in tool_use_records:
        tid = str(tool_use.get("id") or "")
        if tid and tid == selected_event.tool_use_id:
            selected_narration = narration
            continue
        if tool_line >= test_line:
            continue
        tool_input = tool_use.get("input")
        command = ""
        if isinstance(tool_input, dict):
            command = str(tool_input.get("command") or "")
        if not is_container_startup_command(command):
            continue
        record = result_by_id.get(tid)
        if record is None:
            continue  # dangling tool_use — cannot insert without a real result
        result_line, result_obj, result_item = record
        if bool(result_item.get("is_error")):
            continue  # fail-closed: never ship a failed startup node
        startup_events.append(
            _startup_event_from_records(
                native_path=native_path,
                tool_line=tool_line,
                tool_obj=tool_obj,
                tool_use=tool_use,
                narration=narration,
                result_line=result_line,
                result_obj=result_obj,
                result_item=result_item,
                run_id=gate.run_id,
            )
        )

    startup_events.sort(key=lambda event: event.source_line_tool_use)
    if len(startup_events) > MAX_STARTUP_STEPS:
        # Keep the steps closest to the test (the actual container bring-up),
        # never the test step itself, which is always appended below.
        startup_events = startup_events[-MAX_STARTUP_STEPS:]

    final_event = replace(
        selected_event, event_index=0, assistant_text=selected_narration
    )
    chain = startup_events + [final_event]
    return [replace(event, event_index=idx) for idx, event in enumerate(chain)]


def is_test_tool_use(tool_use: dict[str, Any]) -> bool:
    if tool_use.get("name") != "Bash":
        return False
    tool_input = tool_use.get("input")
    if not isinstance(tool_input, dict):
        return False
    command = str(tool_input.get("command", ""))
    return is_test_command(command)


def make_planner_prompt(
    *,
    session_path: Path,
    target_index: int,
    target_content: str,
    events: list[ToolEvent],
) -> str:
    candidates: list[dict[str, Any]] = []
    for event in events:
        candidates.append(
            {
                "event_index": event.event_index,
                "tool_name": event.tool_name,
                "command": event.command,
                "description": event.description,
                "result_preview": event.result_content[:1200],
                "result_is_error": event.result_is_error,
                "source_jsonl": event.source_jsonl,
                "source_line_tool_use": event.source_line_tool_use,
                "source_line_tool_result": event.source_line_tool_result,
            }
        )
    return (
        "Decide whether a real test tool node should be inserted before the "
        "target assistant message.\n\n"
        f"source_session_path: {session_path}\n"
        f"target_message_index: {target_index}\n\n"
        "[target assistant content]\n"
        f"{target_content}\n\n"
        "[candidate real tool events]\n"
        f"{json.dumps(candidates, ensure_ascii=False, indent=2)}\n"
    )


def deterministic_plan(events: list[ToolEvent]) -> dict[str, Any]:
    if not events:
        return {
            "should_insert": False,
            "selected_event_indices": [],
            "assistant_intro": "",
            "reason": "No real test-related tool_use/tool_result pair was found.",
        }
    # events 已按最新优先排序(events[0] 最新)。选最新的一次真实测试运行,忠实反映
    # session 结束时的测试状态(哪怕是 FAIL);不再"成功优先",以免挑到早期一次
    # 恰好 PASS、却非最终状态的运行。矛盾检测在 process_session_file 里做。
    chosen = events[0]
    flag = "FAIL" if chosen.result_is_error else "PASS"
    reason = (
        f"Selected newest test-runner run (event_index={chosen.event_index}, "
        f"result={flag}, cmd={chosen.command!r})."
    )
    return {
        "should_insert": True,
        "selected_event_indices": [chosen.event_index],
        "assistant_intro": DEFAULT_ASSISTANT_INTRO,
        "reason": reason,
    }


def validate_plan(plan: dict[str, Any], events: list[ToolEvent], max_tool_pairs: int) -> dict[str, Any]:
    event_by_index = {event.event_index: event for event in events}
    raw_indexes = plan.get("selected_event_indices")
    if not isinstance(raw_indexes, list):
        raw_indexes = []
    indexes: list[int] = []
    for value in raw_indexes:
        try:
            idx = int(value)
        except (TypeError, ValueError):
            continue
        if idx in event_by_index and idx not in indexes:
            indexes.append(idx)
    indexes = indexes[:max_tool_pairs]
    should_insert = bool(plan.get("should_insert")) and bool(indexes)
    intro = str(plan.get("assistant_intro") or "").strip()
    if should_insert and RUNTEST_INTRO_MARKER not in intro.lower():
        # 无论 intro 是空还是 LLM 自拟的文案,只要缺少识别标记就回退默认 intro:
        # 该标记是下游 cleaner/validator 识别合成块、施加 scoped 严格契约的唯一依据。
        intro = DEFAULT_ASSISTANT_INTRO
    return {
        "should_insert": should_insert,
        "selected_event_indices": indexes,
        "assistant_intro": intro,
        "reason": str(plan.get("reason") or "").strip(),
    }


def collect_existing_tool_ids(messages: list[dict[str, Any]]) -> set[str]:
    ids: set[str] = set()
    for message in messages:
        if isinstance(message.get("tool_call_id"), str):
            ids.add(message["tool_call_id"])
        for call in message.get("tool_calls") or []:
            if isinstance(call, dict) and isinstance(call.get("id"), str):
                ids.add(call["id"])
    return ids


def make_unique_tool_id(event: ToolEvent, existing_ids: set[str]) -> str:
    tool_id = delivery_tool_id(event)
    existing_ids.add(tool_id)
    return tool_id


def parse_timestamp(value: Any) -> datetime | None:
    if not isinstance(value, str) or not value:
        return None
    try:
        normalized = value.replace("Z", "+00:00")
        return datetime.fromisoformat(normalized)
    except ValueError:
        return None


def format_timestamp(value: datetime | None, fallback: str = "") -> str:
    if value is None:
        return fallback or datetime.now().isoformat(timespec="milliseconds") + "Z"
    text = value.isoformat(timespec="milliseconds")
    if text.endswith("+00:00"):
        text = text[:-6] + "Z"
    return text


def event_source_metadata(event: ToolEvent) -> dict[str, Any]:
    return {
        "source_jsonl": event.source_jsonl,
        "source_line_tool_use": event.source_line_tool_use,
        "source_line_tool_result": event.source_line_tool_result,
        "source_tool_use_id": event.tool_use_id,
        "source_report_session_id": event.report_session_id,
        "source_tool_use_timestamp": event.tool_use_timestamp,
        "source_tool_result_timestamp": event.tool_result_timestamp,
    }


def _to_aware(value: datetime | None) -> datetime | None:
    if value is None:
        return None
    if value.tzinfo is None:
        return value.replace(tzinfo=timezone.utc)
    return value



def _forward_insert_times(
    selected: list[ToolEvent],
    prev_time: datetime | None,
) -> tuple[list[tuple[datetime, datetime]], datetime]:
    """锚点=末节点模型:从 prev_time 往后按真实相对时长铺放插入节点。

    返回 ([(assistant_time, tool_time), ...], suggested_target_time),其中
    suggested_target_time = 最后一个 tool 时间 + 0.5s,供调用方把末节点顺移到其后。
    每步耗时用真实 tool_result_ts - tool_use_ts、间隔用相邻事件真实差,缺失兜底;
    prev_time 缺失时以 now 为基。
    """
    buf = timedelta(seconds=0.5)
    default_gap = 2.0
    default_dur = 1.0
    n = len(selected)
    a_off: list[float] = [0.0] * n
    t_off: list[float] = [0.0] * n
    cursor = 0.0
    for i, event in enumerate(selected):
        use = _to_aware(parse_timestamp(event.tool_use_timestamp))
        res = _to_aware(parse_timestamp(event.tool_result_timestamp))
        dur = (res - use).total_seconds() if (use and res and res > use) else default_dur
        if dur <= 0:
            dur = default_dur
        a_off[i] = cursor
        t_off[i] = cursor + dur
        gap = default_gap
        if i + 1 < n:
            nxt_use = _to_aware(parse_timestamp(selected[i + 1].tool_use_timestamp))
            if nxt_use and res and nxt_use > res:
                gap = (nxt_use - res).total_seconds()
        cursor = t_off[i] + max(gap, 0.0)
    base = _to_aware(prev_time) or _to_aware(datetime.now())
    start = base + buf
    times = [
        (start + timedelta(seconds=a_off[i]), start + timedelta(seconds=t_off[i]))
        for i in range(n)
    ]
    last_tool_time = times[-1][1] if times else start
    return times, last_tool_time + buf


_ANSI_RE = re.compile(r"\x1b\[[0-9;]*[A-Za-z]")


def _strip_ansi(text: str) -> str:
    """去掉 ANSI 颜色/控制码。测试器(jest/go/phpunit 等)常输出带色汇总,如 `\\x1b[30;42mOK (34
    tests)\\x1b[0m`——颜色码末尾的 `m` 会和后面的 `OK` 连成 `mOK`、击穿 `\\bOK` 词边界等正则,导致
    成功/失败/计数全部漏识别。判定前统一 strip。"""
    if not text or "\x1b" not in text:
        return text
    return _ANSI_RE.sub("", text)


_TEST_PASS_COUNT_RE = re.compile(
    r"(?<![A-Za-z0-9_])(\d[\d,]*)\s+passed\b(?!\s*:)", re.IGNORECASE
)
_TEST_FAIL_COUNT_RE = re.compile(
    # 尾部 `(?!\s*[:=])` 挡住列对齐 `key=value` 表里的 `failed=`/`failed:` 标签:
    # `passed=223  failed=0` 若无此护栏,`\d+\s+failed` 会把 `passed=223` 的 223 桥接到
    # `failed` 上误报 223 个失败。挡掉后此类表转由下方 _KV_FAIL_RE 兜底(取 failed=0)。
    r"(?<![A-Za-z0-9_])(\d[\d,]*)\s+failed\b(?!\s*[:=])", re.IGNORECASE
)
# 非 "N passed" 框架的通过/失败计数(供 parse_test_counts 兜底)：
#   Maven surefire: "Tests run: 50, Failures: 0, Errors: 0"
#   PHPUnit:        "OK (317 tests, 1503 assertions)"
#   unittest:       "Ran 42 tests in 1.2s" + 随后 "OK"
_MVN_TESTS_RUN_RE = re.compile(
    r"Tests run:\s*(\d[\d,]*)\s*,\s*Failures:\s*(\d+)\s*,\s*Errors:\s*(\d+)", re.IGNORECASE
)
_PHPUNIT_OK_RE = re.compile(r"\bOK\s*\(\s*(\d[\d,]*)\s+tests?", re.IGNORECASE)
_UNITTEST_RAN_OK_RE = re.compile(
    r"\bRan\s+(\d[\d,]*)\s+tests?\b[\s\S]{0,80}?^\s*OK\b", re.IGNORECASE | re.MULTILINE
)
# 自建测试台常见汇总: "Passed: 164 ... Failed: 0"
_CUSTOM_PASSED_RE = re.compile(r"\bPassed:\s*(\d[\d,]*)", re.IGNORECASE)
_CUSTOM_FAILED_RE = re.compile(r"\bFailed:\s*(\d[\d,]*)", re.IGNORECASE)
# key=value 形自建汇总: "SUMMARY: total=112, pass=112, fail=0" / "passed=161 failed=0"。
_KV_PASS_RE = re.compile(r"\bpass(?:ed)?\s*=\s*(\d[\d,]*)", re.IGNORECASE)
_KV_FAIL_RE = re.compile(r"\bfail(?:ed|ures?)?\s*=\s*(\d[\d,]*)", re.IGNORECASE)
# rspec `5 examples, 0 failures`;ctest `... 0 tests failed out of 50`;mocha `2 passing` / `1 failing`。
_RSPEC_RE = re.compile(r"(\d[\d,]*)\s+examples?,\s*(\d[\d,]*)\s+failures?", re.IGNORECASE)
_CTEST_FAILED_OUT_RE = re.compile(r"(\d[\d,]*)\s+tests?\s+failed\s+out\s+of\s+(\d[\d,]*)", re.IGNORECASE)
_MOCHA_PASSING_RE = re.compile(r"(\d[\d,]*)\s+passing\b", re.IGNORECASE)
_MOCHA_FAILING_RE = re.compile(r"(\d[\d,]*)\s+failing\b", re.IGNORECASE)
_TERMINAL_RUNNER_EXIT_RE = re.compile(
    r"(?im)^\s*(?:RUNNER_EXIT|EXIT_CODE|EXIT)\s*[=:]\s*-?\d+\s*$"
)


def parse_test_counts(text: str) -> tuple[int | None, int | None]:
    """从测试输出/收尾文本里抽 (passed, failed) 计数;抽不到为 None。"""
    if not text:
        return (None, None)
    text = _strip_ansi(text)
    text = _strip_trailing_exit_sentinel(text)
    pass_matches = list(_TEST_PASS_COUNT_RE.finditer(text))
    # 失败**计数**只在剔除逐条通过用例行后扫描:自建/TAP 测试台的**通过**行名里常含
    # "N failed"(如 `[PASS] account is locked after 5 failed logins`),朴素 `\d+\s+failed`
    # 会把它当成「5 个失败」→ (passed, 5) → 误报 TEST_COUNT_MISMATCH/失败,连累健康的全绿块。
    # 通过计数仍用原文(通过行本身不含权威通过汇总,汇总行不带 PASS 行首标记,不会被剔除)。
    fail_matches = list(_TEST_FAIL_COUNT_RE.finditer(_strip_passing_case_lines(text)))
    pass_match = pass_matches[-1] if pass_matches else None
    fail_match = fail_matches[-1] if fail_matches else None
    passed = int(pass_match.group(1).replace(",", "")) if pass_match else None
    failed = int(fail_match.group(1).replace(",", "")) if fail_match else None
    if passed is None:
        # 兜底非 "N passed" 框架：Maven / PHPUnit / unittest。让 report_run_passed 能
        # 对这些同样干净通过(闸门也判 PASS)的运行确认 passed>0，从而正常追加收尾验证句。
        php = _PHPUNIT_OK_RE.search(text)
        mvn = list(_MVN_TESTS_RUN_RE.finditer(text))
        ran = _UNITTEST_RAN_OK_RE.search(text)
        if php:
            passed = int(php.group(1).replace(",", ""))
            failed = failed if failed is not None else 0
        elif mvn:
            g = mvn[-1]
            run = int(g.group(1).replace(",", ""))
            fe = int(g.group(2)) + int(g.group(3))
            passed = run
            failed = fe if failed is None else failed
        elif ran:
            passed = int(ran.group(1).replace(",", ""))
            failed = failed if failed is not None else 0
        else:
            cp = list(_CUSTOM_PASSED_RE.finditer(text))
            if cp:
                passed = int(cp[-1].group(1).replace(",", ""))
                cf = list(_CUSTOM_FAILED_RE.finditer(text))
                failed = (int(cf[-1].group(1).replace(",", "")) if cf
                          else (failed if failed is not None else 0))
            else:
                # key=value 形: "SUMMARY: total=112, pass=112, fail=0"、"passed=161 failed=0"。
                kp = list(_KV_PASS_RE.finditer(text))
                if kp:
                    passed = int(kp[-1].group(1).replace(",", ""))
                    kf = list(_KV_FAIL_RE.finditer(text))
                    failed = (int(kf[-1].group(1).replace(",", "")) if kf
                              else (failed if failed is not None else 0))
    if passed is None:
        # rspec `5 examples, 0 failures` / ctest `0 tests failed out of 50` / mocha `2 passing`。
        # 这些框架的**成功**收尾无 "N passed",不补则完全成功被误判 failing → 误删已绿收尾(C1/C2/C3)。
        rs = list(_RSPEC_RE.finditer(text))
        ct = list(_CTEST_FAILED_OUT_RE.finditer(text))
        mo = list(_MOCHA_PASSING_RE.finditer(text))
        if rs:
            g = rs[-1]
            ex = int(g.group(1).replace(",", "")); fl = int(g.group(2).replace(",", ""))
            passed = ex - fl if ex >= fl else ex
            failed = fl if failed is None else failed
        elif ct:
            g = ct[-1]
            fl = int(g.group(1).replace(",", "")); total = int(g.group(2).replace(",", ""))
            passed = total - fl if total >= fl else 0
            failed = fl if failed is None else failed
        elif mo:
            passed = int(mo[-1].group(1).replace(",", ""))
            mf = list(_MOCHA_FAILING_RE.finditer(text))
            failed = (int(mf[-1].group(1).replace(",", "")) if mf
                      else (failed if failed is not None else 0))
    return (passed, failed)


def extract_report_final_summary(jsonl_path: Path) -> str:
    """取一份 report 原生 jsonl 里"最后一条 assistant 的 text 文本"(真收尾)。

    原生流式格式中 thinking/text/tool_use 各占一行且 type 均为 assistant,这里只收
    text 块,返回时间上最后出现的一段——即整轮跑测试的收尾总结。
    """
    last_text = ""
    if not jsonl_path.is_file():
        return ""
    with jsonl_path.open("r", encoding="utf-8") as handle:
        for raw_line in handle:
            raw_line = raw_line.strip()
            if not raw_line:
                continue
            try:
                obj = json.loads(raw_line)
            except json.JSONDecodeError:
                continue
            if obj.get("type") != "assistant":
                continue
            content = jsonl_message_content(obj)
            if not isinstance(content, list):
                continue
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    text = str(block.get("text", "")).strip()
                    if text:
                        last_text = text
    return last_text


def report_run_passed(event: ToolEvent, summary_text: str) -> bool:
    """一致性守卫:判定这次 report 运行是否"干净通过"。

    需同时满足:工具未报错、有 "N passed"(N>0) 证据、无失败计数、无强阻塞信号
    (pytest 的 FAILED/ERROR、Traceback、非零 exit code、cannot run 等)。
    宁可漏判也不误合并——不通过就不追加收尾。
    """
    if event.result_is_error:
        return False
    del summary_text
    haystack = event.result_content
    passed, failed = parse_test_counts(haystack)
    if not passed or passed <= 0:
        return False
    if failed and failed > 0:
        return False
    # 与闸门(evaluate_report_artifacts)保持一致：用 has_failure_output 只认**真正的
    # 框架/构建失败**(行首 FAILED / BUILD FAILURE / Traceback / Failures: N)，不再用
    # 裸 \bERROR\b —— 否则 pip 的良性告警 "ERROR: pip's dependency resolver ..." 会被误判
    # 成失败，导致闸门判 PASS、这里却拒绝追加收尾句，造成"插了通过测试、收尾却说没跑"。
    if has_failure_output(haystack):
        return False
    if re.search(
        r"(?:RUNNER_EXIT|EXIT_CODE|EXIT)\s*[=:]\s*-?[1-9]\d*|"
        r"exit code [1-9]|cannot run|unable to (?:install|run)|no tests ran|"
        r"Cannot connect to the Docker daemon|connection refused|No such container|"
        r"command not found|OOMKilled|out of memory",
        haystack,
        re.IGNORECASE,
    ):
        return False
    return True


_NO_TEST_RUN_CLAUSE = re.compile(
    r"(?:[,;]\s*(?:and|but|though|although)\s+)?"
    r"(?:i\s+)?"
    r"(?:"
    r"no\s+(?:automated\s+|unit\s+)?tests?\b[^.]*?\b(?:was|were)\s+run"
    r"|did\s*n(?:'|o)?t\s+(?:run|execute)\b[^.]*?\b(?:tests?|builds?)\b[^.]*"
    r"|(?:tests?|builds?)\b[^.]*?\b(?:was|were)\s+not\s+run"
    r"|no\s+(?:test|build)\b[^.]*?\b(?:was|were)\s+run"
    r")",
    re.IGNORECASE,
)


def _strip_no_test_disclaimer(text: str) -> str:
    """既然本轮已用真实通过的测试补上收尾，就删掉收尾话里"没跑测试/未运行测试/未跑构建"
    这类与之矛盾的旧免责声明——只删这类断言，**原样保留其它全部内容与空白/换行/markdown**。
    没有此类声明时**原样返回**(绝不重排/压平段落)。刻意保守：只匹配"(测试/构建)未被运行"，
    不误伤"没修改/没创建测试文件""没读源码"等。"""
    if not text or not _NO_TEST_RUN_CLAUSE.search(text):
        return text
    result = text
    # 从右往左删，保持前面各匹配的偏移有效；只动匹配处附近，绝不重排整段。
    for m in reversed(list(_NO_TEST_RUN_CLAUSE.finditer(result))):
        before, clause, after = result[:m.start()], m.group(0), result[m.end():]
        if re.match(r"^[,;]\s*(?:and|but|though|although)\s+", clause, re.I):
            # 句中的尾随子句(前面带 ", and/; but ..."):删掉子句，其后的句末标点仍在 after 里。
            result = before.rstrip() + after
        else:
            # 句首独立断言：删掉该句自身的句末标点+其后空白，避免留下孤立的 "." 。
            after = re.sub(r"^\s*[.!?。！？]\s*", "", after)
            before = before.rstrip()
            sep = " " if (before and after and not before.endswith("\n")) else ""
            result = before + sep + after
    # 只清理删除点可能残留的 " ." 与多余空格(不动换行)。
    result = re.sub(r"[ \t]+([.!?。！？])", r"\1", result)
    result = re.sub(r"[ \t]{2,}", " ", result)
    return result.strip()


def build_verification_sentence(event: ToolEvent, summary_text: str) -> str:
    """据真收尾/结果里的事实,拼一句英文精炼验证句(命令 + 通过/失败数),
    供追加到原 assistant 的 content 末尾。仅在 report_run_passed 为真时调用。
    """
    del summary_text
    command = (event.command or event.tool_name or "the test runner").strip()
    passed, failed = parse_test_counts(event.result_content)
    if passed and (failed in (None, 0)):
        outcome = f"all {passed} tests passed"
    elif passed is not None:
        outcome = f"{passed} passed, {failed} failed"
    else:
        outcome = "tests passed"
    return f"Verified by running `{command}`: {outcome}."


def _unify_terminal_test_counts(
    messages: list[dict[str, Any]],
    candidate_validation: Any,
) -> dict[str, Any]:
    """Rewrite claimed pass counts in the anchor/terminal to the real count.

    Only runs when the candidate gate failed with TEST_COUNT_MISMATCH alone:
    the freshly inserted evidence is a clean pass, so the trustworthy number
    is what the runner actually printed. Mid-session historical claims stay
    untouched — they were true at their own point in time; only the FINAL
    claim must agree with the FINAL evidence.
    """

    outcome: dict[str, Any] = {"applied": False, "rewrites": []}
    synthetic_blocks = [
        block
        for block in candidate_validation.blocks
        if stored_block_is_synthetic(block, messages)
    ]
    if not synthetic_blocks:
        outcome["skip_reason"] = "no synthetic evidence block"
        return outcome
    evidence = max(synthetic_blocks, key=lambda block: block.result_index)
    evidence_count = stored_last_runner_pass_count(evidence.result_text)
    if evidence_count is None:
        outcome["skip_reason"] = "evidence has no runner pass count"
        return outcome
    outcome["evidence_count"] = evidence_count
    target_indexes = {evidence.end_index}
    if messages:
        target_indexes.add(len(messages) - 1)

    def _rewrite(match: re.Match[str]) -> str:
        claimed = int(match.group(1).replace(",", ""))
        if claimed == evidence_count:
            return match.group(0)
        return match.group(0).replace(match.group(1), str(evidence_count), 1)

    for index in sorted(target_indexes):
        node = messages[index]
        if (
            not isinstance(node, dict)
            or node.get("role") != "assistant"
            or node.get("tool_calls")
            or not isinstance(node.get("content"), str)
        ):
            continue
        before = node["content"]
        after = STORED_PASS_CLAIM_RE.sub(_rewrite, before)
        if after != before:
            node["content"] = after
            outcome["rewrites"].append(
                {
                    "message_index": index,
                    "claims_before": STORED_PASS_CLAIM_RE.findall(before),
                    "claims_after": STORED_PASS_CLAIM_RE.findall(after),
                }
            )
    outcome["applied"] = bool(outcome["rewrites"])
    if not outcome["applied"]:
        outcome["skip_reason"] = "no rewritable claim found"
    return outcome


def synth_user_intro(event: ToolEvent) -> str:
    """Synthesize a short English user request for the inserted segment.

    The real command stays in the following tool call; prose never repeats host
    paths from the capture environment.
    """
    return (
        "Please run the discovered test runner to verify the previous changes "
        "and report pass/fail."
    )


def normalize_event_for_delivery(event: ToolEvent, *, task_root: Path) -> ToolEvent:
    """Return a path-safe copy while preserving the raw event for audit reports."""

    command = re.sub(
        r"^\s*cd\s+(?:\"[^\"]+\"|'[^']+'|[^\s;&|]+)\s*&&\s*",
        "",
        event.command,
        count=1,
        flags=re.IGNORECASE,
    ).strip()
    safe_command = str(
        redact_paths(command, known_roots={task_root: "<TASK_ROOT>"})
    )
    safe_input = {
        key: value for key, value in event.tool_input.items() if key != "cwd"
    }
    safe_input["command"] = safe_command
    safe_input = redact_paths(
        safe_input,
        known_roots={task_root: "<TASK_ROOT>"},
    )
    return replace(
        event,
        command=safe_command,
        tool_input=safe_input,
        description=str(
            redact_paths(
                event.description,
                known_roots={task_root: "<TASK_ROOT>"},
            )
        ),
        result_content=str(
            redact_paths(
                event.result_content,
                known_roots={task_root: "<TASK_ROOT>"},
            )
        ),
    )


def build_insert_nodes(
    *,
    event: ToolEvent,
    tool_call_id: str,
    assistant_intro: str,
    assistant_timestamp: str,
    tool_timestamp: str,
    user_intro: str = "",
    user_timestamp: str = "",
) -> list[dict[str, Any]]:
    """Build inserted nodes: optional user(intro) + assistant(tool_call) + tool.
    When user_intro is set, prepend a synthetic user node; otherwise 2 nodes."""
    assistant_node = {
        "role": "assistant",
        "agent": "main",
        "reasoning_content": "",
        "content": assistant_intro,
        "tool_calls": [
            {
                "id": tool_call_id,
                "type": "function",
                "function": {
                    "name": event.tool_name,
                    "arguments": json.dumps(event.tool_input, ensure_ascii=False),
                },
            }
        ],
        "_metadata": {
            "timestamp": assistant_timestamp,
            # 用发起该 tool_use 的真实 API 调用 usage,归一化成规范 tokens;
            # usage 缺失时 normalize_token_usage({}) 自然退化为零值占位。
            "tokens": normalize_token_usage(event.tool_use_usage),
        },
    }
    tool_node = {
        "role": "tool",
        "agent": "main",
        "tool_call_id": tool_call_id,
        "content": event.result_content,
        "_metadata": {
            "timestamp": tool_timestamp,
        },
    }
    nodes: list[dict[str, Any]] = []
    if user_intro:
        nodes.append(
            {
                "role": "user",
                "agent": "main",
                "content": user_intro,
                "_metadata": {
                    "timestamp": user_timestamp or assistant_timestamp,
                },
            }
        )
    nodes.append(assistant_node)
    nodes.append(tool_node)
    return nodes


def assemble_runtest_insert_nodes(
    *,
    selected: Sequence[ToolEvent],
    plan_intro: str,
    insert_times: Sequence[tuple[datetime, datetime]],
    existing_ids: set[str],
    predecessor_is_user: bool,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Assemble the full inserted node block for one anchor from an event chain.

    `selected` is the ordered chain [container-startup steps…, final test step].
    Emits: one synthetic user intro (first step only, unless the anchor's
    predecessor is already a user), then per step assistant(tool_call)+tool.
    Each assistant node uses that step's real narration (assistant_text); the
    first step falls back to plan_intro when the run captured no prose. Returns
    (insert_nodes, inserted_events) — the second is the per-step audit records.
    """
    insert_nodes: list[dict[str, Any]] = []
    inserted_events: list[dict[str, Any]] = []
    for pair_offset, event in enumerate(selected):
        tool_call_id = make_unique_tool_id(event, existing_ids)
        existing_ids.add(tool_call_id)
        assistant_time, tool_time = insert_times[pair_offset]
        # 金标:每个插入 assistant 用它在原生轨迹里的真实叙述;缺失时首节点回退到默认 intro。
        intro = event.assistant_text.strip() or (
            plan_intro if pair_offset == 0 else ""
        )
        user_intro = (
            synth_user_intro(event)
            if pair_offset == 0 and not predecessor_is_user
            else ""
        )
        user_time = assistant_time - timedelta(seconds=0.3)
        nodes = build_insert_nodes(
            event=event,
            tool_call_id=tool_call_id,
            assistant_intro=intro,
            assistant_timestamp=format_timestamp(assistant_time),
            tool_timestamp=format_timestamp(tool_time),
            user_intro=user_intro,
            user_timestamp=format_timestamp(user_time),
        )
        insert_nodes.extend(nodes)
        inserted_events.append(
            {
                "event_index": event.event_index,
                "tool_call_id": tool_call_id,
                "tool_name": event.tool_name,
                "command": event.command,
                "source_jsonl": event.source_jsonl,
                "source_line_tool_use": event.source_line_tool_use,
                "source_line_tool_result": event.source_line_tool_result,
            }
        )
    return insert_nodes, inserted_events


def addtool_build_report(
    *, scan_root: Path, task_root: Path, llm_enabled: bool, model: str = ""
) -> dict[str, Any]:
    return {
        "report_type": "add_run_test_tool",
        "schema_version": SCHEMA_VERSION,
        "gate_version": GATE_VERSION,
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "script": "add_run_test_tool.py",
        "scan_root": str(scan_root),
        "task_root": str(task_root),
        "mode": "write",
        "llm_enabled": llm_enabled,
        # 补测规划(planner)实际使用的大模型名，供 .chainlog / re-runtest.json 直读。
        "model": model if llm_enabled else "deterministic",
        "max_tool_pairs": MAX_TOOL_PAIRS,
        "files": [],
        "summary": {
            "files_seen": 0,
            "files_modified": 0,
            "messages_considered": 0,
            "messages_inserted_before": 0,
            "tool_events_inserted": 0,
            "skipped": 0,
            "errors": 0,
            "gate_failures": 0,
            "file_failures": 0,
        },
    }


def make_report_path(task_root: Path, timestamp: str) -> Path:
    return task_root / "report" / f"add_run_test_tool_{task_root.name}_{timestamp}.json"


def build_rerun_report(
    task_root: Path, session_files: list[Path], report: dict[str, Any]
) -> dict[str, Any]:
    """按 structure.json 的字段布局，汇总本 TASK 每条会话的**补测插入**为 re-runtest.json。

    只记录真正发生了插入的会话(命中轨迹)：每处插入 action_type=insert、before_content 留空、
    after_content 写插入的节点内容，line 取插入块在最终 json 文件中的起始行号。"""
    insertions = report.get("insertions") or []
    by_session: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for ins in insertions:
        stem = Path(ins.get("session_file") or ins.get("session") or "").stem
        by_session[stem].append(ins)

    sessions_out: list[dict[str, Any]] = []
    for session_id in sorted(by_session):
        subs: list[dict[str, Any]] = []
        # 同一会话内多处插入按落点行号从小到大排列，便于阅读。
        for ins in sorted(
            by_session[session_id],
            key=lambda i: (i.get("line_range") or [i.get("insert_at_message_index", 0)])[0],
        ):
            nodes = ins.get("nodes") or []
            after_content = json.dumps(nodes, ensure_ascii=False, indent=2)
            line_range = ins.get("line_range") or []
            line = line_range[0] if line_range else ins.get("insert_at_message_index")
            subs.append(
                {
                    "function": "重跑测试",
                    "action_type": "insert",
                    "before_content": "",
                    "after_content": after_content,
                    "problem": "补充测试节点",
                    "line": line,
                    "addition": "",
                }
            )
        sessions_out.append({"session_id": session_id, "sub": subs})

    return {
        "report_type": "re_runtest_report",
        "task_id": task_root.name,
        "task_path": str(task_root),
        "create": datetime.now().strftime("%Y-%m-%dT%H:%M:%S"),
        "summary": {
            "total_trajectory_count": len(session_files),
            "hit_trajectory_count": len(by_session),
            "total_issues": len(insertions),
        },
        "sessions": sessions_out,
    }


def _message_line_range(
    text: str, data: dict[str, Any], key: str, msg_index: int, count: int
) -> tuple[int, int]:
    """算插入的 count 个消息在最终 json 文本(indent=2)中的 1-based 行号区间[含]。"""
    lines = text.split("\n")
    target_line = f'  "{key}": ['
    start_arr = None
    for i, ln in enumerate(lines):
        if ln == target_line:
            start_arr = i
            break
    messages = data.get(key) or []
    if start_arr is None or not messages:
        return (-1, -1)
    cur = start_arr + 1  # 第一个数组元素的首行(0-based)
    first = last = None
    for j, message in enumerate(messages):
        nlines = json.dumps(message, ensure_ascii=False, indent=2).count("\n") + 1
        if j == msg_index:
            first = cur
        if j == msg_index + count - 1:
            last = cur + nlines - 1
        cur += nlines
    if first is None or last is None:
        return (-1, -1)
    return (first + 1, last + 1)


def _line_range_contains(text: str, lo: int, hi: int, needle: str) -> bool:
    """写盘后自校验:声称的行号区间必须真的包含插入块的 tool_call_id。"""

    if not needle or lo < 1 or hi < lo:
        return False
    lines = text.split("\n")
    if hi > len(lines):
        return False
    return needle in "\n".join(lines[lo - 1 : hi])


def _coerce_int_token(value: Any) -> int:
    """把 token 数值宽松转成 int(兼容字符串/浮点/None),失败一律 0。"""
    if isinstance(value, bool):
        return 0
    if isinstance(value, int):
        return value
    if isinstance(value, float):
        return int(value)
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return 0
        try:
            return int(text)
        except ValueError:
            try:
                return int(float(text))
            except ValueError:
                return 0
    return 0


def _native_reasoning_tokens(tokens: dict[str, Any]) -> int:
    details = tokens.get("output_tokens_details")
    if isinstance(details, dict):
        return _coerce_int_token(details.get("reasoning_tokens", 0))
    return _coerce_int_token(tokens.get("reasoning_tokens", 0))


def normalize_token_usage(tokens: dict[str, Any]) -> dict[str, Any]:
    """把一段原生 usage 映射成规范的 {input, output, reasoning, cache} 结构。

    原生多余字段(server_tool_use/service_tier/inference_geo/iterations/speed/
    cache_creation ...)一律丢弃。
    """
    return {
        "input": _coerce_int_token(tokens.get("input_tokens", 0)),
        "output": _coerce_int_token(tokens.get("output_tokens", 0)),
        "reasoning": _native_reasoning_tokens(tokens),
        "cache": {
            "read": _coerce_int_token(tokens.get("cache_read_input_tokens", 0)),
            "write": _coerce_int_token(tokens.get("cache_creation_input_tokens", 0)),
        },
    }


def process_session_file(
    path: Path,
    *,
    report_root_override: Path | None,
    config: RuntimeConfig | None,
    report: dict[str, Any],
    dry_run: bool = False,
    emit: Callable[[str], None] = print,
    failed_step1_sessions: set[tuple[str, str]] | None = None,
) -> None:
    report["summary"]["files_seen"] += 1
    file_report: dict[str, Any] = {
        "path": str(path),
        "status": "processing",
        "targets": [],
        "write_performed": False,
    }
    report["files"].append(file_report)

    if failed_step1_sessions and _session_task_key(path) in failed_step1_sessions:
        detail = _step1_details_by_session(
            _step1_summary_path_for_root(
                Path(str(report.get("scan_root") or find_task_root(path)))
            )
        ).get(_session_task_key(path), {})
        report["summary"]["skipped"] += 1
        file_report["status"] = "skipped_runtest_failed_unchanged"
        file_report["verdict"] = str(detail.get("verdict") or "")
        file_report["reason_codes"] = [
            str(reason) for reason in detail.get("reason_codes") or []
        ]
        file_report["source_preserved"] = True
        emit("  · 跳过:重跑测试持续失败，源 session 原样保留")
        return

    try:
        data = json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception as exc:
        report["summary"]["errors"] += 1
        file_report["status"] = "error_read_json"
        file_report["error"] = str(exc)
        return

    if not isinstance(data, dict):
        report["summary"]["skipped"] += 1
        report["summary"]["file_failures"] += 1
        file_report["status"] = "skipped_root_not_object"
        return

    messages = find_message_list(data)
    if messages is None:
        report["summary"]["skipped"] += 1
        report["summary"]["file_failures"] += 1
        file_report["status"] = "skipped_no_messages"
        return

    # 幂等保护(2026-07-14):session 已带一块能过 scoped 契约的合成证据时,
    # 本轮直接视为成功跳过——不再二次插入,也不算失败;否则整链重跑会把
    # 上一轮已修好的 session 又计入失败分流。仍执行路径脱敏兜底,与
    # existing_state=="valid" 分支的行为保持一致。
    prior_validation = validate_stored_session(messages)
    if prior_validation.verdict is StoredSessionVerdict.PASS and any(
        stored_block_is_synthetic(block, messages)
        for block in prior_validation.blocks
    ):
        file_report["candidate_verdict"] = prior_validation.verdict.value
        file_report["would_step3_pass"] = True
        early_task_root = find_task_root(path)
        redacted_data = redact_paths(
            data, known_roots={early_task_root: "<TASK_ROOT>"}
        )
        if isinstance(redacted_data, dict) and redacted_data != data:
            redacted_messages = find_message_list(redacted_data)
            validation_reasons = (
                validate_delivery_messages(redacted_messages)
                if redacted_messages is not None
                else ["MISSING_REDACTED_MESSAGES"]
            )
            if validation_reasons:
                report["summary"]["errors"] += 1
                file_report["status"] = "error_post_insert_validation"
                file_report["reason_codes"] = list(validation_reasons)
                return
            file_report["existing_paths_redacted"] = True
            if dry_run:
                file_report["status"] = "dry_run_planned"
            else:
                atomic_write_text(
                    path,
                    json.dumps(redacted_data, ensure_ascii=False, indent=2) + "\n",
                )
                report["summary"]["files_modified"] += 1
                file_report["status"] = "modified"
            return
        report["summary"]["skipped"] += 1
        file_report["status"] = "skipped_existing_valid_insert"
        emit("  · 跳过:已存在合格的合成测试证据(幂等,视为成功)")
        return

    task_root = find_task_root(path)
    report_root = report_root_override or (task_root / "report")
    if not messages:
        report["summary"]["skipped"] += 1
        report["summary"]["file_failures"] += 1
        file_report["status"] = "skipped_no_messages"
        emit("  · 跳过:session 没有任何消息节点")
        return
    last_index = len(messages) - 1

    gates = evaluate_session_report_gates(path, report_root=report_root)
    file_report["gate_scopes"] = [
        {
            "scope_node_index": scope,
            "verdict": g.verdict,
            "run_id": g.run_id,
            "run_dir": str(g.run_dir) if g.run_dir else None,
        }
        for scope, g in gates
    ]
    # Legacy single-gate fields keep pointing at the terminal run for
    # backward-compatible reporting/summaries.
    _terminal_gate = next((g for scope, g in gates if scope is None), None)
    if _terminal_gate is not None:
        file_report["verdict"] = _terminal_gate.verdict
        file_report["reason_codes"] = list(_terminal_gate.reason_codes)
        file_report["selected_run_id"] = _terminal_gate.run_id
        file_report["selected_run_dir"] = (
            str(_terminal_gate.run_dir) if _terminal_gate.run_dir else None
        )

    # 收尾失败测试:删+重补(需求2)。仅当**确实会插入一个通过的终态测试**时才动轨迹——即
    # 终态(scope=None)gate 判 PASS 且能取出被选中的 event。否则(终态 gate 非 PASS、无可插入证据)
    # 绝不删尾/追加总结,以免留下「删了失败测试却没补上、还挂一句假的已运行确认」的坏收尾。
    # 判据:manifest.needs_final_test is True + **当前 messages** 最近一次真跑失败(实时重算,manifest
    # 里的 terminal_failing_range 只作审计)。删除受配对安全约束,且只删「严格高于所有中间 scope 下标」
    # 的区间(避免删尾后中间锚点下标漂移);混合轮/会漂移的区间跳过不删。
    _term_gate_pass = (
        _terminal_gate is not None
        and _terminal_gate.verdict == Verdict.PASS.value
        and extract_gate_selected_event(_terminal_gate) is not None
    )
    _term_manifest = (_terminal_gate.manifest or {}) if _terminal_gate else {}
    _term_detection = _term_manifest.get("test_claim_detection") or {}
    # 终态尾部是否被本次改动(删失败簇 / 追加合成总结)。若最终终态测试未插入,则这些改动不得写盘
    # (否则留下「删了失败测试 + 假总结称已跑 + 无补测」的坏收尾)。见循环后 TERMINAL_DELETE_WITHOUT_INSERT 门。
    _terminal_delete_performed = False
    if _term_gate_pass and _term_detection.get("needs_final_test") is True:
        # 所有中间 scope 的下标(删尾不得触及它们之下,否则中间锚点漂移)。删除区间必须严格高于
        # **最高**的中间 scope(用 max 而非 min):否则介于 min 与 max 之间的删除会移动更高的中间锚点。
        _middle_scopes = [s for s, _g in gates if s is not None]
        _max_middle = max(_middle_scopes) if _middle_scopes else None
        _tstate = terminal_test_state(messages)
        if _tstate.state == TERMINAL_FAILING and _tstate.failing_ranges:
            _cand = _safe_deletable_ranges(messages, list(_tstate.failing_ranges))
            # 只保留严格高于所有中间 scope 的区间(lo > 最高中间 scope 下标)。
            if _max_middle is not None:
                _dropped = [r for r in _cand if r[0] <= _max_middle]
                _safe = [r for r in _cand if r[0] > _max_middle]
                if _dropped:
                    file_report["terminal_failing_delete_skipped_scope_guard"] = [
                        list(r) for r in _dropped
                    ]
            else:
                _safe = _cand
            if _safe:
                for _lo, _hi in sorted(_safe, reverse=True):
                    del messages[_lo:_hi + 1]
                last_index = len(messages) - 1
                _terminal_delete_performed = True
                file_report["terminal_failing_deleted"] = [list(r) for r in _safe]
                emit(
                    "  · 收尾失败测试:删掉整串收尾连续失败/未验证运行区间 "
                    f"{[list(r) for r in _safe]},将补一个干净通过的收尾测试"
                )
            else:
                file_report["terminal_failing_delete_skipped"] = [
                    list(r) for r in _tstate.failing_ranges
                ]
                emit(
                    "  · 收尾失败测试存在但区间非配对安全/会漂移中间锚点,跳过删除、仅追加补测"
                )
        # 保证轨迹**以一个纯文本收尾总结 assistant 结尾**。终态补测块的「收尾总结」就是它前面
        # 那个锚点节点(add_run_test_tool 不自造 closing assistant),而 inspect_existing_insert
        # 判「valid」也要求插入块后紧跟一个无工具调用的纯文本 assistant。删完失败测试后(或本就
        # 停在 tool/Edit 上的坏收尾),末尾若不是这样的总结节点,就追加一个合成收尾总结,让终态
        # 插入有合法锚点、且二次运行能识别既有插入(幂等)。仅在**确会插入终态测试**时做(见上
        # _term_gate_pass 门),避免删了没补/挂假总结。
        if not _tail_is_plain_summary(messages):
            messages.append(_make_synthetic_closing_summary(messages))
            last_index = len(messages) - 1
            _terminal_delete_performed = True
            file_report["appended_synthetic_closing_summary"] = True
            emit("  · 收尾无纯文本总结节点,追加一个合成收尾总结作为终态插入锚点")

    # Keep source cwd only in the redacted audit report; delivery nodes use the
    # separately normalized event copy per plan below.
    session_cwd = ""
    _meta = data.get("meta")
    if isinstance(_meta, dict) and isinstance(_meta.get("cwd"), str):
        session_cwd = _meta["cwd"].strip()
    file_report["session_cwd"] = session_cwd

    # Build one insertion plan per PASS scope (Req4). Terminal (scope None)
    # inserts before the last node ONLY when the LLM judged needs_final_test True
    # — the requirement makes the LLM the sole arbiter of "does this session need
    # a补测". Each intermediate scope inserts a node-scoped (repo@N) result before
    # its own node N. A scoped run we requested but that did not cleanly pass is a
    # real failure (fail-closed: never insert an errored run; route to failed).
    plans: list[dict[str, Any]] = []
    redact_only = False
    scope_failure = False
    for scope, gate in gates:
        if gate.verdict != Verdict.PASS.value:
            if scope is not None:
                scope_failure = True
            continue
        selected_event = extract_gate_selected_event(gate)
        if selected_event is None:
            if scope is not None:
                scope_failure = True
            continue
        # 金标补测:提取「docker 启动步链 → 测试步」完整链,而非只取测试步。planner
        # 仍只判定是否插入/选哪个测试步(见下方 available_events);启动步链作为确定性
        # 单元在插入时随该测试步一起展开。
        chain_events = extract_gate_process_events(gate)
        if not chain_events:
            if scope is not None:
                scope_failure = True
            continue
        delivery_chain = [
            normalize_event_for_delivery(event, task_root=task_root)
            for event in chain_events
        ]
        # 末元素=verdict 选中的测试步;其前是通向它的真实容器启动步。
        delivery_event = delivery_chain[-1]
        existing_state = inspect_existing_insert(messages, delivery_event)
        if existing_state == "incomplete":
            report["summary"]["errors"] += 1
            file_report["status"] = "error_existing_block_incomplete"
            return
        if existing_state == "valid":
            redact_only = True
            continue
        if scope is None:
            manifest = gate.manifest or {}
            detection = manifest.get("test_claim_detection") or {}
            if detection.get("needs_final_test") is not True:
                # LLM says the session already ran a real final test -> no补测.
                continue
            # 结构性闸门不拦终态补测(需求):末节点若不是 assistant(轨迹结构坏了/删失败测试后
            # 收尾停在 tool/user),往上回找最近的 assistant 作锚点,而非放弃插入。锚点仍在其之前插。
            anchor = last_index
            while anchor >= 0 and not (
                isinstance(messages[anchor], dict)
                and messages[anchor].get("role") == "assistant"
            ):
                anchor -= 1
            if anchor < 0:
                continue
            selection = (
                "before-last-node" if anchor == last_index
                else "before-last-assistant"
            )
            anchor_node = messages[anchor]
        else:
            anchor = scope
            selection = f"before-node-{scope}"
            if not (0 <= anchor < len(messages)):
                scope_failure = True
                continue
            anchor_node = messages[anchor]
            if not (
                isinstance(anchor_node, dict)
                and anchor_node.get("role") == "assistant"
            ):
                scope_failure = True
                continue
        plans.append(
            {
                "anchor": anchor,
                "event": delivery_event,
                "events": delivery_chain,
                "selection": selection,
                "scope": scope,
                "run_dir": gate.run_dir,
            }
        )

    if scope_failure:
        file_report["scope_failure"] = True

    if not plans:
        if redact_only:
            redacted_data = redact_paths(data, known_roots={task_root: "<TASK_ROOT>"})
            redacted_messages = (
                find_message_list(redacted_data)
                if isinstance(redacted_data, dict)
                else None
            )
            if redacted_messages is None:
                report["summary"]["errors"] += 1
                file_report["status"] = "error_post_insert_validation"
                file_report["reason_codes"] = ["MISSING_REDACTED_MESSAGES"]
                return
            # 精简（需求）：幂等 redact-only 路径不再跑交付校验闸门（已有合法插入，仅重做脱敏）。
            if redacted_data == data:
                file_report["status"] = "unchanged"
                return
            file_report["existing_paths_redacted"] = True
            if dry_run:
                file_report["status"] = "dry_run_planned"
            else:
                atomic_write_text(
                    path,
                    json.dumps(redacted_data, ensure_ascii=False, indent=2) + "\n",
                )
                report["summary"]["files_modified"] += 1
                file_report["status"] = "modified"
            return
        if scope_failure:
            report["summary"]["skipped"] += 1
            report["summary"]["gate_failures"] += 1
            report["summary"]["file_failures"] += 1
            file_report["status"] = "skipped_gate_non_pass"
            return
        report["summary"]["skipped"] += 1
        file_report["status"] = "skipped_no_test_needed"
        # 会话被正确放行(收尾已有完全成功的测试→无需补测)。清掉早前从「报告门评估旧遗留 run 目录
        # (无 manifest)」残留的 verdict=NO_RELIABLE_TEST_EVIDENCE,改标 NO_TEST_NEEDED,避免下游失败
        # 分流把这个已含真实通过测试的 passing 会话误判为失败(与 collect_failure_records 的放行互为兜底)。
        file_report["verdict"] = NO_TEST_NEEDED_VERDICT
        file_report["reason_codes"] = []
        emit("  · 跳过:LLM 判定无需补测(needs_final_test=false)")
        return

    file_report["report_dirs"] = [
        str(p["run_dir"]) for p in plans if p["run_dir"] is not None
    ]
    file_report["candidate_event_count"] = len(plans)
    file_report["candidate_events"] = [asdict(p["event"]) for p in plans]
    file_report["candidate_chain_lengths"] = [len(p["events"]) for p in plans]
    emit(f"  · 计划插入 {len(plans)} 处(terminal 收尾补测,需 needs_final_test):")
    for p in plans:
        ev = p["event"]
        flag = "FAIL" if ev.result_is_error else "PASS"
        startup_n = max(len(p["events"]) - 1, 0)
        emit(
            f"      scope={p['selection']} anchor={p['anchor']} {flag} "
            f"启动步×{startup_n}+测试 {ev.command[:50]!r}"
        )

    inserted_total = 0
    declined_any = False
    _terminal_inserted = False
    existing_ids = collect_existing_tool_ids(messages)

    # Insert from high to low anchor so earlier insertions do not shift later
    # (lower-index) anchors. Each plan carries its own scope-specific event.
    for scope_plan in sorted(plans, key=lambda p: p["anchor"], reverse=True):
        target_index = scope_plan["anchor"]
        events = [scope_plan["event"]]
        target_selection = scope_plan["selection"]
        is_terminal_plan = scope_plan["scope"] is None
        report["summary"]["messages_considered"] += 1
        target = messages[target_index]
        target_content = normalize_text(target.get("content")).strip()
        target_report: dict[str, Any] = {
            "target_message_index": target_index,
            "target_selection": target_selection,
            "scope_node_index": scope_plan["scope"],
            "target_content_excerpt": target_content[:1200],
            "status": "processing",
        }
        file_report["targets"].append(target_report)

        available_events = [
            event
            for event in events
            if not has_existing_insert(messages, event)
        ]
        target_report["available_event_count"] = len(available_events)
        if not available_events:
            report["summary"]["skipped"] += 1
            target_report["status"] = "skipped_no_available_tool_event"
            continue

        raw_plan: dict[str, Any]
        if is_terminal_plan:
            # 口径:一旦判定需要补测(倒数第二个节点没测试 / 有失败测试删掉后),末节点前的**完整测试
            # 节点对必须插入**——不存在「planner 判断该不该插」的空间。终态一律走确定性计划(should_insert
            # 恒 True、选定已判 PASS 的测试事件),**不咨询 LLM planner 的拒插决策**(移除 skipped_plan_declined
            # 这类与口径不符的逻辑)。是否需要补测由检测层(needs_final_test/terminal_test_state)唯一决定。
            raw_plan = deterministic_plan(available_events)
            target_report["deterministic_plan_used"] = True
            target_report["forced_terminal_insert"] = True
        elif config and config.api_key:
            user_prompt = make_planner_prompt(
                session_path=path,
                target_index=target_index,
                target_content=target_content,
                events=available_events,
            )
            target_report["llm_prompt"] = user_prompt
            try:
                raw_plan = call_llm_plan(
                    config=config,
                    user_prompt=user_prompt,
                    timeout=LLM_TIMEOUT_SECONDS,
                )
                target_report["llm_raw_plan"] = raw_plan
            except Exception as exc:
                report["summary"]["errors"] += 1
                target_report["llm_error"] = str(exc)
                raw_plan = deterministic_plan(available_events)
                target_report["fallback_plan_used"] = True
        else:
            raw_plan = deterministic_plan(available_events)
            target_report["deterministic_plan_used"] = True

        plan = validate_plan(raw_plan, available_events, MAX_TOOL_PAIRS)
        target_report["plan"] = plan
        if not plan["should_insert"]:
            # 终态计划走 deterministic_plan,available_events 非空时 should_insert 恒 True,正常到不了这里;
            # 万一到了(空事件),按「无可插事件」处理,绝不当作「拒插」跳过——终态必插是硬口径。
            if is_terminal_plan:
                report["summary"]["skipped"] += 1
                target_report["status"] = "skipped_no_available_tool_event"
                continue
            # 仅**中间(node-scoped)**插入保留 planner 拒插为正当跳过(2026-07-14 产品决策):
            # 中间命中的补测由 planner 判断该锚点是否适合插;拒插不算失败、不置红整链。终态**不适用**。
            report["summary"]["skipped"] += 1
            target_report["status"] = "skipped_plan_declined"
            target_report["plan_decline_reason"] = plan.get("reason", "")
            declined_any = True
            emit(
                "  · 正当跳过(仅中间 node-scoped):planner 判定不该插 —— "
                f"{str(plan.get('reason', ''))[:200]}"
            )
            continue

        selected = [
            event for event in available_events if event.event_index in plan["selected_event_indices"]
        ]
        # 金标补测:planner 只决定「是否插入 / 选哪个测试步」;真正插入的是通向该测试步的
        # 完整容器启动过程 + 测试步。用计划携带的确定性链替换 selected,链尾即所选测试步。
        chain = scope_plan.get("events")
        if selected and chain:
            selected = list(chain)
            if len(selected) > MAX_INSERT_CHAIN_STEPS:
                # 防御性上限:保留链尾(测试步 + 最近的启动步),丢弃最早的启动步。
                selected = selected[-MAX_INSERT_CHAIN_STEPS:]
        # 按真实先后(source_line_tool_use)排序,保证内容与时间戳顺序一致(多步兼容)。
        selected.sort(key=lambda event: event.source_line_tool_use)
        prev_time = None
        if target_index > 0 and isinstance(messages[target_index - 1], dict):
            prev_meta = messages[target_index - 1].get("_metadata")
            if isinstance(prev_meta, dict):
                prev_time = parse_timestamp(prev_meta.get("timestamp"))
        target_time = parse_timestamp((target.get("_metadata") or {}).get("timestamp"))
        # 锚点=末节点模型:从 prev 往后按真实时长铺插入节点;末节点若离得不够远,
        # 就把它的 timestamp 向后顺移到最后 tool+0.5s(末节点无后继,顺移不撞)。
        insert_times, suggested_target_time = _forward_insert_times(selected, prev_time)
        target_time_shift = None
        if target_time is None or _to_aware(target_time) < suggested_target_time:
            meta = target.get("_metadata")
            if not isinstance(meta, dict):
                meta = {}
                target["_metadata"] = meta
            new_ts = format_timestamp(suggested_target_time)
            target_time_shift = {"from": meta.get("timestamp"), "to": new_ts}
            meta["timestamp"] = new_ts
        predecessor_is_user = (
            target_index > 0
            and isinstance(messages[target_index - 1], dict)
            and messages[target_index - 1].get("role") == "user"
        )
        # 每个 assistant 用其真实叙述;首步补一条合成 user intro(见 assemble_runtest_insert_nodes)。
        insert_nodes, inserted_events = assemble_runtest_insert_nodes(
            selected=selected,
            plan_intro=plan["assistant_intro"],
            insert_times=insert_times,
            existing_ids=existing_ids,
            predecessor_is_user=predecessor_is_user,
        )

        messages[target_index:target_index] = insert_nodes
        # 真收尾合并:从 report 抽最后一条 assistant 文本,过一致性守卫后,只把一句
        # 精炼验证事实追加进原 target assistant 的 content(不改其它字段/节点)。
        appended_summary: str | None = None
        summary_merge: dict[str, Any] = {"attempted": False, "merged": False}
        if selected and isinstance(target, dict) and target.get("role") == "assistant":
            summary_merge["attempted"] = True
            src_event = selected[-1]
            summary_text = extract_report_final_summary(Path(src_event.source_jsonl))
            passed_ok = report_run_passed(src_event, summary_text)
            summary_merge["report_passed"] = passed_ok
            base_content = target.get("content")
            if not passed_ok:
                summary_merge["skip_reason"] = "report run is not a clean pass"
            elif not isinstance(base_content, str):
                summary_merge["skip_reason"] = "target content is not a plain string"
            else:
                sentence = build_verification_sentence(src_event, summary_text)
                if sentence in base_content:
                    summary_merge["skip_reason"] = "sentence already present"
                else:
                    # 先删掉与"已补上的通过测试"矛盾的旧免责声明("没跑测试/未运行构建")，
                    # 再追加验证句——否则末节点会同时出现"没跑测试"和"已验证N通过"两句自相矛盾。
                    stripped = _strip_no_test_disclaimer(base_content)
                    if stripped != base_content:
                        summary_merge["stripped_no_test_disclaimer"] = True
                    target["content"] = (
                        stripped.rstrip() + "\n\n" + sentence
                        if stripped.strip()
                        else sentence
                    )
                    appended_summary = sentence
                    summary_merge["merged"] = True
                    summary_merge["appended_sentence"] = sentence
        else:
            summary_merge["skip_reason"] = "target is not an assistant node"

        inserted_total += len(selected)
        if scope_plan["scope"] is None:
            _terminal_inserted = True
        report["summary"]["messages_inserted_before"] += 1
        report["summary"]["tool_events_inserted"] += len(selected)
        target_report["status"] = "inserted"
        target_report["inserted_events"] = inserted_events
        target_report["inserted_node_count"] = len(insert_nodes)
        target_report["summary_merge"] = summary_merge
        report.setdefault("insertions", []).append(
            {
                "session": str(path),
                "session_file": path.name,
                "task": task_root.name,
                "target_selection": target_selection,
                "insert_at_message_index": target_index,
                # 插入后的精确落点:新节点占据的消息下标区间 + 顺延后的收尾下标。
                "inserted_message_indexes": list(
                    range(target_index, target_index + len(insert_nodes))
                ),
                "anchor_message_index_after_insert": target_index + len(insert_nodes),
                "inserted_roles": [node.get("role") for node in insert_nodes],
                "tool_call_id": (
                    inserted_events[0]["tool_call_id"] if inserted_events else ""
                ),
                "plan_reason": plan.get("reason", ""),
                "nodes": insert_nodes,
                "appended_summary": appended_summary,
                "target_time_shift": target_time_shift,
                "session_cwd": session_cwd,
            }
        )

    if inserted_total == 0:
        if declined_any:
            file_report["status"] = "skipped_plan_declined"
            file_report["reason_codes"] = ["PLANNER_DECLINED"]
        else:
            file_report["status"] = "unchanged"
        return

    # 终态「删除/追加合成总结」与终态「插入」必须同生共死:若尾部已被本次改动(删失败簇或挂合成
    # 总结)、但终态测试最终未插入(planner 拒插、无可用事件等),继续写盘会持久化「删了失败测试 +
    # 假总结称已跑测试 + 无终态补测」的坏收尾。此时放弃写入本文件(磁盘保持原样,留待下次重试),
    # 即便有中间插入也不写——绝不以「牺牲终态正确性」换一个中间补测。
    if _terminal_delete_performed and not _terminal_inserted:
        report["summary"]["skipped"] += 1
        file_report["status"] = "skipped_terminal_delete_without_insert"
        file_report["reason_codes"] = ["TERMINAL_DELETE_WITHOUT_INSERT"]
        emit(
            "  · 保护:终态失败簇已删/已挂合成总结但终态测试未插入,放弃写入以免留下坏收尾(磁盘不变)"
        )
        return

    redacted_data = redact_paths(data, known_roots={task_root: "<TASK_ROOT>"})
    if not isinstance(redacted_data, dict):
        report["summary"]["errors"] += 1
        file_report["status"] = "error_post_insert_validation"
        file_report["reason_codes"] = ["INVALID_REDACTED_SESSION"]
        return
    if redacted_data != data:
        file_report["existing_paths_redacted"] = True
    data = redacted_data
    redacted_messages = find_message_list(data)
    if redacted_messages is None:
        report["summary"]["errors"] += 1
        file_report["status"] = "error_post_insert_validation"
        file_report["reason_codes"] = ["MISSING_REDACTED_MESSAGES"]
        return
    messages = redacted_messages

    # 精简（需求）：插入过程与其后不再跑「交付校验闸门 / 候选闸门」等会频繁误报失败的复检步骤。
    # 是否插入成功的唯一判据已在插入前由 report gate（evaluate_report_artifacts）按
    # 「runner exit==0 且无失败测试」判定；PASS 才会走到这里并取出被选中的干净通过事件插入。
    # 因此这里直接输出修复后的轨迹，不再二次校验拦截。
    final_text = json.dumps(data, ensure_ascii=False, indent=2)
    if dry_run:
        file_report["status"] = "dry_run_planned"
    else:
        atomic_write_text(path, final_text + "\n")
        report["summary"]["files_modified"] += 1
        file_report["status"] = "modified"
        file_report["write_performed"] = True
    # 需求2:写盘后计算插入节点在最终 json 文件中的 1-based 行号区间
    arr_key = next(
        (
            k
            for k in ("messages", "chat_messages", "conversation", "history")
            if isinstance(data.get(k), list) and data.get(k) is messages
        ),
        "messages",
    )
    # 多处插入的下标漂移对账(2026-07-17):插入按 anchor 从高到低应用,每次低 anchor 插入都会把
    # **更高** anchor 已插入块整体下移。`insert_at_message_index` 记的是各自插入时的原始下标,漂移后
    # 对不上最终文件——若直接用它算行号,除最低 anchor 外都会指到错块,导致自校验(区间须含本块
    # tool_call_id)误报失败。这里按「同文件中所有原始下标严格更小的插入的节点数之和」把每个块的
    # 下标推到最终位置,再算行号/落点,让行号与自校验都对上真实位置。
    _same_path_inserts = [
        ins
        for ins in report.get("insertions", [])
        if ins.get("session") == str(path)
    ]
    for insertion in _same_path_inserts:
        if "line_range" in insertion:
            continue
        orig_index = insertion["insert_at_message_index"]
        shift = sum(
            len(other["nodes"])
            for other in _same_path_inserts
            if other is not insertion
            and other["insert_at_message_index"] < orig_index
        )
        final_index = orig_index + shift
        node_count = len(insertion["nodes"])
        # 对账后的真实落点(供审计/看板显示);原始 insert_at_message_index 保留不动作为溯源。
        insertion["inserted_message_indexes"] = list(
            range(final_index, final_index + node_count)
        )
        insertion["anchor_message_index_after_insert"] = final_index + node_count
        lo, hi = _message_line_range(
            final_text,
            data,
            arr_key,
            final_index,
            node_count,
        )
        insertion["line_range"] = [lo, hi]
        verified = _line_range_contains(
            final_text, lo, hi, insertion.get("tool_call_id", "")
        )
        insertion["line_range_verified"] = verified
        indexes = insertion.get("inserted_message_indexes") or []
        span = (
            f"消息#{indexes[0]}-#{indexes[-1]}"
            if len(indexes) > 1
            else f"消息#{indexes[0]}"
            if indexes
            else "?"
        )
        emit(
            "  · 已插入并写盘:\n"
            f"      文件: {path}\n"
            f"      位置: 原收尾 assistant(消息#{final_index})之前,"
            f"新增 {node_count} 个节点({'+'.join(insertion.get('inserted_roles') or [])})"
            f" → 现占 {span},收尾顺延为 消息#{insertion.get('anchor_message_index_after_insert','?')}\n"
            f"      行号: L{lo}-L{hi}"
            + (
                " (已自校验:区间内含插入块的 tool_call_id)"
                if verified
                else " (⚠ 自校验失败,请用下面的 grep 定位)"
            )
            + "\n"
            f"      定位: grep -n \"{insertion.get('tool_call_id','')}\" 该文件可直达"
        )


def addtool_build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Insert assistant(tool_calls)+tool nodes from TASK report JSONL "
            "test-run trajectories before source assistant verification claims."
        )
    )
    parser.add_argument(
        "-r",
        "--root",
        required=True,
        help="TASK root, sessions JSON file, or parent directory to scan.",
    )
    parser.add_argument(
        "--report-root",
        help="Override report root. Defaults to <TASK>/report for each session.",
    )
    parser.add_argument(
        "--env-file",
        help=(
            "Optional .env file for MODEL_API_KEY/ANTHROPIC_API_KEY. Defaults to "
            "<root>/.env, the current directory .env, then the script directory .env."
        ),
    )
    parser.add_argument(
        "--workers",
        type=int,
        default=1,
        help="并行处理的 TASK 数(task 级并行)。默认 1(串行)。",
    )
    parser.add_argument(
        "--session-name",
        action="append",
        metavar="NAME_OR_GLOB",
        help=(
            "只处理这些 session（可重复）：精确文件名 / 纯 stem / fnmatch glob。"
            "没命中的选择器会被报告。"
        ),
    )
    parser.add_argument(
        "--preserve-step1-failures",
        action="store_true",
        help=(
            "Report exhausted Step1 failures as skipped and leave their source "
            "session files byte-for-byte unchanged."
        ),
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Plan and report gated insertions without modifying session files.",
    )
    return parser


def addtool_main() -> int:
    parser = addtool_build_arg_parser()
    args = parser.parse_args()

    root = Path(args.root).expanduser().resolve()
    if not root.exists():
        print(f"error: root path does not exist: {root}")
        return 2

    env_path = Path(args.env_file).expanduser().resolve() if args.env_file else None
    config = resolve_runtime_config(root=root, env_path=env_path)
    llm_enabled = bool(config.api_key)
    if not llm_enabled:
        env_hint = config.env_path or "environment variables or discovered .env files"
        print(
            f"warning: missing MODEL_API_KEY or ANTHROPIC_API_KEY in {env_hint}; "
            "using deterministic selection"
        )

    report_root_override = (
        Path(args.report_root).expanduser().resolve() if args.report_root else None
    )
    workers = max(1, int(args.workers))
    session_files = discover_session_files(root)
    session_names = tuple(args.session_name or ())
    if session_names:
        selected = [p for p in session_files if addtool_session_name_matches(p, session_names)]
        unmatched = [
            sel
            for sel in session_names
            if not any(addtool_session_name_matches(p, (sel,)) for p in session_files)
        ]
        if unmatched:
            print(
                "warning: --session-name selector(s) matched no session: "
                + ", ".join(unmatched)
            )
        print(
            f"--session-name filter: {len(selected)}/{len(session_files)} "
            "session(s) selected"
        )
        session_files = selected
    failed_step1_sessions = (
        _failed_step1_session_keys(root) if args.preserve_step1_failures else set()
    )
    if not session_files:
        reason_code = (
            "SESSION_SELECTOR_NO_MATCH" if session_names else "NO_SESSIONS_FOUND"
        )
        print(
            f"No session JSON files found under {root}; "
            f"rerun_required=true reason_codes={reason_code}"
        )
        return 1

    timestamp = datetime.now().strftime("%Y%m%d%H%M%S%f")

    # 以 TASK 为并行粒度:同一 task 的多个 session 共写一个 report,故按 task 分组;
    # 不同 task 的 report 对象/报告文件/session 文件互不共享,天然无写入竞争。
    groups: dict[Path, list[Path]] = defaultdict(list)
    for path in session_files:
        groups[find_task_root(path)].append(path)
    items = sorted(groups.items(), key=lambda kv: str(kv[0]))

    print(f"Found {len(session_files)} session file(s) in {len(items)} task(s)")
    print(
        f"Mode: {'dry-run' if args.dry_run else 'write'}; "
        f"planner: {'LLM' if llm_enabled else 'deterministic'}; "
        f"workers: {workers}"
    )

    def handle_task(task_root: Path, task_sessions: list[Path]) -> tuple[dict[str, Any], Path]:
        report = addtool_build_report(
            scan_root=root,
            task_root=task_root,
            llm_enabled=llm_enabled,
            model=config.model,
        )
        report["mode"] = "dry-run" if args.dry_run else "write"
        for path in task_sessions:
            try:
                rel = path.relative_to(task_root)
            except ValueError:
                rel = path
            # 并发下逐行 print 会把不同 session 的日志交错在一起(行错位),
            # 改为:每个 session 的全部日志攒成一块,处理完整体原子输出。
            buffer: list[str] = [f"Processing {task_root.name}/{rel}"]
            process_session_file(
                path,
                report_root_override=report_root_override,
                config=config,
                report=report,
                dry_run=args.dry_run,
                emit=buffer.append,
                failed_step1_sessions=failed_step1_sessions,
            )
            with _PRINT_LOCK:
                print("\n".join(buffer), flush=True)
        report["summary"]["rerun_required"] = bool(
            report["summary"]["errors"]
            or report["summary"]["gate_failures"]
            or report["summary"]["file_failures"]
            or report["summary"]["files_seen"] == 0
        )
        insertions = report.get("insertions") or []
        merged_report = [
            {
                # 定位字段放最前:插到哪个 task 的哪个 json、哪个消息位、哪些行。
                "task": ins.get("task", task_root.name),
                "session_file": ins.get("session_file")
                or Path(ins["session"]).name,
                "session_path": ins["session"],
                "insert_at_message_index": ins["insert_at_message_index"],
                "inserted_message_indexes": ins.get("inserted_message_indexes"),
                "anchor_message_index_after_insert": ins.get(
                    "anchor_message_index_after_insert"
                ),
                "inserted_roles": ins.get("inserted_roles"),
                "tool_call_id": ins.get("tool_call_id"),
                "line_range": ins.get("line_range"),
                "line_range_verified": ins.get("line_range_verified"),
                "line_range_basis": (
                    "1-based inclusive lines of the session json AS WRITTEN BY "
                    "THIS STEP; if a later step rewrites the file, locate by "
                    "tool_call_id instead"
                ),
                "locate_hint": (
                    f"grep -n \"{ins.get('tool_call_id', '')}\" "
                    f"sessions/{ins.get('session_file') or Path(ins['session']).name}"
                ),
                "appended_summary": ins.get("appended_summary"),
                "target_time_shift": ins.get("target_time_shift"),
                "nodes": ins["nodes"],
            }
            for ins in insertions
        ]
        report_path = make_report_path(task_root, timestamp)
        report_path.parent.mkdir(parents=True, exist_ok=True)
        redaction_roots = {task_root: "<TASK_ROOT>"}
        atomic_write_json(
            report_path,
            redact_paths(report, known_roots=redaction_roots),
        )
        atomic_write_json(
            report_path.with_suffix(".insertions.json"),
            redact_paths(merged_report, known_roots=redaction_roots),
        )
        # 需求2:每个 TASK 的 report/ 下产出 re-runtest.json(结构对齐 structure.json),
        # 只登记发生了补测插入的会话。放行/无需补测的会话不写入。
        # after_content 走脱敏(与落盘 session 内容一致);task_path 保留真实路径(对齐示例)。
        # 用 atomic_write_text 而非 atomic_write_json:后者 sort_keys=True 会打乱字段顺序,
        # 这里必须严格保持事例 json 的字段顺序(report_type→task_id→…→sessions)。
        rerun_report = build_rerun_report(task_root, task_sessions, report)
        rerun_report = redact_paths(rerun_report, known_roots=redaction_roots)
        rerun_report["task_path"] = str(task_root)
        atomic_write_text(
            task_root / "report" / "re-runtest.json",
            json.dumps(rerun_report, ensure_ascii=False, indent=2) + "\n",
        )
        if insertions:
            summary_lines = [
                f"[插入清单] {task_root} 共 {len(insertions)} 处:"
            ]
            for ins in insertions:
                lr = ins.get("line_range") or [-1, -1]
                name = ins.get("session_file") or Path(ins["session"]).name
                summary_lines.append(
                    f"  - {task_root / 'sessions' / name}: "
                    f"消息#{ins['insert_at_message_index']}前 "
                    f"L{lr[0]}-L{lr[1]} id={ins.get('tool_call_id', '')}"
                )
            summary_lines.append(
                f"  审计详情: {report_path.with_suffix('.insertions.json').name}"
            )
            with _PRINT_LOCK:
                print("\n".join(summary_lines), flush=True)
        return report, report_path

    reports: dict[Path, dict[str, Any]] = {}
    report_paths: list[Path] = []
    if workers > 1 and len(items) > 1:
        with ThreadPoolExecutor(max_workers=workers) as executor:
            future_map = {
                executor.submit(handle_task, task_root, task_sessions): task_root
                for task_root, task_sessions in items
            }
            for future in as_completed(future_map):
                task_root = future_map[future]
                report, report_path = future.result()
                reports[task_root] = report
                report_paths.append(report_path)
    else:
        for task_root, task_sessions in items:
            report, report_path = handle_task(task_root, task_sessions)
            reports[task_root] = report
            report_paths.append(report_path)
    report_paths.sort(key=str)

    total = {
        "files_seen": 0,
        "files_modified": 0,
        "messages_considered": 0,
        "messages_inserted_before": 0,
        "tool_events_inserted": 0,
        "skipped": 0,
        "errors": 0,
        "gate_failures": 0,
        "file_failures": 0,
    }
    for report in reports.values():
        for key in total:
            total[key] += int(report["summary"].get(key, 0))

    print("\nDone")
    print(f"  files_seen:               {total['files_seen']}")
    print(f"  files_modified:           {total['files_modified']}")
    print(f"  messages_considered:      {total['messages_considered']}")
    print(f"  messages_inserted_before: {total['messages_inserted_before']}")
    print(f"  tool_events_inserted:     {total['tool_events_inserted']}")
    print(f"  skipped:                  {total['skipped']}")
    print(f"  errors:                   {total['errors']}")
    print(f"  gate_failures:            {total['gate_failures']}")
    print(f"  file_failures:            {total['file_failures']}")
    print("  report files:")
    for report_path in report_paths:
        print(f"    {report_path}")
    return 1 if any(
        total[key] for key in ("errors", "gate_failures", "file_failures")
    ) else 0


# =========================================================================== #
# SECTION: detect_test_claims  (ported from detect_test_claims.py)
# =========================================================================== #
# LLM 检测 agent 轨迹「收尾窗口（倒数几个节点）是否已有一次完全通过的正式测试」
# (needs_final_test)。对每条 source session 先跑一次精准的大模型判官，据其 needs_final_test
# 决定是否补测及 prompt profile。
#
# 判官模型固定复用仓库既有 model_config（channel=openai，默认 gpt-5.6），与 detect_test_claims.py
# 保持一致，**不**走 pipeline 自己的 anthropic-messages 客户端（那是给 add_run_test 规划器用的）。
# model_config 依赖 langchain-openai，采用惰性导入：只有真正启用检测时才 import，未安装则给出
# 清晰报错而不影响 pipeline 其它子命令。

TCD_REPORT_TYPE = "test_claim_not_run_report"
TCD_MODEL_TIMEOUT_SECONDS = 150
TCD_JUDGE_RETRIES = 2
# 判官内层(langchain/openai)重试次数：0 表示禁用内层重试，全权交给外层 TCD_JUDGE_RETRIES。
TCD_MODEL_MAX_RETRIES = 0
TCD_DEFAULT_WORKERS = 6

# 「收尾必测」维度：session 末尾若最后 N 轮 assistant 都没有跑测试的迹象，判为 needs_final_test。
FINAL_TEST_WINDOW = 5

# ---- 证据压缩上限 ----
ASSISTANT_TEXT_CHARS = 900       # 每条 assistant 正文截断
CMD_CHARS = 260                  # 每个工具调用参数截断
TEST_RESULT_HEAD_CHARS = 500     # 测试/构建类返回：头部
TEST_RESULT_TAIL_CHARS = 1200    # 测试/构建类返回：尾部（含汇总行）
OTHER_RESULT_CHARS = 90          # 其它命令返回：只给短片段
MAX_EVIDENCE_CHARS = 70000       # 单 session 完整证据预算（超出切到"仅测试证据"精简视图）
TEST_ONLY_HARD_CAP = 140000      # 精简视图硬上限；保证真实测试运行证据不因预算被丢

# ---- 是否「真的在跑测试」的命令识别（供证据标注，最终判定仍由模型做）----
_TEST_RUN_PATTERNS = [
    r"\bpytest\b", r"py\.test", r"-m\s+pytest", r"-m\s+unittest",
    r"npm\s+(run\s+)?test", r"yarn\s+test", r"pnpm\s+(run\s+)?test",
    r"\bjest\b", r"\bvitest\b", r"\bmocha\b", r"\bnose2?\b", r"\btox\b",
    r"go\s+test", r"cargo\s+test", r"cargo\s+nextest", r"phpunit", r"\brspec\b", r"dotnet\s+test",
    r"xcodebuild\s+[^&|;]*\btest\b", r"swift\s+test",
    r"python[0-9.]*\s+\S*test\S*\.py", r"run_tests?", r"\btest\.sh\b",
    r"\bbash\s+\S*test\w*\.(?:sh|bash|py|js|ts|rb)\b",
    r"\bsh\s+\S*test\w*\.(?:sh|bash|py|js|ts|rb)\b",
    r"ctest", r"gradlew?\s[^&|;]*\btest\b",
    # 常见「入口式」测试命令(用户明确列出的真实终态形态,之前全部漏判)。
    r"\bmake\b[^&|;]*\btest\b", r"\brake\b\s+\S*test", r"composer\s+(run(-script)?\s+)?test",
    r"(bin/)?rails\s+test", r"\bdeno\s+test", r"\bjust\b\s+\S*test", r"\btask\b\s+\S*test",
    r"\bbundle\s+exec\s+(rspec|rails\s+test|ruby\s+\S*test)",
]
_TEST_RUN_RE = re.compile("|".join(_TEST_RUN_PATTERNS), re.IGNORECASE)
_MVN_TEST_RE = re.compile(r"\bmvn\b[^&|;]*\btest\b", re.IGNORECASE)
_MVN_COMPILE_ONLY_RE = re.compile(r"\bmvn\b[^&|;]*test-compile", re.IGNORECASE)
_BUILD_HINT_RE = re.compile(r"\bmvn\b|\bgradle|\bnpm\b|\byarn\b|\bpnpm\b|\bpytest\b|phpunit|go\s+test|cargo|dotnet|\.sh\b|test", re.IGNORECASE)
# 只「收集/列举」而不执行测试的形态:即便命中测试器名也不算一次真跑(输出如 `collected N items`)。
_COLLECT_ONLY_RE = re.compile(
    r"--collect-only|--collectonly|(?:^|\s)--co(?:\s|$)|--fixtures\b|--markers\b"
    r"|--setup-plan\b|--setup-only\b|--list-?tests?\b|--listTests\b|(?:^|\s)-list\b|go\s+test\s+[^&|;]*-list\b",
    re.IGNORECASE)
# 循环批量跑测试:`for f in tests/*.sh; do bash "$f"; done`(分号切分会拆散,故整串判)。
_LOOP_TEST_EXEC_RE = re.compile(
    r"\b(for|while)\b[^;]*\btest[^;]*;\s*do\b[^;]*\b(bash|sh|pytest|py\.test|node|python[0-9.]*|go\s+test|npx)\b",
    re.IGNORECASE)
# `python -c "import fastapi, pytest, ..."` 只是导入冒烟(验证依赖可导入),不是在跑测试:
# 其中的 `pytest` 仅出现在 import 列表里。除非同段确有 `pytest.main(`/`.main(` 调用才算真跑。
_IMPORT_SMOKE_RE = re.compile(r"python[0-9.]*\s+-c\s+['\"][^'\"]*\bimport\b", re.IGNORECASE)


def looks_like_test_run(cmd: str) -> bool:
    if _TEST_RUN_RE.search(cmd):
        return True
    if _MVN_TEST_RE.search(cmd) and not _MVN_COMPILE_ONLY_RE.search(cmd):
        return True
    return False


# 「只是引用/查看」测试脚本或旧日志、并非执行的命令首 token（收尾必测口径要排除这些）。
_NON_EXEC_HEADS = {
    "chmod", "cat", "tail", "head", "less", "more", "grep", "egrep", "fgrep",
    "rg", "ag", "sed", "awk", "ls", "ll", "find", "wc", "stat", "file", "touch",
    "cp", "mv", "rm", "mkdir", "echo", "printf", "vim", "vi", "nano", "view",
    "git", "diff", "tree", "cd", "export", "pwd", "which", "whoami", "date",
}
# 正式测试运行器额外补充：Django manage.py test。
_EXTRA_TEST_EXEC_RE = re.compile(r"\bmanage\.py\s+test\b|call_command\(\s*['\"]test", re.IGNORECASE)
# 安装/下载/打包类命令段：即使含 "pytest"/"test" 字样也不是在跑测试。
_INSTALL_SEG_RE = re.compile(
    r"\b(pip[0-9.]*\s+(install|download)|python[0-9.]*\s+-m\s+pip\s+(install|download)"
    r"|npm\s+(install|i|ci|add)|yarn\s+add|pnpm\s+(install|add)|poetry\s+(add|install)"
    r"|apt(-get)?\s+install|brew\s+install|go\s+get|cargo\s+add|gem\s+install|--dry-run)\b",
    re.IGNORECASE)


def _split_shell_segments(cmd: str) -> list[str]:
    """按 shell 操作符 `&&` `||` `;` `|` 切分命令,但**不切引号内的内容**。

    朴素 `re.split(r"&&|\\|\\||;|\\|", cmd)` 会把 `grep -v 'a\\|b'` 这种引号内含转义竖线的
    grep 参数从 `\\|` 处劈开,碎片(如 `.phpunit.cache'`)恰好命中测试器子串正则被误判为真跑。
    此处做引号感知切分,保证引号内文本不被当作操作符。"""
    segs: list[str] = []
    buf: list[str] = []
    quote: str | None = None
    i, n = 0, len(cmd)
    while i < n:
        ch = cmd[i]
        if quote:
            buf.append(ch)
            if ch == quote:
                quote = None
            i += 1
            continue
        if ch in "'\"":
            quote = ch
            buf.append(ch)
            i += 1
            continue
        if cmd[i:i + 2] in ("&&", "||"):
            segs.append("".join(buf)); buf = []; i += 2; continue
        if ch in ";|":
            segs.append("".join(buf)); buf = []; i += 1; continue
        buf.append(ch)
        i += 1
    segs.append("".join(buf))
    return segs


def genuine_test_exec(cmd: str) -> bool:
    """命令是否为一次真正执行的正式测试运行（而非引用/查看/构建/冒烟/安装/仅收集）。"""
    if not cmd:
        return False
    # 循环批量跑测试(`for f in tests/*.sh; do bash "$f"; done`)分段会被拆散,先整串判。
    if _LOOP_TEST_EXEC_RE.search(cmd):
        return True
    for seg in _split_shell_segments(cmd):
        seg = seg.strip()
        if not seg:
            continue
        head = re.split(r"\s+", seg, maxsplit=1)[0]
        head = head.rsplit("/", 1)[-1].lower()  # basename，兼容 ./run_tests.sh、/usr/bin/pytest
        if head in _NON_EXEC_HEADS:
            continue
        if _INSTALL_SEG_RE.search(seg):
            continue
        if _COLLECT_ONLY_RE.search(seg):  # 只收集/列举、不执行 → 不算真跑
            continue
        if _IMPORT_SMOKE_RE.search(seg) and ".main(" not in seg:  # 导入冒烟检查,非跑测试
            continue
        if looks_like_test_run(seg) or _EXTRA_TEST_EXEC_RE.search(seg):
            return True
    return False


def _tcd_tool_calls(msg: dict) -> list[tuple[str, str, str]]:
    out = []
    for tc in msg.get("tool_calls") or []:
        fn = tc.get("function", {})
        a = fn.get("arguments", "")
        if not isinstance(a, str):
            a = json.dumps(a, ensure_ascii=False)
        out.append((fn.get("name", ""), a, tc.get("id")))
    return out


def _tcd_short_cmd(name: str, args: str) -> str:
    """把一个工具调用压成一行可读命令。Bash 给命令串，Write/Edit 给文件路径。"""
    try:
        obj = json.loads(args)
    except Exception:
        obj = {}
    if name == "Bash":
        c = obj.get("command", args)
        return c[:CMD_CHARS]
    if name in ("Write", "Edit", "Read", "NotebookEdit"):
        fp = obj.get("file_path", "")
        tag = " [TEST-FILE]" if re.search(r"test", fp, re.I) else ""
        return f"{fp}{tag}"[:CMD_CHARS]
    return args[:CMD_CHARS]


def _tcd_fmt_result(res: str, is_test_or_build: bool) -> str:
    """测试/构建类：头+尾（保住末尾的 Tests run/BUILD SUCCESS 汇总行）；其它：短片段。"""
    res = res.strip()
    if not is_test_or_build:
        return f"    -> RESULT[{len(res)}c]: {res[:OTHER_RESULT_CHARS]}"
    if len(res) <= TEST_RESULT_HEAD_CHARS + TEST_RESULT_TAIL_CHARS:
        return f"    -> RESULT: {res}"
    head = res[:TEST_RESULT_HEAD_CHARS]
    tail = res[-TEST_RESULT_TAIL_CHARS:]
    return f"    -> RESULT(head): {head}\n    ...\n    -> RESULT(tail): {tail}"


_RESULT_TEST_EVID_RE = re.compile(
    r"\bTests?\s+run:\s*\d+|\d+\s+passed|\d+\s+failed|BUILD SUCCESS|BUILD FAILURE|"
    r"OK\s*\(\d+\s+tests?\)|collected\s+\d+\s+item|=+\s*\d+\s+(passed|failed)|"
    r"failures=\d+|errors=\d+|测试[^。\n]{0,6}(通过|失败)|全部通过|passed in\b|no tests ran|"
    r"---\s+(FAIL|PASS):|===\s+RUN\b|^ok\s+\S+\s+[\d.]+s|\bok\s+\S+/\S+\s+[\d.]+s|^FAIL\b|^PASS\b|"
    r"Test Run Successful|TEST SUCCEEDED|Total:\s*\d+\s*\|?\s*Passed|Passed:\s*\d+|"
    r"Executed\s+\d+\s+tests?|GRAND TEST SUMMARY|ALL TESTS PASSED|Ran\s+\d+\s+tests?",
    re.IGNORECASE | re.MULTILINE)


# 更严格的"正式测试运行汇总"识别，专供收尾必测 oracle 的"浮现结果"路径。
_STRONG_TEST_SUMMARY_RE = re.compile(
    r"\bTests?\s+run:\s*\d+"
    r"|OK\s*\(\d+\s+tests?\)"
    r"|Ran\s+\d+\s+tests?"
    r"|Executed\s+\d+\s+tests?"
    r"|collected\s+\d+\s+items?"
    r"|Test\s+Suites?:\s*\d+\s+passed"
    r"|Tests:\s*\d+\s+passed"
    r"|ALL\s+PASSED\s*\(\d+\s+tests?\)"
    r"|All\s+\d+\s+tests?\s+pass"
    r"|\d+\s+passed,\s*\d+\s+(warning|skipped|xfailed|deselected|error|failed)"
    r"|\d+\s+tests?,\s*\d+\s+(failure|error)"
    r"|\d+/\d+\s*(通过|passed|passing)"
    r"|=+\s*\d+\s+(passed|failed|error)"
    r"|\d+\s+passed[ ,].*?\d+\s+failed"
    r"|\d+\s+(passed|failed)\b[^\n]*\bin\s+[\d.]+\s*s"
    r"|passed in\s+[\d.]+\s*s"
    r"|---\s+(FAIL|PASS):"
    r"|\bok\s+\S+/\S+\s+[\d.]+s"
    r"|Running\s+\d+\s+tests?\s+using"
    r"|TOTAL:\s*\d+\s+(SUCCESS|passed|cases)"
    r"|Test Run Successful|TEST SUCCEEDED|ALL TESTS PASSED|GRAND TEST SUMMARY"
    r"|测试[^。\n]{0,6}(通过|失败)|全部通过|全部测试通过|no tests ran",
    re.IGNORECASE | re.MULTILINE)


# 「完全成功」专用:只保留**肯定通过**的汇总,剔除仅表示测试**开始/收集**(`collected N items`、
# `Running N tests using`)、零测试(`no tests ran`)、以及提及失败的组合。用于 count-less 的成功
# 兜底,避免上游把失败汇总截断后只剩起始横幅被误判为完全成功(A2:截断输出 false-pass)。
_STRONG_PASS_SUMMARY_RE = re.compile(
    r"\bTests?\s+run:\s*\d+(?![^\n]*(?:Failure|Error)s?:\s*[1-9])"
    r"|OK\s*\(\d+\s+tests?\b"
    r"|Ran\s+\d+\s+tests?[^\n]*\bOK\b"
    r"|Executed\s+\d+\s+tests?"
    r"|Test\s+Suites?:\s*\d+\s+passed"
    r"|Tests:\s*\d+\s+passed"
    r"|ALL\s+PASSED\s*\(\d+\s+tests?\)"
    r"|All\s+\d+\s+tests?\s+pass"
    r"|\d+/\d+\s*(通过|passed|passing)"
    r"|passed in\s+[\d.]+\s*s"
    r"|\d+\s+passed\b[^\n]*\bin\s+[\d.]+\s*s"
    r"|\d+\s+passing\b"                        # mocha 成功
    r"|100%\s+tests\s+passed"                  # ctest 成功
    r"|---\s+PASS:"                            # go 通过(非 FAIL)
    r"|^\s*ok\s+\S+\s+[\d.]+s"                 # go 单包通过(放宽:模块名可无斜杠,C4)
    r"|Test Run Successful|TEST SUCCEEDED|ALL TESTS PASSED|GRAND TEST SUMMARY"
    r"|TOTAL:\s*\d+\s+(SUCCESS|passed|cases)"
    r"|全部通过|全部测试通过|测试[^。\n]{0,6}通过",
    re.IGNORECASE | re.MULTILINE)


def obj_command(args: str) -> str:
    try:
        return json.loads(args).get("command", args)
    except Exception:
        return args


def obj_command_str(cmd_or_args: str) -> str:
    return cmd_or_args


def _tcd_expand_result(name: str, cmd: str, res: str) -> bool:
    """该工具返回是否应"详展"（头+尾）而非截成 90 字符。"""
    if name == "Bash" and (looks_like_test_run(obj_command_str(cmd)) or _BUILD_HINT_RE.search(cmd)):
        return True
    if name in ("Agent", "Task") and res and _RESULT_TEST_EVID_RE.search(res):
        return True
    if res and _RESULT_TEST_EVID_RE.search(res):
        return True
    return False


def _tcd_user_test_evidence(content: str) -> str | None:
    """USER 消息里可能内联真实测试证据：QA 测试台输出、粘贴日志、task-notification、压缩摘要。"""
    if not content:
        return None
    if _RESULT_TEST_EVID_RE.search(content) or re.search(
        r"task-notification|exit code 0|exit_code.{0,3}0|OVERALL:\s*PASS|ALL TESTS PASSED|"
        r"PASS\b.*FAIL|Passed:\s*\d+|test result:\s*ok|PROBE_(PASS|FAIL)", content, re.IGNORECASE):
        c = content.strip()
        if len(c) <= TEST_RESULT_HEAD_CHARS + TEST_RESULT_TAIL_CHARS:
            return c
        return c[:TEST_RESULT_HEAD_CHARS] + "\n    ...\n" + c[-TEST_RESULT_TAIL_CHARS:]
    return None


def _tcd_emit_calls(block: list, calls, results) -> None:
    for name, args, cid in calls:
        cmd = _tcd_short_cmd(name, args)
        res = results.get(cid, "")
        is_run = name == "Bash" and looks_like_test_run(obj_command(args))
        run_tag = "  <== TEST-RUN CMD" if is_run else ""
        deleg = "  <== SUBAGENT (result inlined below)" if name in ("Agent", "Task") else ""
        block.append(f"  CALL {name}: {cmd}{run_tag}{deleg}")
        if res:
            block.append(_tcd_fmt_result(res, _tcd_expand_result(name, cmd, res)))


def build_evidence(data: dict) -> tuple[str, list[int]]:
    """构造 session 的测试证据时间线文本；返回 (evidence_text, assistant_node_indices)。

    只把 assistant 的正文 content 当作可命中的"陈述"；不喂 reasoning_content。"""
    msgs = data["messages"]
    results = {m.get("tool_call_id"): (m.get("content") or "")
               for m in msgs if m.get("role") == "tool"}
    asst_nodes = [i for i, m in enumerate(msgs) if m.get("role") == "assistant"]

    tail_set = set(asst_nodes[-FINAL_TEST_WINDOW:]) if asst_nodes else set()
    first_tail = min(tail_set) if tail_set else None

    def render(include_other_results: bool) -> str:
        lines = []
        for i, m in enumerate(msgs):
            role = m.get("role")
            if role == "user":
                ev = _tcd_user_test_evidence(m.get("content") or "")
                if ev:
                    lines.append(f"[node {i}] USER (含测试证据/外部结果):\n    {ev}")
                continue
            if role != "assistant":
                continue
            if i == first_tail:
                lines.append(
                    "══════════ 以下是本 session 最后 "
                    f"{len(tail_set)} 轮 assistant（收尾窗口）"
                    "；needs_final_test 只看这个窗口内有没有真跑测试 ══════════"
                )
            txt = (m.get("content") or "").strip()
            calls = _tcd_tool_calls(m)
            tail_tag = "  «收尾窗口»" if i in tail_set else ""
            block = [f"[node {i}] ASSISTANT:{tail_tag}"]
            block.append(f'  TEXT: {txt[:ASSISTANT_TEXT_CHARS]}' if txt else "  TEXT: (无正文，仅工具调用)")
            if include_other_results:
                _tcd_emit_calls(block, calls, results)
            else:
                for name, args, cid in calls:
                    cmd = _tcd_short_cmd(name, args)
                    res = results.get(cid, "")
                    is_run = name == "Bash" and looks_like_test_run(obj_command(args))
                    run_tag = "  <== TEST-RUN CMD" if is_run else ""
                    deleg = "  <== SUBAGENT" if name in ("Agent", "Task") else ""
                    block.append(f"  CALL {name}: {cmd}{run_tag}{deleg}")
                    if res and _tcd_expand_result(name, cmd, res):
                        block.append(_tcd_fmt_result(res, True))
            lines.append("\n".join(block))
        return "\n\n".join(lines)

    def render_tail_detail() -> str:
        """收尾窗口逐节点全量详情：确保判官对 needs_final_test 决定性的窗口始终可见。"""
        if first_tail is None:
            return ""
        lines = [f"\n\n【收尾窗口逐节点详情（needs_final_test 只依据这一段；共最后 {len(tail_set)} 轮 assistant）】"]
        for i in sorted(tail_set):
            m = msgs[i]
            txt = (m.get("content") or "").strip()
            block = [f"[node {i}] ASSISTANT «收尾窗口»:"]
            block.append(f'  TEXT: {txt[:ASSISTANT_TEXT_CHARS]}' if txt else "  TEXT: (无正文，仅工具调用)")
            _tcd_emit_calls(block, _tcd_tool_calls(m), results)
            lines.append("\n".join(block))
        for j in range(first_tail, len(msgs)):
            if msgs[j].get("role") == "user":
                ev = _tcd_user_test_evidence(msgs[j].get("content") or "")
                if ev:
                    lines.append(f"[node {j}] USER (含测试证据/外部结果):\n    {ev}")
        return "\n\n".join(lines)

    text = render(include_other_results=True)
    if len(text) > MAX_EVIDENCE_CHARS:
        text = render(include_other_results=False)[:TEST_ONLY_HARD_CAP]
    text = text + render_tail_detail()
    return text, asst_nodes


def get_task_context(data: dict) -> str:
    """取第一条 user 消息前 1200 字符作为任务背景。"""
    for m in data["messages"]:
        if m.get("role") == "user":
            c = m.get("content") or ""
            if isinstance(c, str):
                return c[:1200]
    return ""


# ============================ 提示词 ============================
TCD_SYSTEM_PROMPT = r"""你是严谨的 agent 轨迹审计员。你只做**一件**事：判断这条 session 收尾时
"该不该补跑一次测试"（needs_final_test）。

【判定原则】每条主 session 收尾前，都应当真跑过一次**完全成功**的正式自动化测试。你只需回答：
收尾处最近一次正式测试是否**真的跑了、且完全通过**。
  • 收尾处**有"跑正式测试且完全通过的迹象"** → needs_final_test = **false**（收尾已测且全绿，无需补）。
  • 收尾处**没有**上述迹象，**或**最近一次收尾测试**含任何失败/未确认全绿** → needs_final_test = **true**
    （收尾没测，或测了但没干净通过，需要补一次干净通过的收尾测试）。

【判据范围：只看收尾窗口】判据**只看收尾窗口**——即证据末尾「【收尾窗口逐节点详情…】」那一段，
以及时间线里用「«收尾窗口»」标注的最后 N 条 assistant（对应"最后节点往上的最近几个节点"）。
**严禁**用收尾窗口以外（没有 «收尾窗口» 标记）的 node 作依据；只要你的理由引用了窗口外的 node，就是错的。
session **前半段/窗口外**跑过测试**不影响** needs_final_test——只要**收尾窗口内**没有正式测试的完全通过迹象就为 true。

⚠️**"完全成功"是硬条件（这是判 false 的唯一门槛，务必逐字核对 RESULT）**：那次收尾测试运行的结果里
**不得含任何失败/报错**（无 `N failed`(N>0)、`Failures: N`(N>0)、`Errors: N`(N>0)、`--- FAIL:`、
`BUILD FAILURE/FAILED`、`FAILED`、`panic:`、`test result: FAILED`、`AssertionError`、Traceback、非零退出
`RUNNER_EXIT=<非0>`/`exit code <非0>` 等），**且**要有**正向通过证据**（`N passed`、`pass=N/fail=0`、
`OK (N tests)`、`Ran N tests…OK`、`test result: ok`、pytest 点阵全绿、`Tests: N passed`、`BUILD SUCCESS`、
`100% tests passed`、`ALL TESTS PASSED` 等）。
**只要最近这次收尾测试里出现了任何失败/错误** → 即便它"确实跑了"，也判 needs_final_test = **true**
（这条 session 收尾停在了一次失败/未修复的测试上，需要删掉它并补一次干净通过的收尾测试）。
只有**空泛声称"测试通过"却在收尾窗口 RESULT 里查不到任何真实测试汇总/退出码** → 也判 true（无真实证据）。

【什么算"跑正式测试且完全通过的迹象"】收尾窗口内出现下列之一，且其 RESULT/USER 证据显示测试**确实被执行并全绿**：
  (1) 直接执行了正式测试框架/runner（跨语言，覆盖大多数生态）：
      pytest / py.test / python -m unittest / python xxx_test.py / manage.py test（Django）/
      npm|yarn|pnpm test / jest / vitest / mocha / tox / nose / go test / cargo test /
      mvn|gradle test / ./gradlew test / phpunit / rspec / dotnet test / ctest / xcodebuild test /
      ./run_tests.sh、bash run_tests.sh、run_api_tests.sh 之类测试脚本；**或**
  (2) 收尾窗口内**浮现出真实测试运行的输出/结果**：子代理(Agent/Task)内联返回、TaskOutput/BashOutput 回收的
      后台测试输出、`tail/cat` 出的后台测试日志、docker compose 跑 pytest 的点阵、USER 粘贴的测试台结果、
      **或用 Read/Grep/cat 读到一份测试结果报告/日志文件**里明确的测试运行汇总——只要浮现的内容里有真实测试
      汇总行（`Tests run: N`、`Test Suites: N passed`、`Tests: 133 passed`、`OK (N tests)`、`Executed/Ran N tests`、
      `ALL TESTS PASSED`、`327/327 passed`、pytest 点阵、`--- PASS`、`test result: ok` 等）即算
      （仍受上面"完全成功"硬条件约束：汇总里若含失败计数/失败行/非零退出 → needs_final_test=true）。
      ⚠️区分：读到的是**测试结果/报告/日志**（含上述汇总，算）vs 读到的是**测试脚本源码/计划文档**
      （如 `cat run_tests.sh` 只看到脚本里 `echo "All tests PASSED"` 这类字符串、或读实施计划）——后者**不算**。

⚠️**这些不算"跑正式测试"**（收尾只有它们 → 仍然 needs_final_test=true）：curl / wget / HTTP 状态码探测 /
  健康检查(healthz) / 冒烟测试(smoke) / 手写 `python -c` 里的 requests/test_client 临时功能探测 / 浏览器式验证 /
  只编译或 lint / tsc / `cargo check` / mvn test-compile / `dotnet build` / eslint / `bash -n` 语法检查 /
  `chmod`/`cat`/`grep`/`git`(add|commit|push) 只是引用或查看测试脚本却没执行 / 更新 Todo / 纯文字总结 /
  只启动服务(docker up)。典型 true：末尾几轮只在写文件 / 改代码 / 构建 / commit / 纯总结。

你会看到该 session 的「测试证据时间线」：按 node 顺序列出每条 assistant 的**面向用户的正文(TEXT)**、
它发起的工具调用(CALL) 及返回(RESULT)，以及**含测试证据的 USER 消息**（QA 测试台输出、粘贴的运行日志、
`<task-notification> exit code 0`、压缩摘要里记录的历史测试结果）。凡是真正跑测试的 Bash 命令我已用
「<== TEST-RUN CMD」标出，子代理委托用「<== SUBAGENT」标出（均仅供参考，你仍需自己核对 RESULT/USER 证据）。

⚠️ RESULT 可能被截断为「头部 + 尾部」两段（中间用 ... 省略）。**构建/测试工具的汇总行几乎总在尾部**
（如 Maven `Tests run: N, Failures: 0`、`BUILD SUCCESS`；pytest `N passed`；PHPUnit `OK (N tests)`；
docker compose 跑 pytest 时点阵和 `N passed` 也在最末）。判断"有没有真跑通过"要**看 RESULT(tail)**，
不要因为 head 只有启动/迁移/compose 日志就断定没跑；也不要因为 head 有绿色就忽略 tail 里的失败行。

⚠️ 收尾窗口内的**测试执行证据可能出现在窗口任意位置**（assistant 的 Bash/工具 RESULT、USER 消息、
TaskOutput/BashOutput 回收的后台输出、子代理 Agent/Task 的内联 RESULT）。只要窗口内任意位置存在一次
**与收尾相符的、完全通过的**真实测试执行证据 → needs_final_test=false。

⚠️ 你只审计 assistant **正文 TEXT** 与工具 RESULT/USER 证据里的**真实执行痕迹**，不看模型私有思维(reasoning)，
也不被"complete/done/所有任务完成"这类**交付措辞**诱导——没有真实测试汇总/退出码就是 true。

────────────────── 输出（严格 JSON，不要多余文字，不要任何解释性前后缀） ──────────────────
{
  "needs_final_test": true/false,
  "final_test_reason": "<一句话：收尾窗口里最近一次测试是否真跑**且完全通过**。若 true，指出末尾几轮在干什么、或最近那次测试为何不算全绿(有失败/未确认通过/查无实据)；若 false，指出收尾窗口里哪个 node 真跑了什么测试并全绿(引用其汇总行)>"
}
- needs_final_test 务必对每条 session 都给出明确的 true/false，不得省略、不得为 null。
- 只依据收尾窗口证据；拿不准是否全绿时，从严判 **true**（宁可多补一次，也不放过一个未验证的收尾）。"""

TCD_USER_TEMPLATE = """【任务背景(节选)】
{task}

【测试证据时间线】
{evidence}

请按 system 要求，只输出 JSON。"""


def _tcd_parse_json(text: str) -> dict | None:
    if not text:
        return None
    m = re.search(r"\{.*\}", text, re.DOTALL)
    if not m:
        return None
    frag = m.group(0)
    try:
        return json.loads(frag)
    except Exception:
        try:
            return json.loads(frag[:frag.rfind("}") + 1])
        except Exception:
            return None


_SCRIPT_SRC_EXT = (".sh", ".bash", ".py", ".js", ".ts", ".tsx", ".jsx", ".rb",
                   ".go", ".java", ".rs", ".c", ".cpp", ".php", ".bat", ".ps1")
_VIEW_HEADS = {"cat", "head", "tail", "sed", "less", "more", "bat", "nl"}


def _tcd_reads_script_source(name: str, args: str) -> bool:
    """该工具调用是否只是在**查看脚本源码**（读脚本里的 `echo "All tests PASSED"` 不算真实结果）。"""
    try:
        obj = json.loads(args)
    except Exception:
        obj = {}
    if name in ("Read", "NotebookEdit"):
        return str(obj.get("file_path", "")).lower().endswith(_SCRIPT_SRC_EXT)
    if name == "Grep":
        return str(obj.get("path", "")).lower().endswith(_SCRIPT_SRC_EXT)
    if name == "Bash":
        cmd = str(obj.get("command", "")).strip()
        segs = [s.strip() for s in re.split(r"&&|\|\||;|\|", cmd) if s.strip()]
        viewed_script = False
        for seg in segs:
            head = re.split(r"\s+", seg, maxsplit=1)[0].rsplit("/", 1)[-1].lower()
            if head in _VIEW_HEADS:
                if re.search(r"\S+(" + "|".join(re.escape(e) for e in _SCRIPT_SRC_EXT) + r")\b", seg):
                    viewed_script = True
                continue
            if genuine_test_exec(seg):
                return False
        return viewed_script
    return False


def _msg_content_text(content) -> str:
    """把一条消息的 content 归一成纯文本,健壮吃下 None / str / Anthropic content-block 列表。

    收尾 oracle 的正则消费 result 文本;若上游 session 用 content-block 列表序列化(标准
    Claude/Anthropic 格式),`re.finditer(pattern, list)` 会直接抛 TypeError 中断整个 job。
    这里统一 flatten,避免异构结构击穿。"""
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for b in content:
            if isinstance(b, str):
                parts.append(b)
            elif isinstance(b, dict):
                parts.append(str(b.get("text") or b.get("content") or b.get("output") or ""))
        joined = "\n".join(p for p in parts if p)
        return joined if joined else json.dumps(content, ensure_ascii=False)
    return str(content)


def tail_real_test(msgs: list, window: int = FINAL_TEST_WINDOW) -> bool:
    """确定性判断：session 最后 `window` 轮 assistant 里是否出现过任何真实的正式测试运行。

    仅表示「存在」，不判成败。收尾必测的成败口径见 `terminal_test_state`。"""
    if not isinstance(msgs, list):
        return False
    asst_idx = [i for i, m in enumerate(msgs)
                if isinstance(m, dict) and m.get("role") == "assistant"]
    if not asst_idx:
        return False
    tail = asst_idx[-window:]
    results = {m.get("tool_call_id"): _msg_content_text(m.get("content"))
               for m in msgs if isinstance(m, dict) and m.get("role") == "tool"}
    for i in tail:
        for tc in msgs[i].get("tool_calls") or []:
            if not isinstance(tc, dict):
                continue
            fn = tc.get("function") if isinstance(tc.get("function"), dict) else {}
            name = fn.get("name", "")
            a = fn.get("arguments", "")
            a = a if isinstance(a, str) else json.dumps(a, ensure_ascii=False)
            res = results.get(tc.get("id"), "")
            if name == "Bash" and genuine_test_exec(obj_command(a)):
                return True
            if res and _STRONG_TEST_SUMMARY_RE.search(res) \
                    and not _tcd_reads_script_source(name, a):
                return True
    for m in msgs[tail[0]:]:
        if isinstance(m, dict) and m.get("role") == "user" \
                and _STRONG_TEST_SUMMARY_RE.search(_msg_content_text(m.get("content"))):
            return True
    return False


# 收尾窗口成败三态。
TERMINAL_NO_TEST = "no_test"
TERMINAL_PASSING = "passing"
TERMINAL_FAILING = "failing"
# 口径B(用户 2026-07-16 定):最近一次真测**完全成功**,但其后还有代码 Edit(Write/Edit/MultiEdit…)
# → 测试已「过时」(改完代码没再测)→ 需在末节点前**补**一次改完之后的成功测试;**不删**旧的通过测试。
TERMINAL_STALE = "stale"


@dataclass(frozen=True)
class TerminalTestState:
    """收尾窗口的「最近一次真实测试运行」判定结果。

    state:
      - passing : 最近一次真跑且**完全成功**,且其后没有代码改动 → 无需补测。
      - failing : 最近一次真跑但**含失败/未验证成功**(且其后没有更新的成功测试) → 删掉整串
        收尾连续运行 + 重补。
      - stale   : 最近一次真跑**完全成功**,但其后**又改过代码**(Write/Edit/MultiEdit…)→ 测试已过时
        (改完没再测)→ 在末节点前**补**一次改完之后的成功测试;**不删**旧的通过测试(口径B)。
        其后只有文字总结/后台通知/读命令则仍算 passing。
      - no_test : 根本没找到真实测试运行 → 补测。
    failing_ranges: failing 时,**整串收尾连续测试运行**(从最近这次往上,直到遇到一次完全成功
      的运行或非测试断点为止)各自的节点区间闭区间,供 addtool 删除;其它状态为空。删整串是因为
      收尾常是「连续跑几个部分套件」的调试尾巴,只删失败那次会让前面部分通过的运行被误当「最终
      测试」残留(实测 B0540B: node1926 test_authorization 20/0 紧接 node1928 test_notifications 0/1)。
    node_index: 命中的最近一次真跑所在 assistant 节点(仅供审计/日志)。
    """
    state: str
    failing_ranges: tuple[tuple[int, int], ...] = ()
    node_index: int | None = None

    @property
    def failing_range(self) -> tuple[int, int] | None:
        """最近一次失败运行的区间(向后兼容单区间调用)。"""
        return self.failing_ranges[-1] if self.failing_ranges else None


def _terminal_result_is_failing(result_text: str) -> bool:
    """一次测试运行的 RESULT 文本是否含明确失败信号。

    复用 `_ordinary_failure_reasons`(覆盖 `N failed`/`N tests failed`/`N failures`/`failures=N`/
    `errors=N`、失败输出、非零 exit)以吃到各框架的计数式失败(ctest `N tests failed out of M`、
    rspec `N examples, M failures`、unittest `FAILED (failures=N)` 等),而不仅是 has_failure_output。"""
    if not result_text:
        return False
    result_text = _strip_ansi(result_text)
    if _ordinary_failure_reasons(result_text):
        return True
    passed, failed = parse_test_counts(result_text)
    if failed and failed > 0:
        return True
    return False


def _terminal_result_is_fully_successful(result_text: str) -> bool:
    """一次测试运行的 RESULT 是否「完全成功」:有正向通过证据(passed>0)、无失败、非零测试。"""
    if not result_text:
        return False
    result_text = _strip_ansi(result_text)
    if _terminal_result_is_failing(result_text):
        return False
    passed, failed = parse_test_counts(result_text)
    strong_pass = bool(_STRONG_PASS_SUMMARY_RE.search(result_text))
    # 零测试否决:仅在**没有任何正向通过证据**时才因「零测试」判非成功。否则会被 go 多包输出里的
    # 逐包 `pkg [no test files]` 噪声误伤——整轮实际有其它包跑了测试并通过(`ok pkg 1.2s`/`RESULT: PASS`)。
    if has_zero_test_output(result_text) and not (passed and passed > 0) and not strong_pass:
        return False
    if passed and passed > 0 and not failed:
        return True
    # 无法抽出计数但含**肯定通过**汇总行(如 `OK (5 tests)`/pytest 点阵尾被截断)也算成功。
    # 用 _STRONG_PASS_SUMMARY_RE(剔除 `collected N items`/`Running N tests using` 等仅表示
    # 「开始/收集」的起始横幅),避免截断输出把失败误判为完全成功。
    if strong_pass:
        return True
    return False


def _terminal_tool_result_range(
    msgs: list, asst_index: int, call_id: str
) -> tuple[int, int]:
    """给定发起测试的 assistant 节点与 call_id,返回 (asst_index, 最后一个直属 tool 结果) 闭区间。

    区间只覆盖该 assistant + 紧随其后连续的 tool 结果节点(不吞掉后面的收尾 assistant),
    以便删除时保持 tool_call/tool 配对自洽。"""
    end = asst_index
    cursor = asst_index + 1
    saw_match = False
    while cursor < len(msgs) and msgs[cursor].get("role") == "tool":
        if str(msgs[cursor].get("tool_call_id", "")) == str(call_id):
            saw_match = True
        end = cursor
        cursor += 1
    if not saw_match:
        # 结果不在紧邻位置(后台/延迟回收)——只删 assistant 自身不安全,退回单节点区间。
        return (asst_index, asst_index)
    return (asst_index, end)


def _latest_genuine_test_run(msgs: list) -> tuple[int, str, str] | None:
    """从后往前找**最近一次真实测试运行**。

    返回 (assistant_node_index, tool_call_id, result_text);找不到返回 None。
    真实运行 = 该 assistant 的某个 Bash 工具调用 `genuine_test_exec` 命中(执行了正式测试),
    且其存在对应 tool 结果。用 genuine_test_exec 而非 is_test_command——后者漏掉 `npx vitest`、
    `bash path/test_x.sh`、`time bash run_tests.sh`、`for f in..;bash $f`、`docker compose exec ..pytest`
    等真实终态测试形态。"""
    runs = _all_genuine_test_runs(msgs)
    return runs[-1] if runs else None


def _has_substantial_nontest_work_between(
    msgs: list, lo_exclusive: int, hi_exclusive: int
) -> bool:
    """(lo_exclusive, hi_exclusive) 开区间内是否有「实质非测试工作」。

    实质非测试工作 = 某个 assistant 节点发起了会改代码/文件的工具(Write/Edit/MultiEdit/
    apply_patch/NotebookEdit)。用它把「边调试边连续跑测试」的收尾尾巴(相邻运行之间只有纯文字
    过渡或读文件)与「跑完一次测试后转去改代码/干别的」区分开:前者算连续(一起删),后者断开。
    只看写类工具而非任意 Bash,是因为收尾连续测试之间常穿插 cat/grep/登录探测等读命令,那些
    不构成「转去干别的」。"""
    for i in range(lo_exclusive + 1, hi_exclusive):
        m = msgs[i]
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        if _is_edit_message(m):
            return True
    return False


def _is_bg_launch_placeholder(text: str) -> bool:
    """一次 Bash 结果是否只是「后台任务已发起」的占位(真实测试输出稍后才通过通知/取回到达)。"""
    if not text:
        return False
    low = text.lower()
    return ("notified when it completes" in low
            or "running in background with id" in low
            or "command running in background" in low)


def _bg_task_id(text: str) -> str | None:
    m = re.search(r"background with ID:\s*([A-Za-z0-9_]+)", text)
    if m:
        return m.group(1)
    m = re.search(r"/([A-Za-z0-9_]+)\.output\b", text)
    return m.group(1) if m else None


def _resolve_background_result(msgs: list, launch_result: str) -> str | None:
    """后台发起的测试:用 task id 从后续 tool 节点(TaskOutput 取回)找到**完成后的真实结果**。

    形如 node136 发起 `pytest tests/` 到后台 → 直属结果只是「running in background with ID: X…
    notified when it completes」占位;真实结果在稍后的 TaskOutput 节点里(含 `<task_id>X</task_id>`
    `<status>completed</status>` `<output>…Pytest: 299 passed…</output>`)。取回它作为该次运行的结果,
    否则会把占位当成「未验证成功」误删已通过的后台测试。取最后一个匹配(last-wins)。"""
    tid = _bg_task_id(launch_result)
    if not tid:
        return None
    best: str | None = None
    for m in msgs:
        if not isinstance(m, dict) or m.get("role") != "tool":
            continue
        t = _msg_content_text(m.get("content"))
        if not t or _is_bg_launch_placeholder(t):
            continue
        if tid in t and ("<status>completed" in t
                         or "retrieval_status>success" in t
                         or "<output>" in t):
            best = t
    return best


def _all_genuine_test_runs(msgs: list) -> list[tuple[int, str, str]]:
    """按节点顺序返回所有真实测试运行 (assistant_node_index, tool_call_id, result_text)。

    同一 assistant 若有多个测试 Bash 调用,**任一非完全成功即用它代表该节点**(宁可重测不可
    漏失败:防「先跑全量失败、后跑单文件通过」在同一节点内被后者掩盖);全部成功则取最后一个。"""
    if not isinstance(msgs, list):
        return []
    results_by_id = {
        str(m.get("tool_call_id")): _msg_content_text(m.get("content"))
        for m in msgs
        if isinstance(m, dict) and m.get("role") == "tool"
    }
    out: list[tuple[int, str, str]] = []
    for i, m in enumerate(msgs):
        if not isinstance(m, dict) or m.get("role") != "assistant":
            continue
        node_hits: list[tuple[int, str, str]] = []
        for tc in m.get("tool_calls") or []:
            if not isinstance(tc, dict):
                continue
            fn = tc.get("function") if isinstance(tc.get("function"), dict) else {}
            if fn.get("name") != "Bash":
                continue
            a = fn.get("arguments", "")
            a = a if isinstance(a, str) else json.dumps(a, ensure_ascii=False)
            if not genuine_test_exec(obj_command(a)):
                continue
            call_id = str(tc.get("id") or "")
            res = results_by_id.get(call_id, "")
            if _is_bg_launch_placeholder(res):
                # 后台发起的测试:占位结果非结论性。取回完成结果;取不到则跳过本次(回退更早真跑)。
                resolved = _resolve_background_result(msgs, res)
                if resolved is None:
                    continue
                res = resolved
            node_hits.append((i, call_id, res))
        if node_hits:
            chosen = next(
                (h for h in node_hits if not _terminal_result_is_fully_successful(h[2])),
                node_hits[-1],
            )
            out.append(chosen)
    return out


def _latest_emergent_test_text(msgs: list, window: int) -> str | None:
    """回退路径:无 genuine Bash 测试命令时,取收尾窗口内**最近一次浮现式测试证据**的文本
    (子代理/后台回收的 tool 结果、或 USER 粘贴的测试输出),供成败判定。找不到返回 None。

    与 `tail_real_test` 的区别:后者只判「存在」,这里返回**文本**以便判成败——避免把失败/仅
    起始横幅的浮现证据无条件当成 passing(A1/A4:回退路径 false-pass)。"""
    if not isinstance(msgs, list):
        return None
    asst_idx = [i for i, m in enumerate(msgs)
                if isinstance(m, dict) and m.get("role") == "assistant"]
    if not asst_idx:
        return None
    tail = asst_idx[-window:]
    results = {m.get("tool_call_id"): _msg_content_text(m.get("content"))
               for m in msgs if isinstance(m, dict) and m.get("role") == "tool"}
    found: str | None = None
    for i in tail:
        for tc in msgs[i].get("tool_calls") or []:
            if not isinstance(tc, dict):
                continue
            fn = tc.get("function") if isinstance(tc.get("function"), dict) else {}
            name = fn.get("name", "")
            a = fn.get("arguments", "")
            a = a if isinstance(a, str) else json.dumps(a, ensure_ascii=False)
            res = results.get(tc.get("id"), "")
            if res and _STRONG_TEST_SUMMARY_RE.search(res) \
                    and not _tcd_reads_script_source(name, a):
                found = res
    for m in msgs[tail[0]:]:
        if isinstance(m, dict) and m.get("role") == "user":
            t = _msg_content_text(m.get("content"))
            if _STRONG_TEST_SUMMARY_RE.search(t):
                found = t
    return found


def terminal_test_state(
    msgs: list, window: int = FINAL_TEST_WINDOW
) -> TerminalTestState:
    """收尾成败口径:找**最近一次真实测试运行**并判定其成败(见 TerminalTestState)。

    不用硬性「最后 window 节点」判成败——大量会话在最后一次测试后还有几十个编辑节点,硬窗口
    会把失败测试挤出去误当「无测试」。改为从收尾总结节点往上回找最近一次真跑:失败/未验证成功
    →删掉整串收尾连续运行+重补;完全成功→不动;根本没真跑→补。`window` 仅用于 `tail_real_test`
    的存在性兜底(某些浮现式证据没有直接的 genuine Bash 命令时)。"""
    if not isinstance(msgs, list):
        return TerminalTestState(TERMINAL_NO_TEST)
    runs = _all_genuine_test_runs(msgs)
    if runs:
        node_index, call_id, res = runs[-1]
        if _terminal_result_is_fully_successful(res):
            # 口径B:最近一次真测全绿,但其后若还有代码 Edit(改了代码却没再测)→ 测试已过时(STALE),
            # 需补一次「改完之后」的成功测试(不删旧的通过测试)。其后只有文字总结/后台通知/读命令则
            # 仍算 passing。判据用 _is_edit_message(Write/Edit/MultiEdit/apply_patch/NotebookEdit)。
            tool_end = _terminal_tool_result_range(msgs, node_index, call_id)[1]
            if _has_substantial_nontest_work_between(msgs, tool_end, len(msgs)):
                return TerminalTestState(TERMINAL_STALE, node_index=node_index)
            return TerminalTestState(TERMINAL_PASSING, node_index=node_index)
        # 最近一次真跑「非完全成功」(明确失败,或空输出/零测试/无计数无强汇总的未验证成功)
        # → 收尾停在未通过的测试上。删掉**整串收尾连续运行**:从最近这次往前,把与它「连续」
        # 的运行都收进删除集。「连续」= 两次运行之间没有实质的非测试工作(相邻运行之间只隔各自的
        # tool 结果 / 纯文字过渡)——这是「边调试边一个接一个跑测试」的收尾尾巴,即使其中某次
        # 部分通过(如只跑了某个子集套件)也一并删,因为整段收尾并未验证全绿(实测 B0540B:
        # node1926 test_authorization 20/0 紧接 node1928 test_notifications 0/1,两次相邻,一起删)。
        # 一旦相邻两次运行之间夹了实质非测试工作(agent 跑完一次后就转去干别的),就在那里断开,
        # 保留更早的运行不动。
        ranges: list[tuple[int, int]] = []
        prev_start: int | None = None
        for r_node, r_cid, r_res in reversed(runs):
            r_range = _terminal_tool_result_range(msgs, r_node, r_cid)
            if prev_start is not None:
                if _has_substantial_nontest_work_between(msgs, r_range[1], prev_start):
                    break
            ranges.append(r_range)
            prev_start = r_range[0]
        ranges.sort()
        return TerminalTestState(TERMINAL_FAILING, failing_ranges=tuple(ranges),
                                 node_index=node_index)
    # 没有直接的 genuine Bash 测试命令:回退到浮现式证据(子代理/USER 粘贴/后台回收汇总)。
    # 但不能「存在即通过」——取最近一次浮现证据判成败:完全成功→passing;否则→no_test(补测)。
    # 浮现证据无 genuine 区间可删,失败也只补不删(删除仅针对 genuine Bash 失败簇)。
    emergent = _latest_emergent_test_text(msgs, window)
    if emergent is not None and _terminal_result_is_fully_successful(emergent):
        return TerminalTestState(TERMINAL_PASSING)
    return TerminalTestState(TERMINAL_NO_TEST)


def needs_final_test_oracle(data: dict, window: int = FINAL_TEST_WINDOW) -> bool:
    """确定性口径:收尾没有「完全成功」的测试(无真跑、或最近一次真跑失败/未验证成功)→ 需补测。"""
    msgs = data.get("messages", [])
    return terminal_test_state(msgs, window).state != TERMINAL_PASSING


def _range_is_pairing_safe(msgs: list, lo: int, hi: int) -> bool:
    """闭区间 [lo,hi] 删除后是否保持 tool_call/tool 配对自洽。

    要求:①区间内每个 assistant 发起的 tool_call 的结果都落在区间内(不留悬空调用);
    ②区间内每个 tool 结果对应的调用都在区间内(不留孤儿结果)。这样整段删掉不会破坏
    区间外的配对关系。"""
    if lo < 0 or hi >= len(msgs) or lo > hi:
        return False
    inside_call_ids: set[str] = set()
    inside_result_ids: set[str] = set()
    for i in range(lo, hi + 1):
        m = msgs[i]
        if not isinstance(m, dict):
            return False
        if m.get("role") == "assistant":
            for tc in m.get("tool_calls") or []:
                cid = str((tc or {}).get("id") or "")
                if cid:
                    inside_call_ids.add(cid)
        elif m.get("role") == "tool":
            rid = str(m.get("tool_call_id") or "")
            if rid:
                inside_result_ids.add(rid)
    # 区间内每个调用的结果都必须在区间内。
    for i in range(len(msgs)):
        m = msgs[i]
        if not isinstance(m, dict):
            continue
        if m.get("role") == "tool":
            rid = str(m.get("tool_call_id") or "")
            if rid and rid in inside_call_ids and not (lo <= i <= hi):
                return False  # 调用在区间内、结果在区间外 → 会留悬空调用
    # 区间内每个结果的调用都必须在区间内(否则删掉结果留下的是孤儿——但更常见的是调用在区间外)。
    for rid in inside_result_ids:
        if rid not in inside_call_ids:
            # 结果的调用在区间外:删掉结果会让区间外调用悬空(dangling)。不安全。
            return False
    return True


def _safe_deletable_ranges(
    msgs: list, ranges: Sequence[tuple[int, int]]
) -> list[tuple[int, int]]:
    """过滤出「删除后不破坏 tool_call/tool 配对」的失败测试区间。

    混合轮(同一 assistant 既发失败测试又发别的工具调用,或结果散落区间外)会被跳过——
    宁可不删也不产生 split-pair 的坏轨迹。"""
    safe: list[tuple[int, int]] = []
    for lo, hi in ranges:
        if _range_is_pairing_safe(msgs, lo, hi):
            safe.append((lo, hi))
    return safe


def _tail_is_plain_summary(msgs: list) -> bool:
    """轨迹是否以「纯文本收尾总结 assistant」结尾(无工具调用、有非空正文)。

    这是终态插入锚点的合法形态,也是 inspect_existing_insert 判「valid」的收尾条件。"""
    if not msgs:
        return False
    last = msgs[-1]
    return (
        isinstance(last, dict)
        and last.get("role") == "assistant"
        and not last.get("tool_calls")
        and bool(normalize_text(last.get("content")).strip())
    )


def _make_synthetic_closing_summary(msgs: list) -> dict[str, Any]:
    """合成一个纯文本收尾总结 assistant 节点(用于末尾缺总结时补锚点)。

    时间戳顺移到最后一条消息之后 +0.5s(缺失时不设),token 置零占位。正文是中性收尾句,
    终态插入后其上方是补测块;若后续 summary-merge 逻辑判定通过,会把「Verified by running…」
    验证句并进来。**插入进轨迹的正文必须是英文**(轨迹内容一律英文)。"""
    text = "Completed the changes above and ran the test suite to confirm the results."
    node: dict[str, Any] = {
        "role": "assistant",
        "agent": "main",
        "reasoning_content": "",
        "content": text,
        "tool_calls": [],
    }
    prev_ts = None
    for m in reversed(msgs):
        if isinstance(m, dict):
            meta = m.get("_metadata")
            if isinstance(meta, dict) and meta.get("timestamp"):
                prev_ts = parse_timestamp(meta.get("timestamp"))
                break
    if prev_ts is not None:
        node["_metadata"] = {
            "timestamp": format_timestamp(_to_aware(prev_ts) + timedelta(seconds=0.5)),
            "tokens": normalize_token_usage({}),
        }
    else:
        node["_metadata"] = {"tokens": normalize_token_usage({})}
    return node




def _tcd_sibling_subagent_evidence(path: Path) -> str:
    """扁平语料里，主轨迹常把测试委托给同前缀的 `__subagents__*.json`。扫描其中真实测试运行。"""
    name = path.name
    if "__subagents__" in name or "__" not in name:
        return ""
    stem = name[:-5]  # strip .json
    hits = []
    try:
        for sib in sorted(path.parent.glob(stem + "__subagents__*.json")):
            try:
                sd = json.loads(sib.read_text(encoding="utf-8"))
            except Exception:
                continue
            msgs = sd.get("messages", []) if isinstance(sd, dict) else []
            results = {m.get("tool_call_id"): (m.get("content") or "")
                       for m in msgs if m.get("role") == "tool"}
            for m in msgs:
                if m.get("role") != "assistant":
                    continue
                for tc in m.get("tool_calls") or []:
                    fn = tc.get("function", {})
                    a = fn.get("arguments", "")
                    a = a if isinstance(a, str) else json.dumps(a, ensure_ascii=False)
                    if fn.get("name") == "Bash" and looks_like_test_run(obj_command(a)):
                        res = results.get(tc.get("id"), "")
                        mt = _RESULT_TEST_EVID_RE.search(res or "")
                        if mt:
                            snip = res[max(0, mt.start()-40):mt.start()+80].replace("\n", " ")
                            hits.append(f"[{sib.name[-40:]}] {obj_command(a)[:70]} -> {snip}")
    except Exception:
        return ""
    if not hits:
        return ""
    uniq = list(dict.fromkeys(hits))[:12]
    return ("\n\n[子代理/压缩文件中的真实测试运行证据（与主轨迹属同一 session，委托给子代理执行）]\n  "
            + "\n  ".join(uniq))


def build_test_claim_detector_model(model_name: str | None = None):
    """惰性构造判官模型（复用 structure_check_script/model_config，channel=openai，默认 gpt-5.6）。

    仅在真正启用轨迹检测时调用；未安装 langchain-openai 时给出清晰报错。"""
    check_dir = Path(__file__).resolve().parents[1] / "structure_check_script"
    if str(check_dir) not in sys.path:
        sys.path.insert(0, str(check_dir))
    from model_config import build_chat_model, resolve_model_config  # noqa: E402
    cfg = resolve_model_config(
        model=model_name,
        timeout=TCD_MODEL_TIMEOUT_SECONDS,
        # 判官自带外层重试(TCD_JUDGE_RETRIES)，关掉 langchain/openai 内层重试，
        # 避免"外层×内层"倍增：最坏调用数从 (外+1)×(内+1) 收敛到 (外+1)。
        max_retries=TCD_MODEL_MAX_RETRIES,
    )
    return build_chat_model(cfg), cfg


def detect_test_claims_for_session(model, path: Path) -> dict:
    """对单条 session json 跑「收尾是否需要补测」检测（needs_final_test）。

    喂给判官"测试证据时间线"，解析 JSON，做 needs_final_test 的 LLM/oracle 融合。
    只判收尾窗口（倒数几个节点）是否已有完全通过的正式测试；不再做逐节点的谎报检测。"""
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    msgs = data.get("messages", [])
    evidence, asst_nodes = build_evidence(data)
    sib = _tcd_sibling_subagent_evidence(Path(path))
    if sib:
        evidence = evidence + sib
    task = get_task_context(data)
    user = TCD_USER_TEMPLATE.format(task=task, evidence=evidence)
    last_err = None
    for attempt in range(TCD_JUDGE_RETRIES + 1):
        try:
            resp = model.invoke(
                [("system", TCD_SYSTEM_PROMPT), ("human", user)],
                # 固定的 prompt_cache_key：判官每条 session 的 system 前缀完全相同(见
                # TCD_SYSTEM_PROMPT)，同一 key 让上游把这段长前缀路由到同一缓存分片，
                # 命中后 system 前缀按缓存价计费(usage 里 cached_tokens>0)。
                prompt_cache_key="rerun-test-v1",
            )
            parsed = _tcd_parse_json(resp.content if hasattr(resp, "content") else str(resp))
            if parsed is None:
                last_err = "json_parse_failed"
                # 空/不可解析 JSON(gpt-5.6 惰性典型表现)：退避后再试，避免无间隔连打全额调用。
                if attempt < TCD_JUDGE_RETRIES:
                    time.sleep(1.5 * (attempt + 1))
                continue
            llm_nft = parsed.get("needs_final_test", None)
            term = terminal_test_state(msgs, FINAL_TEST_WINDOW)
            oracle_nft = term.state != TERMINAL_PASSING
            # 融合(oracle 主导确定性信号):最近一次真测**失败**(FAILING)或**成功但其后改过代码**
            # (STALE,口径B)时,确定性 oracle 直接强制 needs_final=True——绝不让非确定性判官把
            # 「失败测试/过时测试」漏判成「已测无需补」。其余情形(no_test / passing)由判官优先
            # (它更懂「浮现式/委托式」成功证据),判官缺该字段时回退 oracle。
            if term.state in (TERMINAL_FAILING, TERMINAL_STALE):
                needs_final = True
            elif isinstance(llm_nft, bool):
                needs_final = llm_nft
            else:
                needs_final = oracle_nft
            return {
                "needs_final_test": needs_final,
                "final_test_reason": (parsed.get("final_test_reason") or "")[:500],
                "needs_final_test_oracle": oracle_nft,
                "terminal_test_state": term.state,
                "terminal_failing_range": (
                    list(term.failing_range) if term.failing_range else None
                ),
                "n_assistant_nodes": len(asst_nodes),
                "evidence_chars": len(evidence),
            }
        except Exception as e:  # noqa: BLE001
            last_err = str(e)[:200]
            time.sleep(1.5 * (attempt + 1))
    return {"needs_final_test": None, "error": last_err}


# 判官模型按模型名缓存并共享给所有 repo-chain 线程（langchain ChatOpenAI 的 .invoke 可并发）。
# 首次构造时若 langchain-openai 缺失，错误缓存为异常字符串，后续不再反复 import。
_tcd_model_lock = threading.Lock()
_tcd_model_cache: dict[str, Any] = {}


def get_test_claim_detector_model(model_name: str | None = None):
    """线程安全地获取（并缓存）判官模型。返回 (model, cfg)。构造失败会抛出。"""
    key = model_name or "__default__"
    with _tcd_model_lock:
        cached = _tcd_model_cache.get(key)
        if isinstance(cached, Exception):
            raise cached
        if cached is None:
            try:
                cached = build_test_claim_detector_model(model_name)
            except Exception as exc:  # noqa: BLE001 —— 缓存失败，避免每条 session 反复重试构造
                _tcd_model_cache[key] = exc
                raise
            _tcd_model_cache[key] = cached
        return cached


class DetectorUnavailableError(RuntimeError):
    """LLM 测试声明判官不可用时抛出（fail-closed）。

    产品要求「补测试的唯一判定方式是经过大模型的判定」，因此判官不可用/失败时不得静默
    降级；该 session 判为失败进入失败分流，等判官恢复后重跑。"""


def _oracle_only_detection(path: Path) -> dict | None:
    """LLM 不可用时的（非严格）兜底：**仍用确定性 oracle**（terminal_test_state /
    needs_final_test_oracle）判断收尾是否需要补测，绝不退回正则关键字启发式。"""
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
    except Exception:
        return None
    term = terminal_test_state(data.get("messages", []))
    oracle_nft = term.state != TERMINAL_PASSING
    return {
        "needs_final_test": oracle_nft,
        "final_test_reason": "deterministic oracle (LLM judge unavailable): "
                             + ("no fully-successful test in final window"
                                if oracle_nft
                                else "fully-successful test detected in final window"),
        "needs_final_test_oracle": oracle_nft,
        "terminal_test_state": term.state,
        "terminal_failing_range": (
            list(term.failing_range) if term.failing_range else None
        ),
        "source": "oracle",
    }


def detect_source_session_claims(
    source_session: "SourceSession | None",
    *,
    model_name: str | None = None,
    strict_llm: bool = True,
) -> dict | None:
    """对一条 source session 跑「是否需要加测试」判断（供 STEP1 profile 选择用）。

    判断**只**采用 detect_test_claims.py 的 **LLM 判官**（detect_test_claims_for_session）。
    产品要求「补测试的唯一判定方式是经过大模型的判定」——因此 `strict_llm=True`（默认）时，
    判官不可用/失败即 **fail-closed**：抛出 `DetectorUnavailableError`，让该 session 进失败分流
    等判官恢复后重跑，**绝不**静默退回确定性 oracle 或正则（那会漏判需要补测的 session）。

    仅当显式 `strict_llm=False`（如 dry-run 预览列表，不做金标决策）时，才回退到
    detect_test_claims.py 自带的确定性 oracle 以避免中断展示。返回值带
    "source": "llm" | "oracle"，或在 fail-closed 时抛异常。
    """
    if source_session is None:
        return None
    try:
        model, _cfg = get_test_claim_detector_model(model_name)
        result = detect_test_claims_for_session(model, source_session.path)
        if result.get("error") and result.get("needs_final_test") is None:
            # 判官彻底失败：fail-closed（严格）或 oracle 兜底（仅预览）。
            if strict_llm:
                raise DetectorUnavailableError(
                    f"LLM 判官对 {source_session.path.name} 判定失败: "
                    f"{result.get('error')}"
                )
            print(
                f"[detect-test-claims] 判官失败，(非严格)改用 detect_test_claims 确定性 oracle: "
                f"{source_session.path.name}: {result.get('error')}",
                file=sys.stderr,
                flush=True,
            )
            return _oracle_only_detection(source_session.path)
        result.setdefault("source", "llm")
        return result
    except DetectorUnavailableError:
        raise
    except Exception as exc:  # noqa: BLE001
        if strict_llm:
            # fail-closed：唯一判定方式必须是大模型；判官不可用则该 session 判为失败。
            raise DetectorUnavailableError(
                f"LLM 判官不可用（{source_session.path.name}）: {str(exc)[:200]}"
            ) from exc
        print(
            f"[detect-test-claims] 判官不可用，(非严格)改用 detect_test_claims 确定性 oracle: "
            f"{source_session.path.name}: {str(exc)[:200]}",
            file=sys.stderr,
            flush=True,
        )
        return _oracle_only_detection(source_session.path)


def format_detector_findings_for_prompt(detector_result: dict | None) -> str:
    """把检测结果渲染成注入 Claude prompt 的具体指令段（无信号时返回空串）。

    只处理终态补测（needs_final_test）：判官判定收尾窗口没有完全通过的正式测试时，
    指示 claude 跑一次干净通过的收尾测试。"""
    if not detector_result:
        return ""
    if not bool(detector_result.get("needs_final_test")):
        return ""
    # NB: deliberately do NOT inject the detector's final_test_reason here — the judge
    # reasons in Chinese, and everything in this prompt (and therefore in the trajectory
    # Claude produces) must be English. The reason stays in the manifest for audit only.
    return "\n".join([
        "",
        "Precise trajectory audit of the SOURCE session (LLM detector, treat as evidence to act on):",
        "- The source session did NOT end on a fully-successful formal test in its final window "
        "(needs_final_test=true). Before finishing, run the "
        "discovered test runner one final time and keep fixing the underlying bug and rerunning "
        "until the FULL runner ends with zero failures (all green). Only finish once the final "
        "run is fully passing — a run that still has any failure is not acceptable as the final test.",
    ])


