#!/usr/bin/env python3
"""Find repo test runners and ask Claude Code to produce test trajectories.

The script is intended for TASK directories that look like:

    TASK-.../
      metadata.json
      repo/
        run_tests.sh  (or runtest, run_test.*, test.sh, ...)

By default, each source sessions/*.json file becomes one Claude Code job.  The
script extracts deterministic context from that source session, builds a
session-specific test prompt, saves Claude's stream-json output, copies any
detected native Claude JSONL session, and writes a manifest with
source-to-target session mappings for later conversion.
"""

