# 永久挂起(docker 拉镜像/测试卡死时)。改用一个固定硬上限做死锁兜底：默认 30 分钟，
# 与 --timeout-seconds 的默认值一致——单次 claude 运行超过 30 分钟即视为卡住、直接放弃
# 该 session(判 INCOMPLETE_TRACE/STEP1_TIMEOUT，流水线继续下一条)。需要更长可用 env 覆盖。
HARD_MAX_CLAUDE_TIMEOUT_SECONDS = int(
    os.environ.get("RUNTEST_HARD_MAX_TIMEOUT_SECONDS") or 30 * 60
)


def _resolve_claude_timeout_seconds(raw: int | None) -> int:
    """把用户传入的 --timeout-seconds 归一为一个**有限**的秒数。

    0 / 负数 / None(旧语义"不限") → 硬上限兜底(默认 30 分钟)，杜绝 communicate(timeout=None)
    永久挂起；正数 → 原样返回。"""
    if raw and raw > 0:
        return int(raw)
    return HARD_MAX_CLAUDE_TIMEOUT_SECONDS
