@dataclass
class ClaudeRunResult:
    task_dir: Path
    repo_dir: Path
    work_repo_dir: Path
    test_runner: Path
    work_test_runner: Path
    output_dir: Path
    command: list[str]
    prompt_profile: str
    prompt_profile_reasons: list[str] = field(default_factory=list)
    source_session: SourceSession | None = None
    source_session_extract_path: Path | None = None
